window.DATA = [{"id":"ik","short":"ИК","name":"ИК вопросы","title":"Ответы по новейшей истории Узбекистана","subtitle":"178 вопросов в порядке исходного списка","tickets":false,"items":[{"n":1,"q":"Предмет цели и задачи дисциплины Новейшая история Узбекистана","a":["Предмет изучает путь Узбекистана к независимости и развитие страны в период самостоятельной государственности. Рассматриваются политические, экономические, социальные и культурные изменения, а также международные отношения. Цель курса состоит в понимании причин событий, их последовательности и последствий. Важно уметь работать с источниками и отличать подтвержденные факты от оценок"]},{"n":2,"q":"Роль предмета в воспитании гармонично развитого поколения","a":["Изучение истории помогает молодежи понимать свою страну, ее культуру и путь развития. Оно развивает уважение к людям разных национальностей, чувство ответственности и интерес к общественной жизни. Разбор исторических решений учит видеть связь между поступками и их последствиями. Для полноценного образования важны не только знания о достижениях, но и обсуждение трудностей и ошибок"]},{"n":3,"q":"Роль исторической памяти в воспитании духовно зрелой личности","a":["Историческая память представляет собой сохранение знаний о прошлом семьи, народа и страны. Она поддерживается через образование, архивы, памятники, музеи и семейные рассказы. Память помогает понимать происхождение традиций и ценить опыт предыдущих поколений. При этом рассказы о прошлом нужно сопоставлять с документами, чтобы не принимать мифы за факты"]},{"n":4,"q":"Социально экономическая и политическая ситуация во второй половине 1980 х годов","a":["Узбекистан оставался частью СССР и зависел от союзного центра в политике и экономике. Хозяйство было сильно связано с выращиванием хлопка, что ограничивало разнообразие производства и усиливало экологические проблемы. На фоне перестройки обострились дефицит товаров, социальные трудности и недоверие к власти. Гласность сделала более открытым обсуждение языка, исторического наследия и самостоятельности республики"]},{"n":5,"q":"Ферганские события 1989 года причины и последствия","a":["В июне 1989 года в Ферганской долине произошли массовые столкновения и насилие, от которых особенно пострадали турки-месхетинцы. Среди причин называют накопленные социальные проблемы, нехватку жилья и работы, межэтническую напряженность и недостаточную реакцию властей. События привели к гибели людей, разрушениям и переселению значительной части пострадавшего населения. Они показали необходимость защиты граждан и предотвращения межнациональных конфликтов"]},{"n":6,"q":"Рост общественной и политической активности в конце 1980 х годов","a":["Рост активности был связан с перестройкой, гласностью и ослаблением прежнего контроля над общественными обсуждениями. Люди открыто поднимали вопросы языка, экологии, социальной справедливости и национального наследия. Экономические трудности усиливали запрос на изменения. Появлялись общественные движения и новые формы участия граждан в политической жизни"]},{"n":7,"q":"События ГКЧП и их влияние на Узбекистан","a":["С 19 по 21 августа 1991 года группа советских руководителей попыталась сохранить прежнюю систему власти через создание Государственного комитета по чрезвычайному положению. Попытка переворота провалилась и ускорила распад союзных структур. В республиках усилилось стремление самостоятельно решать вопросы власти и развития. В Узбекистане вскоре после этих событий была провозглашена государственная независимость"]},{"n":8,"q":"Ислам Каримов первый Президент Узбекистана","a":["Ислам Каримов стал первым Президентом Узбекской ССР 24 марта 1990 года. После провозглашения независимости он был избран Президентом Республики Узбекистан на выборах 29 декабря 1991 года. При нем формировались государственные институты, принимались Конституция и символы, проводился постепенный переход к рыночной экономике. Он возглавлял страну до 2016 года, а его правление также связано с высокой централизацией власти"]},{"n":9,"q":"Декларация о независимости и ее историческое значение","a":["Декларация о государственном суверенитете Узбекской ССР была принята 20 июня 1990 года. Она закрепляла право республики самостоятельно определять важнейшие вопросы своей жизни и утверждала приоритет ее суверенных полномочий. Этот документ стал важным шагом к независимости. Его нужно отличать от провозглашения полной государственной независимости 31 августа 1991 года"]},{"n":10,"q":"Узбекская модель развития и ее особенности","a":["Узбекской моделью называют подход к переходу от плановой экономики к рынку, сформулированный в начале независимости. Обычно выделяют пять принципов: приоритет экономики над политикой, ведущую роль государства в реформах, верховенство закона, сильную социальную политику и постепенность преобразований. Предполагалось избегать резкого разрушения хозяйственных связей. При этом постепенность сопровождалась длительным сохранением значительного государственного контроля"]},{"n":11,"q":"Исторический путь обеспечения экономической независимости","a":["Экономическая независимость означала создание собственных финансовых институтов и уменьшение зависимости от прежних союзных поставок. Важными шагами стали введение национальной валюты сум 1 июля 1994 года, развитие банковской системы и расширение собственной промышленности. Большое внимание уделялось продовольствию, энергетике и транспортным связям. При этом экономическая самостоятельность не исключает торговли и сотрудничества с другими странами"]},{"n":12,"q":"Принятие Конституции и ее историческое значение","a":["Первая Конституция независимого Узбекистана была принята 8 декабря 1992 года. Она определила основы государственного строя, права граждан и устройство органов власти. Новая редакция была принята на референдуме 30 апреля 2023 года и вступила в силу 1 мая 2023 года. Конституция является правовой основой государства, но ее нормы должны обеспечиваться реальной работой государственных органов и судов"]},{"n":13,"q":"Принятие государственных символов","a":["Государственный флаг был принят 18 ноября 1991 года, герб 2 июля 1992 года, а гимн 10 декабря 1992 года. Музыку гимна написал Муталь Бурханов, слова Абдулла Арипов. Символы выражают самостоятельность страны, ее исторические традиции и общность граждан. Их используют в официальной жизни, государственных учреждениях и международных отношениях"]},{"n":14,"q":"Принцип разделения властей","a":["Разделение властей означает различие законодательной, исполнительной и судебной функций. Олий Мажлис принимает законы и осуществляет парламентский контроль, исполнительные органы организуют их выполнение, а суды разрешают споры и защищают права. Органы власти должны взаимодействовать и ограничивать возможность злоупотреблений. Само наличие разных учреждений еще не заменяет их реальной самостоятельности и ответственности"]},{"n":15,"q":"Формирование многопартийной системы проблемы и пути их решения","a":["После независимости начала формироваться правовая основа деятельности политических партий и выборов на многопартийной основе. Партии должны представлять интересы разных групп, предлагать программы и выдвигать кандидатов. В учебный период действовали пять зарегистрированных партий, включая УзЛиДеП, НДПУ, «Адолат», «Миллий тикланиш» и Экологическую партию. Основные задачи развития системы связаны с содержательной конкуренцией, открытостью и подотчетностью избирателям"]},{"n":16,"q":"Парламентские реформы","a":["В первые годы независимости создавались основы национального парламентаризма. После реформ парламент стал двухпалатным: с 2005 года работают Законодательная палата и Сенат. Позже расширялись формы парламентского контроля и участия в формировании правительства. На выборах 2024 года для Законодательной палаты впервые применили смешанную систему, сочетающую выборы по округам и партийным спискам"]},{"n":17,"q":"Становление и структура исполнительной власти","a":["Исполнительная власть организует повседневное управление, выполнение законов и государственных программ. На общегосударственном уровне важную роль играет Кабинет Министров во главе с Премьер-министром, в систему также входят министерства и ведомства. На местах действуют хокимы и подчиненные им исполнительные структуры. В ходе реформ менялись состав органов, их полномочия и порядок отчетности"]},{"n":18,"q":"Судебная реформа","a":["Цель судебной реформы состоит в укреплении независимости суда, защите прав человека и повышении доступности правосудия. К важным изменениям относятся отмена смертной казни с 2008 года, развитие судебного контроля за ограничением свободы и создание административных судов. Расширялись электронные сервисы и открытость судебной информации. Результат реформ зависит от справедливого рассмотрения дел и исполнения судебных решений"]},{"n":19,"q":"Роль СМИ в демократизации общества","a":["СМИ сообщают гражданам о событиях и решениях власти, объясняют общественные проблемы и дают возможность обсуждать их. Журналистские расследования могут выявлять нарушения и способствовать общественному контролю. Для этой роли необходимы доступ к информации, свобода выражения мнений и безопасность журналистов. Качество работы СМИ также зависит от проверки фактов и ответственности за достоверность сообщений"]},{"n":20,"q":"Либерализация общественной жизни достижения и проблемы","a":["Либерализация означает расширение свобод, открытости и возможностей самостоятельного участия людей в общественной жизни. В Узбекистане этот процесс связан с развитием общественных обсуждений, электронных обращений и более открытого освещения ряда проблем. Одновременно сохраняются вопросы реальной конкуренции, независимости общественных институтов и защиты свободы слова. Поэтому оценивать нужно конкретные изменения и их практические результаты"]},{"n":21,"q":"Негосударственные некоммерческие организации и их роль","a":["Негосударственные некоммерческие организации создаются для общественно полезных целей, а не для распределения прибыли между участниками. Они могут заниматься образованием, благотворительностью, защитой интересов людей, экологией и помощью уязвимым группам. Их роль состоит в выявлении общественных потребностей и участии граждан в решении проблем. Для эффективной работы важны прозрачность, самостоятельность и понятные правила деятельности"]},{"n":22,"q":"Местное самоуправление и его актуальные проблемы","a":["Махалля является формой самоорганизации жителей по месту проживания, а ее сход граждан относится к органам самоуправления. Она участвует в поддержке семей, общественной жизни, благоустройстве и выявлении местных проблем. Самоуправление нужно отличать от местных исполнительных органов во главе с хокимом. Основные трудности связаны с достаточностью ресурсов, самостоятельностью решений и недопущением чрезмерной нагрузки на активистов"]},{"n":23,"q":"Государственная молодежная политика","a":["Молодежная политика направлена на создание условий для образования, занятости, здоровья и участия молодых людей в жизни общества. Она включает профессиональное обучение, поддержку инициатив, спорт, культуру и профилактику социальных проблем. Важным документом стал Закон о государственной молодежной политике 2016 года. Эффективность такой политики оценивают по доступности возможностей и реальным результатам для молодежи"]},{"n":24,"q":"Рыночная инфраструктура и структурные изменения экономики","a":["Рыночная инфраструктура включает банки, биржи, страхование, транспорт, связь и учреждения, которые помогают обмену товарами и услугами. После независимости Узбекистан постепенно переходил от планового распределения к рыночным механизмам. Структурные изменения связаны с развитием промышленности, услуг, частного бизнеса и переработки сырья. Важная задача состоит в том, чтобы рост создавал производительные рабочие места и устойчивые доходы"]},{"n":25,"q":"Аграрные реформы задачи и направления","a":["Аграрные реформы изменяли организацию сельского хозяйства и условия работы производителей. Развивались фермерские и дехканские хозяйства, менялись механизмы закупок, расширялись выращивание разных культур и переработка продукции. Важные задачи включают повышение урожайности, водосбережение и защиту интересов работников. Для отрасли особенно значимы состояние почв, доступ к воде и предсказуемые правила землепользования"]},{"n":26,"q":"Проблемы развития малого бизнеса и частного предпринимательства","a":["Малый бизнес создает рабочие места, расширяет выбор товаров и услуг и помогает развитию регионов. Для его поддержки упрощались некоторые процедуры регистрации, налогообложения и получения государственных услуг. Основные трудности связаны с доступом к финансированию, инфраструктуре и рынкам, а также с административными барьерами. Устойчивое развитие требует честной конкуренции, защиты собственности и понятных правил"]},{"n":27,"q":"Развитие и перспективы промышленного производства","a":["В независимом Узбекистане развивались автомобилестроение, текстиль, химическая, горно-металлургическая и другие отрасли. Важным направлением стало увеличение переработки местного сырья внутри страны. Перспективы связаны с современными технологиями, повышением производительности, подготовкой кадров и выходом на внешние рынки. Одновременно нужно снижать загрязнение и обеспечивать предприятия надежной энергией"]},{"n":28,"q":"Мировой финансовый кризис и преодоление его последствий","a":["Мировой финансовый кризис 2008 года ухудшил условия торговли, инвестиций и кредитования во многих странах. Для Узбекистана риски были связаны с внешним спросом, экспортными доходами и денежными переводами. Антикризисные меры включали поддержку банков, предприятий, инфраструктурных проектов и занятости. Ограниченная вовлеченность финансовой системы в мировые рынки смягчала часть прямых рисков, но не устраняла внешнее влияние"]},{"n":29,"q":"Физическая культура и спорт в годы независимости","a":["После независимости Узбекистан стал самостоятельно участвовать в международных спортивных организациях и соревнованиях. Развивались спортивные школы, массовые занятия, детский и женский спорт. Международные успехи особенно заметны в боксе, дзюдо, борьбе и ряде других дисциплин. Для общества важны не только медали, но и доступность безопасной физической активности для людей разных возрастов"]},{"n":30,"q":"Реформы образования достижения и проблемы","a":["После независимости менялись содержание образования, структура подготовки кадров и сеть учебных заведений. Важными этапами стали Закон об образовании и Национальная программа подготовки кадров 1997 года, а затем новый Закон об образовании 2020 года. Расширялись дошкольное и высшее образование, обновлялись программы и цифровые средства. Среди проблем остаются качество подготовки, различия между регионами, нагрузка на педагогов и связь обучения с практикой"]},{"n":31,"q":"Сильная социальная политика и ее значение","a":["Сильная социальная политика направлена на защиту людей от бедности и тяжелых жизненных обстоятельств. Она включает пенсии, пособия, социальные услуги, поддержку занятости, доступ к образованию и здравоохранению. Помощь должна учитывать реальные потребности семьи и быть доступной без лишних препятствий. Ее цель состоит не только во временной поддержке, но и в создании условий для самостоятельного дохода"]},{"n":32,"q":"Реформы здравоохранения","a":["Реформы здравоохранения связаны с развитием первичной помощи, скорой медицинской помощи, профилактики и специализированного лечения. Создавались новые учреждения, обновлялось оборудование, расширялись цифровые сервисы. Важные задачи включают подготовку кадров, доступность лекарств и уменьшение различий между городом и селом. Оценивать систему следует по качеству и своевременности помощи, а не только по числу построенных объектов"]},{"n":33,"q":"Борьба с коррупцией как приоритет реформ","a":["Коррупция означает использование должностных возможностей для личной выгоды и наносит ущерб доверию, бюджету и равным возможностям. В Узбекистане принят Закон о противодействии коррупции 2017 года, а в 2020 году создано Антикоррупционное агентство. Важны прозрачные закупки, открытые данные, цифровые услуги и предупреждение конфликта интересов. Наказание должно сочетаться с независимым контролем и условиями, которые затрудняют злоупотребления"]},{"n":34,"q":"Народные приемные и диалог с населением","a":["Виртуальная и Народные приемные Президента созданы для приема обращений и выявления проблем граждан. Через них можно сообщать о нарушениях, трудностях получения услуг и местных проблемах. Такой механизм помогает органам власти видеть повторяющиеся причины жалоб. Его результативность зависит от качества ответа, реального решения вопроса и возможности проверить исполнение"]},{"n":35,"q":"Принцип от сильного государства к сильному гражданскому обществу","a":["Принцип означает постепенное расширение самостоятельного участия граждан и общественных организаций в решении общих вопросов. Государство должно обеспечивать законность и права, а общество должно иметь возможность контролировать власть и защищать свои интересы. Для этого развивают самоуправление, ННО, СМИ и формы общественного обсуждения. Передача задач обществу должна сопровождаться правами, ресурсами и ответственностью"]},{"n":36,"q":"Возрождение национальных ценностей и традиций","a":["После независимости расширилось внимание к родному языку, историческим памятникам, народным праздникам и обычаям. В общественной жизни укрепилось празднование Навруза, возрос интерес к традиционным ремеслам и семейному наследию. Возрождение означает сохранение культурной памяти и передачу ее новым поколениям. Оно должно сочетаться с уважением к многообразию страны и правам каждого человека"]},{"n":37,"q":"Восстановление исторического наследия великих ученых","a":["В годы независимости расширились исследования и популяризация трудов аль-Хорезми, аль-Фергани, аль-Бируни, Ибн Сины, Мирзо Улугбека и других ученых. Проводились юбилейные мероприятия, издавались труды, развивались музеи и научные центры. Их наследие показывает историческую связь региона с мировой наукой. Для его сохранения нужны качественные переводы, изучение рукописей и доступ к источникам"]},{"n":38,"q":"Избирательная система реформы и их цели","a":["Избирательная система определяет, как граждане выбирают органы власти и как голоса превращаются в депутатские места. На выборах 2024 года Законодательная палата избиралась по смешанной системе: 75 депутатов по одномандатным округам и 75 по партийным спискам. Цель изменений состоит в соединении связи депутата с территорией и представительства партийных программ. Важными условиями остаются свободное волеизъявление, понятные процедуры и прозрачный подсчет"]},{"n":39,"q":"Развитие туризма и его перспективы","a":["Туристический потенциал Узбекистана связан с Самаркандом, Бухарой, Хивой, природой, ремеслами и современной культурой. Упрощение въезда для многих стран и развитие транспорта помогали расширять туристические связи. Перспективны культурный, экологический, гастрономический и внутренний туризм. Развитие отрасли требует качества услуг, сохранения памятников и учета интересов местных жителей"]},{"n":40,"q":"Наука и перспективы инновационного развития","a":["Наука помогает создавать новые знания, технологии и способы решения общественных задач. После независимости менялись система научных учреждений, финансирование исследований и подготовка кадров. Инновационное развитие связано с применением исследований в производстве, медицине, сельском хозяйстве и цифровой сфере. Для этого нужны качественное образование, оборудование, научная добросовестность и сотрудничество с международными коллегами"]},{"n":41,"q":"Традиция наименования годов и ее цель","a":["В Узбекистане годам присваивают названия, которые выделяют общественно значимое направление работы. Название сопровождается государственной программой с задачами, ответственными органами и мероприятиями. Например, 2025 год был объявлен Годом охраны окружающей среды и зеленой экономики. Смысл этой практики состоит в концентрации внимания и ресурсов, а результаты нужно оценивать по выполнению конкретных задач"]},{"n":42,"q":"Реформы высшего образования и их перспективы","a":["Реформы высшего образования связаны с расширением доступа, открытием новых вузов и филиалов, развитием негосударственных учреждений и международного сотрудничества. Внедрялись кредитно-модульный подход и цифровые сервисы, увеличивалось внимание к научной работе. Главные задачи включают качество преподавания, практические навыки и честную оценку знаний. Рост числа студентов должен сопровождаться достаточным количеством подготовленных преподавателей и учебных ресурсов"]},{"n":43,"q":"Отношения государства и религии","a":["Конституция определяет Узбекистан как светское государство и закрепляет свободу совести. Это означает право исповедовать любую религию или не исповедовать никакой, при равенстве граждан перед законом. Религиозные организации отделены от государства и действуют в рамках законодательства. Важны уважение к верующим и неверующим, межрелигиозный диалог и защита от принуждения"]},{"n":44,"q":"Цели и задачи дисциплины Новейшая история Узбекистана","a":["Предмет изучает путь Узбекистана к независимости и развитие страны в период самостоятельной государственности. Рассматриваются политические, экономические, социальные и культурные изменения, а также международные отношения. Цель курса состоит в понимании причин событий, их последовательности и последствий. Важно уметь работать с источниками и отличать подтвержденные факты от оценок"]},{"n":45,"q":"Теоретические и методологические основы предмета","a":["Курс опирается на историзм, последовательность событий, анализ причин и сопоставление источников. Историзм требует рассматривать событие в условиях его времени, а не только с позиции сегодняшнего дня. Используются документы, статистика, воспоминания, архивы и научные исследования. Выводы должны учитывать надежность источника, возможную предвзятость и разные объяснения событий"]},{"n":46,"q":"Роль предмета в воспитании гармонично развитого поколения","a":["Изучение истории помогает молодежи понимать свою страну, ее культуру и путь развития. Оно развивает уважение к людям разных национальностей, чувство ответственности и интерес к общественной жизни. Разбор исторических решений учит видеть связь между поступками и их последствиями. Для полноценного образования важны не только знания о достижениях, но и обсуждение трудностей и ошибок"]},{"n":47,"q":"Ситуация в Узбекистане во второй половине 1980 х годов","a":["Узбекистан оставался частью СССР и зависел от союзного центра в политике и экономике. Хозяйство было сильно связано с выращиванием хлопка, что ограничивало разнообразие производства и усиливало экологические проблемы. На фоне перестройки обострились дефицит товаров, социальные трудности и недоверие к власти. Гласность сделала более открытым обсуждение языка, исторического наследия и самостоятельности республики"]},{"n":48,"q":"Ферганские события 1989 года причины и последствия","a":["В июне 1989 года в Ферганской долине произошли массовые столкновения и насилие, от которых особенно пострадали турки-месхетинцы. Среди причин называют накопленные социальные проблемы, нехватку жилья и работы, межэтническую напряженность и недостаточную реакцию властей. События привели к гибели людей, разрушениям и переселению значительной части пострадавшего населения. Они показали необходимость защиты граждан и предотвращения межнациональных конфликтов"]},{"n":49,"q":"Рост общественной и политической активности в конце 1980 х годов","a":["Рост активности был связан с перестройкой, гласностью и ослаблением прежнего контроля над общественными обсуждениями. Люди открыто поднимали вопросы языка, экологии, социальной справедливости и национального наследия. Экономические трудности усиливали запрос на изменения. Появлялись общественные движения и новые формы участия граждан в политической жизни"]},{"n":50,"q":"Попытки сохранить Советский Союз события ГКЧП и их влияние","a":["В условиях кризиса СССР обсуждалось обновление отношений между союзными республиками и подготовка нового Союзного договора. На референдуме в марте 1991 года ставился вопрос о сохранении обновленного Союза. Попытка переворота ГКЧП в августе сорвала политический процесс и ускорила распад союзной системы. В Узбекистане усилился курс на самостоятельность, а 31 августа была провозглашена государственная независимость"]},{"n":51,"q":"Декларация о независимости и ее историческое значение","a":["Декларация о государственном суверенитете Узбекской ССР была принята 20 июня 1990 года. Она закрепляла право республики самостоятельно определять важнейшие вопросы своей жизни и утверждала приоритет ее суверенных полномочий. Этот документ стал важным шагом к независимости. Его нужно отличать от провозглашения полной государственной независимости 31 августа 1991 года"]},{"n":52,"q":"Провозглашение государственной независимости","a":["31 августа 1991 года была провозглашена государственная независимость Республики Узбекистан и принят Закон об основах государственной независимости. 1 сентября установлено Днем независимости. На референдуме 29 декабря 1991 года население поддержало независимость. Эти решения создали правовую основу самостоятельного государства и его международного признания"]},{"n":53,"q":"Укрепление государственного суверенитета в первые годы независимости","a":["Для укрепления суверенитета создавались собственные органы управления, правовая система, вооруженные силы и дипломатическая служба. Были приняты государственные символы и Конституция, введена национальная валюта. Узбекистан устанавливал отношения с другими странами и вступал в международные организации. Важной задачей было сохранение управляемости и хозяйственных связей в условиях распада СССР"]},{"n":54,"q":"Обеспечение экономической независимости","a":["Экономическая независимость означала создание собственных финансовых институтов и уменьшение зависимости от прежних союзных поставок. Важными шагами стали введение национальной валюты сум 1 июля 1994 года, развитие банковской системы и расширение собственной промышленности. Большое внимание уделялось продовольствию, энергетике и транспортным связям. При этом экономическая самостоятельность не исключает торговли и сотрудничества с другими странами"]},{"n":55,"q":"Формирование многопартийной системы проблемы и решения","a":["После независимости начала формироваться правовая основа деятельности политических партий и выборов на многопартийной основе. Партии должны представлять интересы разных групп, предлагать программы и выдвигать кандидатов. В учебный период действовали пять зарегистрированных партий, включая УзЛиДеП, НДПУ, «Адолат», «Миллий тикланиш» и Экологическую партию. Основные задачи развития системы связаны с содержательной конкуренцией, открытостью и подотчетностью избирателям"]},{"n":56,"q":"Парламентские реформы","a":["В первые годы независимости создавались основы национального парламентаризма. После реформ парламент стал двухпалатным: с 2005 года работают Законодательная палата и Сенат. Позже расширялись формы парламентского контроля и участия в формировании правительства. На выборах 2024 года для Законодательной палаты впервые применили смешанную систему, сочетающую выборы по округам и партийным спискам"]},{"n":57,"q":"Становление и структура исполнительной власти","a":["Исполнительная власть организует повседневное управление, выполнение законов и государственных программ. На общегосударственном уровне важную роль играет Кабинет Министров во главе с Премьер-министром, в систему также входят министерства и ведомства. На местах действуют хокимы и подчиненные им исполнительные структуры. В ходе реформ менялись состав органов, их полномочия и порядок отчетности"]},{"n":58,"q":"Судебная реформа","a":["Цель судебной реформы состоит в укреплении независимости суда, защите прав человека и повышении доступности правосудия. К важным изменениям относятся отмена смертной казни с 2008 года, развитие судебного контроля за ограничением свободы и создание административных судов. Расширялись электронные сервисы и открытость судебной информации. Результат реформ зависит от справедливого рассмотрения дел и исполнения судебных решений"]},{"n":59,"q":"Роль СМИ в демократизации общества","a":["СМИ сообщают гражданам о событиях и решениях власти, объясняют общественные проблемы и дают возможность обсуждать их. Журналистские расследования могут выявлять нарушения и способствовать общественному контролю. Для этой роли необходимы доступ к информации, свобода выражения мнений и безопасность журналистов. Качество работы СМИ также зависит от проверки фактов и ответственности за достоверность сообщений"]},{"n":60,"q":"Негосударственные некоммерческие организации и их роль","a":["Негосударственные некоммерческие организации создаются для общественно полезных целей, а не для распределения прибыли между участниками. Они могут заниматься образованием, благотворительностью, защитой интересов людей, экологией и помощью уязвимым группам. Их роль состоит в выявлении общественных потребностей и участии граждан в решении проблем. Для эффективной работы важны прозрачность, самостоятельность и понятные правила деятельности"]},{"n":61,"q":"Местное самоуправление и текущие проблемы","a":["Махалля является формой самоорганизации жителей по месту проживания, а ее сход граждан относится к органам самоуправления. Она участвует в поддержке семей, общественной жизни, благоустройстве и выявлении местных проблем. Самоуправление нужно отличать от местных исполнительных органов во главе с хокимом. Основные трудности связаны с достаточностью ресурсов, самостоятельностью решений и недопущением чрезмерной нагрузки на активистов"]},{"n":62,"q":"Государственная молодежная политика и ее сущность","a":["Молодежная политика направлена на создание условий для образования, занятости, здоровья и участия молодых людей в жизни общества. Она включает профессиональное обучение, поддержку инициатив, спорт, культуру и профилактику социальных проблем. Важным документом стал Закон о государственной молодежной политике 2016 года. Эффективность такой политики оценивают по доступности возможностей и реальным результатам для молодежи"]},{"n":63,"q":"Рыночная инфраструктура и структурные изменения экономики","a":["Рыночная инфраструктура включает банки, биржи, страхование, транспорт, связь и учреждения, которые помогают обмену товарами и услугами. После независимости Узбекистан постепенно переходил от планового распределения к рыночным механизмам. Структурные изменения связаны с развитием промышленности, услуг, частного бизнеса и переработки сырья. Важная задача состоит в том, чтобы рост создавал производительные рабочие места и устойчивые доходы"]},{"n":64,"q":"Аграрные реформы задачи и направления","a":["Аграрные реформы изменяли организацию сельского хозяйства и условия работы производителей. Развивались фермерские и дехканские хозяйства, менялись механизмы закупок, расширялись выращивание разных культур и переработка продукции. Важные задачи включают повышение урожайности, водосбережение и защиту интересов работников. Для отрасли особенно значимы состояние почв, доступ к воде и предсказуемые правила землепользования"]},{"n":65,"q":"Развитие малого бизнеса и частного предпринимательства","a":["Малый бизнес создает рабочие места, расширяет выбор товаров и услуг и помогает развитию регионов. Для его поддержки упрощались некоторые процедуры регистрации, налогообложения и получения государственных услуг. Основные трудности связаны с доступом к финансированию, инфраструктуре и рынкам, а также с административными барьерами. Устойчивое развитие требует честной конкуренции, защиты собственности и понятных правил"]},{"n":66,"q":"Развитие и перспективы промышленного производства","a":["В независимом Узбекистане развивались автомобилестроение, текстиль, химическая, горно-металлургическая и другие отрасли. Важным направлением стало увеличение переработки местного сырья внутри страны. Перспективы связаны с современными технологиями, повышением производительности, подготовкой кадров и выходом на внешние рынки. Одновременно нужно снижать загрязнение и обеспечивать предприятия надежной энергией"]},{"n":67,"q":"Физическая культура и спорт в годы независимости","a":["После независимости Узбекистан стал самостоятельно участвовать в международных спортивных организациях и соревнованиях. Развивались спортивные школы, массовые занятия, детский и женский спорт. Международные успехи особенно заметны в боксе, дзюдо, борьбе и ряде других дисциплин. Для общества важны не только медали, но и доступность безопасной физической активности для людей разных возрастов"]},{"n":68,"q":"Реформы образования достижения и проблемы","a":["После независимости менялись содержание образования, структура подготовки кадров и сеть учебных заведений. Важными этапами стали Закон об образовании и Национальная программа подготовки кадров 1997 года, а затем новый Закон об образовании 2020 года. Расширялись дошкольное и высшее образование, обновлялись программы и цифровые средства. Среди проблем остаются качество подготовки, различия между регионами, нагрузка на педагогов и связь обучения с практикой"]},{"n":69,"q":"Сильная социальная политика и ее значение","a":["Сильная социальная политика направлена на защиту людей от бедности и тяжелых жизненных обстоятельств. Она включает пенсии, пособия, социальные услуги, поддержку занятости, доступ к образованию и здравоохранению. Помощь должна учитывать реальные потребности семьи и быть доступной без лишних препятствий. Ее цель состоит не только во временной поддержке, но и в создании условий для самостоятельного дохода"]},{"n":70,"q":"Реформы здравоохранения","a":["Реформы здравоохранения связаны с развитием первичной помощи, скорой медицинской помощи, профилактики и специализированного лечения. Создавались новые учреждения, обновлялось оборудование, расширялись цифровые сервисы. Важные задачи включают подготовку кадров, доступность лекарств и уменьшение различий между городом и селом. Оценивать систему следует по качеству и своевременности помощи, а не только по числу построенных объектов"]},{"n":71,"q":"Борьба с коррупцией как приоритет реформ Шавката Мирзиёева","a":["Коррупция означает использование должностных возможностей для личной выгоды и наносит ущерб доверию, бюджету и равным возможностям. В Узбекистане принят Закон о противодействии коррупции 2017 года, а в 2020 году создано Антикоррупционное агентство. Важны прозрачные закупки, открытые данные, цифровые услуги и предупреждение конфликта интересов. Наказание должно сочетаться с независимым контролем и условиями, которые затрудняют злоупотребления"]},{"n":72,"q":"Народные приемные как часть государственной политики","a":["Виртуальная и Народные приемные Президента созданы для приема обращений и выявления проблем граждан. Через них можно сообщать о нарушениях, трудностях получения услуг и местных проблемах. Такой механизм помогает органам власти видеть повторяющиеся причины жалоб. Его результативность зависит от качества ответа, реального решения вопроса и возможности проверить исполнение"]},{"n":73,"q":"Принцип от сильного государства к сильному гражданскому обществу","a":["Принцип означает постепенное расширение самостоятельного участия граждан и общественных организаций в решении общих вопросов. Государство должно обеспечивать законность и права, а общество должно иметь возможность контролировать власть и защищать свои интересы. Для этого развивают самоуправление, ННО, СМИ и формы общественного обсуждения. Передача задач обществу должна сопровождаться правами, ресурсами и ответственностью"]},{"n":74,"q":"Возрождение национальных ценностей и традиций","a":["После независимости расширилось внимание к родному языку, историческим памятникам, народным праздникам и обычаям. В общественной жизни укрепилось празднование Навруза, возрос интерес к традиционным ремеслам и семейному наследию. Возрождение означает сохранение культурной памяти и передачу ее новым поколениям. Оно должно сочетаться с уважением к многообразию страны и правам каждого человека"]},{"n":75,"q":"Содержание и значение названия 2025 года","a":["Название 2025 года связывало экологическую политику с экономическим развитием. Программа предусматривала меры по озеленению, водосбережению, сокращению загрязнения и развитию более чистых технологий. Зеленая экономика стремится уменьшать расход ресурсов и вред природе при сохранении возможностей для роста и занятости. Значение программы состоит в защите здоровья людей и природных условий жизни будущих поколений"]},{"n":76,"q":"Восстановление наследия великих ученых","a":["В годы независимости расширились исследования и популяризация трудов аль-Хорезми, аль-Фергани, аль-Бируни, Ибн Сины, Мирзо Улугбека и других ученых. Проводились юбилейные мероприятия, издавались труды, развивались музеи и научные центры. Их наследие показывает историческую связь региона с мировой наукой. Для его сохранения нужны качественные переводы, изучение рукописей и доступ к источникам"]},{"n":77,"q":"Межнациональная и межрелигиозная стабильность","a":["Политика в этой сфере направлена на равноправие граждан, предотвращение дискриминации и мирное взаимодействие разных общин. Важную роль играют образование, культурные центры, диалог религиозных организаций и соблюдение закона. Конфликты нужно предупреждать через решение социальных проблем и защиту людей от насилия. Устойчивое согласие строится на уважении прав, а не только на торжественных мероприятиях"]},{"n":78,"q":"Наука и перспективы инновационного развития","a":["Наука помогает создавать новые знания, технологии и способы решения общественных задач. После независимости менялись система научных учреждений, финансирование исследований и подготовка кадров. Инновационное развитие связано с применением исследований в производстве, медицине, сельском хозяйстве и цифровой сфере. Для этого нужны качественное образование, оборудование, научная добросовестность и сотрудничество с международными коллегами"]},{"n":79,"q":"Реформы образования и их перспективы","a":["После независимости менялись содержание образования, структура подготовки кадров и сеть учебных заведений. Важными этапами стали Закон об образовании и Национальная программа подготовки кадров 1997 года, а затем новый Закон об образовании 2020 года. Расширялись дошкольное и высшее образование, обновлялись программы и цифровые средства. Среди проблем остаются качество подготовки, различия между регионами, нагрузка на педагогов и связь обучения с практикой"]},{"n":80,"q":"Социально экономическое и духовное развитие Каракалпакстана","a":["Республика Каракалпакстан входит в состав Узбекистана и имеет собственную Конституцию, Жокаргы Кенес и Совет Министров в рамках конституционного устройства страны. Развивались образование, культура, инфраструктура и производственные проекты. При этом регион особенно сильно затронут последствиями высыхания Аральского моря. Важные задачи включают доступ к чистой воде, здоровье населения, рабочие места и сохранение каракалпакского культурного наследия"]},{"n":81,"q":"Миролюбивая внешняя политика и ее основные принципы","a":["Внешняя политика Узбекистана опирается на суверенное равенство, уважение границ, невмешательство и мирное решение споров. Государство стремится развивать взаимовыгодные отношения и сохранять самостоятельность решений. Особое место занимает сотрудничество с соседями по Центральной Азии. Экономические связи, транспорт и дипломатический диалог рассматриваются как средства укрепления безопасности и развития"]},{"n":82,"q":"Сотрудничество Узбекистана с ООН","a":["Узбекистан вступил в ООН 2 марта 1992 года. Сотрудничество охватывает образование, здравоохранение, права человека, экологию и устойчивое развитие. Страна выдвигает инициативы по Центральной Азии, Приаралью, молодежи и региональной безопасности. ООН дает площадку для дипломатического диалога и совместных проектов, но реализация инициатив зависит от поддержки государств и практической работы"]},{"n":83,"q":"Сотрудничество Узбекистана с СНГ","a":["Узбекистан участвовал в формировании Содружества Независимых Государств в декабре 1991 года. СНГ помогает поддерживать связи между бывшими союзными республиками в торговле, транспорте, гуманитарной сфере и миграции. Для Узбекистана важны договоренности, упрощающие экономическое взаимодействие и контакты граждан. При этом участие в СНГ не означает восстановления единого союзного государства"]},{"n":84,"q":"Перспективы сотрудничества с Европейским союзом","a":["Узбекистан развивает с Европейским союзом торговые, инвестиционные, образовательные и экологические связи. Важны доступ к европейским рынкам, техническая помощь, обмен опытом и подготовка специалистов. Сотрудничество также затрагивает государственное управление и права человека. Перспективы зависят от качества продукции, соблюдения договоренностей и взаимного интереса сторон"]},{"n":85,"q":"Сотрудничество Узбекистана с ШОС","a":["Узбекистан стал одним из государств-учредителей Шанхайской организации сотрудничества в 2001 году. Сотрудничество включает безопасность, противодействие терроризму, экономические и гуманитарные связи. В Ташкенте размещен Исполнительный комитет Региональной антитеррористической структуры ШОС. Организация является площадкой для согласования интересов разных стран и не равнозначна единому военно-политическому союзу"]},{"n":86,"q":"Культурное сотрудничество с ЮНЕСКО","a":["Узбекистан вступил в ЮНЕСКО в 1993 году. Совместная работа связана с сохранением памятников, нематериального наследия, развитием образования и науки. Международное признание исторических городов и традиций помогает привлекать внимание к их защите. При этом охрана наследия требует постоянной работы специалистов, а не только включения объекта в международный список"]},{"n":87,"q":"Борьба с терроризмом наркотрафиком и торговлей людьми","a":["Терроризм, незаконный оборот наркотиков и торговля людьми представляют угрозу безопасности и правам человека. Узбекистан сотрудничает с соседями и международными организациями через обмен информацией, охрану границ и совместные программы. Важны профилактика, помощь пострадавшим и уменьшение социальных причин уязвимости. Меры безопасности должны соблюдаться вместе с законностью и защитой прав граждан"]},{"n":88,"q":"Обеспечение безопасности согласия и толерантности в Центральной Азии","a":["С 2016 года внешняя политика Узбекистана уделяет повышенное внимание отношениям с соседями, переговорам по спорным вопросам и региональному диалогу. Развивались контакты руководителей, приграничные связи и совместные проекты. Поддержка межнационального согласия включает культурное сотрудничество и противодействие радикализации через образование. Такие усилия нужно рассматривать как длительный процесс, требующий участия всех стран региона"]},{"n":89,"q":"Справедливость и верховенство закона как условия развития","a":["Верховенство закона означает, что государственные органы и граждане действуют в рамках права, а решения власти можно проверять и оспаривать. Справедливость требует равного отношения, соразмерности ответственности и защиты слабой стороны. Для этого необходимы независимый суд, доступ к защите и исполнение решений. Эти условия помогают укреплять доверие и создавать предсказуемую среду для жизни и бизнеса"]},{"n":90,"q":"Программа экономических реформ Шавката Мирзиёева","a":["С 2016 года реформы включали либерализацию валютного рынка, изменение налоговой системы и расширение возможностей для предпринимательства. Большое внимание уделялось инвестициям, внешней торговле, государственным предприятиям и инфраструктуре. Цель состоит в повышении производительности, доходов и занятости. При этом открытие рынков должно сопровождаться защитой конкуренции, подготовкой кадров и поддержкой людей, которых затрагивают изменения"]},{"n":91,"q":"Выступление на 80 й сессии Генеральной Ассамблеи ООН в 2025 году","a":["Шавкат Мирзиёев выступил на 80-й сессии Генеральной Ассамблеи ООН 23 сентября 2025 года. Он говорил о региональном сотрудничестве, мирном решении конфликтов, водных ресурсах, климате и доступе к технологиям. Среди предложений были Всемирный форум по водосбережению, Всемирное движение молодежи за мир и механизм обмена решениями в области искусственного интеллекта. Также подчеркивались необходимость поддержки Афганистана и развития транспортных и энергетических связей"]},{"n":92,"q":"Инициативы по развитию мира и стабильности в Афганистане","a":["Узбекистан рассматривает мир и восстановление Афганистана как важное условие безопасности Центральной Азии. Его подход включает дипломатический диалог, гуманитарную помощь, поставки электроэнергии и развитие торговли. Обсуждаются транспортные проекты, которые могли бы связать регион с Южной Азией. Реализация таких планов зависит от безопасности, финансирования и международных договоренностей"]},{"n":93,"q":"Взаимовыгодные отношения со странами Центральной Азии","a":["Для Узбекистана особенно важны отношения с Казахстаном, Кыргызстаном, Таджикистаном и Туркменистаном. Сотрудничество охватывает торговлю, границы, транспорт, энергетику и совместное использование водных ресурсов. Развиваются консультации руководителей и прямые связи между регионами. Устойчивые результаты требуют учета интересов всех сторон и выполнения достигнутых соглашений"]},{"n":94,"q":"Президент Шавкат Мирзиёев как руководитель Нового Узбекистана","a":["Шавкат Мирзиёев стал Президентом Узбекистана в 2016 году. С понятием Нового Узбекистана связывают заявленный курс на открытость, улучшение государственных услуг, экономические преобразования и сотрудничество с соседями. К примерам относятся валютная либерализация, расширение системы обращений и реформы образования. Оценивать роль руководителя следует по конкретным решениям и их последствиям, отделяя цели программы от достигнутых результатов"]},{"n":95,"q":"Инициатива создания основ Третьего Ренессанса","a":["Идея Третьего Ренессанса означает стремление создать новый подъем науки, образования и культуры. Она опирается на память о выдающихся ученых средневекового региона и культурном развитии эпохи Тимуридов. В современной политике с ней связывают повышение качества школ, поддержку учителей, исследования и развитие талантов. Это программная цель, достижение которой требует длительной работы и устойчивых условий"]},{"n":96,"q":"Пять важных инициатив и работа по их реализации","a":["Пять важных инициатив были выдвинуты в 2019 году. Они включают интерес молодежи к культуре и искусству, физкультуру и спорт, компьютерные технологии и интернет, чтение и повышение духовной культуры, а также занятость женщин. Реализация связана с кружками, спортивными занятиями, библиотеками, обучением цифровым навыкам и поддержкой работы. Их смысл состоит в расширении доступных возможностей для развития и занятости"]},{"n":97,"q":"Стратегия развития Нового Узбекистана с 2022 по 2026 год","a":["Стратегия была утверждена 28 января 2022 года и включала семь приоритетных направлений и сто целей. Направления охватывали гуманное государство, законность, экономику, социальную сферу, духовное развитие, глобальные проблемы и безопасность с внешней политикой. Основная идея состояла в повышении качества жизни и уважении достоинства человека. Стратегию следует понимать как систему поставленных задач, выполнение которых требует отдельной оценки"]},{"n":98,"q":"Стратегия Узбекистан 2030 и ее сущность","a":["Стратегия «Узбекистан 2030» первоначально утверждена 11 сентября 2023 года. Она объединяла сто целей по пяти направлениям: развитие человека, экономический рост, водосбережение и экология, справедливое государственное управление, безопасность и миролюбивая политика. В феврале 2026 года документы стратегии были обновлены, поэтому для ответа по программе 2025 года важно различать первоначальный документ и последующие изменения. Общий смысл стратегии состоит в улучшении качества жизни через долгосрочные и проверяемые задачи"]},{"n":99,"q":"Реформы школьного образования и их перспективы","a":["Реформы школьного образования направлены на качество обучения, обновление учебников и улучшение условий работы педагогов. Важным изменением стало восстановление одиннадцатилетней общеобразовательной школы. Развиваются специализированные школы, цифровые средства и подготовка учителей. Главная задача состоит в том, чтобы ребенок получал базовые знания и навыки независимо от места проживания и дохода семьи"]},{"n":100,"q":"Реформы дошкольного образования","a":["Реформы дошкольного образования связаны с расширением сети детских садов и охвата детей подготовкой к школе. Используются государственные, негосударственные и семейные формы, а также партнерство государства с частным сектором. Важны не только новые места, но и безопасность, питание, подготовка воспитателей и содержание занятий. Дошкольное образование должно поддерживать речь, игру, общение и общее развитие ребенка"]},{"n":101,"q":"Духовное развитие и поднятие этой сферы на новый уровень","a":["Духовное развитие связано с нравственными ценностями, культурой, образованием и уважением к другим людям. Оно поддерживается через чтение, искусство, изучение наследия и ответственное участие в общественной жизни. Государственные программы в этой сфере должны расширять доступ к культурным возможностям. Устойчивый результат возникает, когда ценности подтверждаются повседневными поступками, справедливым отношением и личным примером"]},{"n":102,"q":"Референдум по изменениям Конституции указанный в вопросе как событие 2022 года","a":["В исходном вопросе указан 2022 год, однако референдум по новой редакции Конституции состоялся 30 апреля 2023 года. В 2022 году проходили подготовка проекта и его обсуждение. Новая редакция закрепила, в частности, характеристику государства как социального и светского и расширила ряд гарантий прав. Значение референдума состоит в принятии основных правил устройства государства путем всенародного голосования"]},{"n":103,"q":"Укрепление безопасности и оборонного потенциала","a":["Укрепление безопасности включает защиту независимости, границ, населения и важной инфраструктуры. Оборонный потенциал зависит от подготовки военнослужащих, управления, техники и способности реагировать на угрозы. Не менее важны дипломатия, предупреждение конфликтов, информационная безопасность и защита при чрезвычайных ситуациях. Военная и гражданская безопасность должны обеспечиваться в рамках Конституции и закона"]},{"n":104,"q":"Открытая прагматичная и активная внешняя политика","a":["Открытая политика предполагает готовность к диалогу и сотрудничеству с разными странами. Прагматичность означает ориентацию на реальные интересы граждан, торговли, транспорта и безопасности. Активность проявляется в участии в международных площадках и выдвижении инициатив. При этом важны самостоятельность решений, выполнение договоренностей и мирное урегулирование разногласий"]},{"n":105,"q":"Построение гуманного государства","a":["Гуманное государство ставит в центр достоинство и законные интересы человека. Его учреждения должны быть доступны, уважительно обращаться с гражданами и решать общественные проблемы. Это включает защиту от произвола, справедливый суд, социальную поддержку и качественные услуги. Проверять такой принцип нужно по тому, как государство действует в обычных жизненных ситуациях"]},{"n":106,"q":"Принцип честь и достоинство человека превыше всего","a":["Принцип приоритета чести и достоинства означает признание ценности каждого человека независимо от его положения. Он требует уважительного обращения, защиты от унижения, насилия и незаконного вмешательства. В государственной политике это связано с доступностью правосудия, образования, медицины и возможностей для труда. Права человека должны учитываться при принятии решений и работе должностных лиц"]},{"n":107,"q":"Развитие национальной экономики и высокие темпы роста","a":["Устойчивый экономический рост означает увеличение производства полезных товаров и услуг на длительной основе. Для него нужны инвестиции, технологии, квалифицированные кадры, надежная инфраструктура и честная конкуренция. Важно не только увеличивать объем экономики, но и повышать реальные доходы и качество рабочих мест. Следует учитывать инфляцию, экологические издержки и доступность результатов роста для разных групп населения"]},{"n":108,"q":"Социальная политика и человеческий капитал в Стратегии развития","a":["Человеческий капитал включает знания, навыки, здоровье и способности людей. В Стратегии развития на период с 2022 по 2026 год социальная политика связывалась с образованием, медициной, занятостью и поддержкой нуждающихся. Такие вложения помогают людям повышать самостоятельность и производительность труда. Справедливость требует уменьшать препятствия для детей, людей с инвалидностью и жителей удаленных территорий"]},{"n":109,"q":"Участие в решении глобальных проблем современности","a":["Узбекистан участвует в международной работе по климату, водным ресурсам, бедности, безопасности и устойчивому развитию. Особое место занимает привлечение внимания к последствиям высыхания Аральского моря. Страна сотрудничает с ООН и другими организациями, предлагает инициативы и участвует в совместных проектах. Глобальные проблемы нельзя решить усилиями одного государства, поэтому важны обмен знаниями и согласованные действия"]},{"n":110,"q":"Особенности избирательной системы","a":["Избирательная система определяет, как граждане выбирают органы власти и как голоса превращаются в депутатские места. На выборах 2024 года Законодательная палата избиралась по смешанной системе: 75 депутатов по одномандатным округам и 75 по партийным спискам. Цель изменений состоит в соединении связи депутата с территорией и представительства партийных программ. Важными условиями остаются свободное волеизъявление, понятные процедуры и прозрачный подсчет"]},{"n":111,"q":"Значение принятия Избирательного кодекса","a":["Избирательный кодекс принят в 2019 году и объединил основные правила проведения разных выборов в одном документе. Он регулирует деятельность комиссий, выдвижение кандидатов, агитацию, голосование и подсчет голосов. Единые нормы делают процедуры более понятными для участников. Значение кодекса зависит также от последовательного исполнения, прозрачности и возможности обжаловать нарушения"]},{"n":112,"q":"Становление и развитие парламентаризма","a":["В первые годы независимости создавались основы национального парламентаризма. После реформ парламент стал двухпалатным: с 2005 года работают Законодательная палата и Сенат. Позже расширялись формы парламентского контроля и участия в формировании правительства. На выборах 2024 года для Законодательной палаты впервые применили смешанную систему, сочетающую выборы по округам и партийным спискам"]},{"n":113,"q":"Роль политических партий в демократизации политической жизни","a":["Политические партии объединяют людей с близкими взглядами и предлагают программы общественного развития. Через выборы они стремятся получить представительство и влиять на законы и решения. В парламенте партии должны выражать интересы избирателей и контролировать работу исполнительной власти. Их реальная роль определяется качеством конкуренции, связью с гражданами и ответственностью за обещания"]},{"n":114,"q":"Значение Железной женской и молодежной тетрадей","a":["Так называют системы выявления людей и семей, которым нужна адресная поддержка. Железная тетрадь была связана с помощью семьям в трудном материальном положении, Женская тетрадь с проблемами женщин, а Молодежная с трудностями молодых людей. Поддержка может включать обучение, содействие занятости и социальные услуги. Смысл учета состоит в индивидуальном решении проблемы, а сама запись в перечне еще не означает ее устранения"]},{"n":115,"q":"Восстановление культурного наследия национальных ценностей и традиций","a":["После независимости расширилось внимание к родному языку, историческим памятникам, народным праздникам и обычаям. В общественной жизни укрепилось празднование Навруза, возрос интерес к традиционным ремеслам и семейному наследию. Возрождение означает сохранение культурной памяти и передачу ее новым поколениям. Оно должно сочетаться с уважением к многообразию страны и правам каждого человека"]},{"n":116,"q":"Социальные и культурные реформы в годы независимости","a":["Социальные и культурные реформы включают образование, здравоохранение, поддержку семей, развитие искусства и сохранение наследия. После независимости создавались новые национальные учреждения, пересматривались программы и расширялись международные культурные контакты. Важна доступность библиотек, музеев, театров и творческих занятий для разных регионов. Качество реформ определяется участием людей и реальным улучшением условий жизни"]},{"n":117,"q":"Концепция внешнеполитической деятельности","a":["Концепция внешнеполитической деятельности определяет основные интересы, принципы и направления международных отношений страны. В учебном курсе важен документ 2012 года, который закреплял самостоятельность решений и миролюбивый подход. Среди ориентиров были невмешательство, равноправное сотрудничество и приоритет безопасности. Концепцию как программный документ следует отличать от отдельных соглашений и более поздних решений"]},{"n":118,"q":"Собственный путь обновления и прогресса","a":["После распада СССР Узбекистану требовалось одновременно создавать государственные институты и менять хозяйственную систему. Руководство выбрало постепенный переход с сильной регулирующей ролью государства и социальной поддержкой. В дальнейшем подходы менялись под влиянием внутренних задач и мировой экономики. Значение собственного пути состоит в самостоятельности решений, а его результаты нужно оценивать по развитию страны и положению населения"]},{"n":119,"q":"Начало политических реформ и основы демократического управления","a":["Начало политических реформ связано с позднесоветскими изменениями и первыми годами независимости. Создавались институт президентства, национальная правовая база, органы самостоятельного управления и многопартийные механизмы выборов. Конституция 1992 года закрепила основы устройства государства и права граждан. Дальнейшая задача заключалась в том, чтобы правовые принципы работали на практике"]},{"n":120,"q":"Политические реформы в Узбекистане","a":["Политические реформы затрагивают устройство власти, выборы, парламент, суды, государственные услуги и участие граждан. На разных этапах менялись полномочия органов, порядок формирования парламента и формы общественного контроля. С 2016 года заметное место заняли обращения граждан и открытость отдельных государственных процессов. Оценка реформ должна учитывать не только принятые документы, но и реальную защиту прав и ответственность власти"]},{"n":121,"q":"Основы демократического государства и гражданского общества","a":["Основы демократического государства включают народное представительство, выборы, разделение властей и защиту прав. Гражданское общество состоит из самостоятельных объединений, общественных инициатив и других форм участия людей. Для их развития нужны законные возможности объединяться, получать информацию и высказывать мнение. Конституционные нормы создают основу, но их действие требует независимых институтов и активного участия граждан"]},{"n":122,"q":"Экономические реформы частная собственность и рыночные отношения","a":["Переход к рынку включал признание разных форм собственности, приватизацию части предприятий и развитие предпринимательства. Частная собственность дает возможность самостоятельно использовать имущество и получать доход в рамках закона. Рыночные отношения требуют договоров, конкуренции, финансовых услуг и защиты прав собственника. Важны также прозрачность приватизации и недопущение замены государственной монополии частной"]},{"n":123,"q":"Обновление страны от национального возрождения к национальному прогрессу","a":["Эта формулировка выражает переход от восстановления государственности и культурного наследия к задачам повышения качества жизни. В программе Нового Узбекистана с ней связывают экономические реформы, образование, открытость и развитие человеческого потенциала. Смысл состоит в соединении уважения к истории с современными знаниями и технологиями. Это политическая идея, которую следует оценивать по конкретным решениям и результатам"]},{"n":124,"q":"Международные отношения и место в мировом сообществе","a":["После независимости Узбекистан установил дипломатические отношения и стал участником международных организаций. Его положение связывает Центральную Азию с важными транспортными, торговыми и культурными направлениями. Страна развивает отношения с соседями и крупными мировыми партнерами. Международная роль зависит от надежности сотрудничества, внутреннего развития и способности участвовать в решении общих проблем"]},{"n":125,"q":"Каракалпакстан в годы независимости","a":["Республика Каракалпакстан входит в состав Узбекистана и имеет собственную Конституцию, Жокаргы Кенес и Совет Министров в рамках конституционного устройства страны. Развивались образование, культура, инфраструктура и производственные проекты. При этом регион особенно сильно затронут последствиями высыхания Аральского моря. Важные задачи включают доступ к чистой воде, здоровье населения, рабочие места и сохранение каракалпакского культурного наследия"]},{"n":126,"q":"Аральская экологическая катастрофа и пути преодоления кризиса","a":["Высыхание Аральского моря связано прежде всего с многолетним отводом значительной части стока Амударьи и Сырдарьи на орошение. Последствия включают засоление, пылевые и солевые бури, ухудшение условий жизни и потерю прежнего рыбного хозяйства. Меры включают водосбережение, посадку устойчивых растений на высохшем дне, обеспечение питьевой водой и поддержку населения. Полное возвращение прежнего моря в короткий срок нереалистично, поэтому особенно важны адаптация и снижение вреда"]},{"n":127,"q":"Меры по повышению благосостояния населения","a":["Благосостояние зависит от реальных доходов, занятости, стоимости жизни, здоровья и качества общественных услуг. Его повышают через производительные рабочие места, поддержку предпринимательства, образование и доступную инфраструктуру. Для семей в трудной ситуации нужна адресная социальная помощь. Оценка должна учитывать не только средние показатели, но и различия между регионами и группами населения"]},{"n":128,"q":"Путь независимого развития и его значение","a":["После распада СССР Узбекистану требовалось одновременно создавать государственные институты и менять хозяйственную систему. Руководство выбрало постепенный переход с сильной регулирующей ролью государства и социальной поддержкой. В дальнейшем подходы менялись под влиянием внутренних задач и мировой экономики. Значение собственного пути состоит в самостоятельности решений, а его результаты нужно оценивать по развитию страны и положению населения"]},{"n":129,"q":"От сильного государства к сильному гражданскому обществу","a":["Принцип означает постепенное расширение самостоятельного участия граждан и общественных организаций в решении общих вопросов. Государство должно обеспечивать законность и права, а общество должно иметь возможность контролировать власть и защищать свои интересы. Для этого развивают самоуправление, ННО, СМИ и формы общественного обсуждения. Передача задач обществу должна сопровождаться правами, ресурсами и ответственностью"]},{"n":130,"q":"Институты гражданского общества и их роль в развитии демократии","a":["К институтам гражданского общества относят ННО, профессиональные и общественные объединения, независимые СМИ и органы самоуправления. Они помогают людям выражать интересы, объединяться и контролировать общественно значимые решения. Их роль особенно важна там, где отдельному человеку трудно защитить свои права самостоятельно. Для действенности необходимы самостоятельность, прозрачность и возможность свободно действовать в рамках закона"]},{"n":131,"q":"Деятельность политических партий","a":["Политические партии объединяют людей с близкими взглядами и предлагают программы общественного развития. Через выборы они стремятся получить представительство и влиять на законы и решения. В парламенте партии должны выражать интересы избирателей и контролировать работу исполнительной власти. Их реальная роль определяется качеством конкуренции, связью с гражданами и ответственностью за обещания"]},{"n":132,"q":"Гуманное государство и достоинство человека","a":["Гуманное государство ставит в центр достоинство и законные интересы человека. Его учреждения должны быть доступны, уважительно обращаться с гражданами и решать общественные проблемы. Это включает защиту от произвола, справедливый суд, социальную поддержку и качественные услуги. Проверять такой принцип нужно по тому, как государство действует в обычных жизненных ситуациях"]},{"n":133,"q":"Декларация независимости и ее историческое значение","a":["Декларация о государственном суверенитете Узбекской ССР была принята 20 июня 1990 года. Она закрепляла право республики самостоятельно определять важнейшие вопросы своей жизни и утверждала приоритет ее суверенных полномочий. Этот документ стал важным шагом к независимости. Его нужно отличать от провозглашения полной государственной независимости 31 августа 1991 года"]},{"n":134,"q":"Укрепление суверенитета в первые годы независимости","a":["Для укрепления суверенитета создавались собственные органы управления, правовая система, вооруженные силы и дипломатическая служба. Были приняты государственные символы и Конституция, введена национальная валюта. Узбекистан устанавливал отношения с другими странами и вступал в международные организации. Важной задачей было сохранение управляемости и хозяйственных связей в условиях распада СССР"]},{"n":135,"q":"Принятие Конституции и ее историческое значение","a":["Первая Конституция независимого Узбекистана была принята 8 декабря 1992 года. Она определила основы государственного строя, права граждан и устройство органов власти. Новая редакция была принята на референдуме 30 апреля 2023 года и вступила в силу 1 мая 2023 года. Конституция является правовой основой государства, но ее нормы должны обеспечиваться реальной работой государственных органов и судов"]},{"n":136,"q":"Становление многопартийности проблемы и решения","a":["После независимости начала формироваться правовая основа деятельности политических партий и выборов на многопартийной основе. Партии должны представлять интересы разных групп, предлагать программы и выдвигать кандидатов. В учебный период действовали пять зарегистрированных партий, включая УзЛиДеП, НДПУ, «Адолат», «Миллий тикланиш» и Экологическую партию. Основные задачи развития системы связаны с содержательной конкуренцией, открытостью и подотчетностью избирателям"]},{"n":137,"q":"Развитие малого бизнеса и частного предпринимательства","a":["Малый бизнес создает рабочие места, расширяет выбор товаров и услуг и помогает развитию регионов. Для его поддержки упрощались некоторые процедуры регистрации, налогообложения и получения государственных услуг. Основные трудности связаны с доступом к финансированию, инфраструктуре и рынкам, а также с административными барьерами. Устойчивое развитие требует честной конкуренции, защиты собственности и понятных правил"]},{"n":138,"q":"Физическая культура и спорт за годы независимости","a":["После независимости Узбекистан стал самостоятельно участвовать в международных спортивных организациях и соревнованиях. Развивались спортивные школы, массовые занятия, детский и женский спорт. Международные успехи особенно заметны в боксе, дзюдо, борьбе и ряде других дисциплин. Для общества важны не только медали, но и доступность безопасной физической активности для людей разных возрастов"]},{"n":139,"q":"Образовательные реформы достижения и проблемы","a":["После независимости менялись содержание образования, структура подготовки кадров и сеть учебных заведений. Важными этапами стали Закон об образовании и Национальная программа подготовки кадров 1997 года, а затем новый Закон об образовании 2020 года. Расширялись дошкольное и высшее образование, обновлялись программы и цифровые средства. Среди проблем остаются качество подготовки, различия между регионами, нагрузка на педагогов и связь обучения с практикой"]},{"n":140,"q":"Декларация о независимости и ее историческое значение","a":["Декларация о государственном суверенитете Узбекской ССР была принята 20 июня 1990 года. Она закрепляла право республики самостоятельно определять важнейшие вопросы своей жизни и утверждала приоритет ее суверенных полномочий. Этот документ стал важным шагом к независимости. Его нужно отличать от провозглашения полной государственной независимости 31 августа 1991 года"]},{"n":141,"q":"Провозглашение государственной независимости","a":["31 августа 1991 года была провозглашена государственная независимость Республики Узбекистан и принят Закон об основах государственной независимости. 1 сентября установлено Днем независимости. На референдуме 29 декабря 1991 года население поддержало независимость. Эти решения создали правовую основу самостоятельного государства и его международного признания"]},{"n":142,"q":"Укрепление суверенитета в первые годы независимости","a":["Для укрепления суверенитета создавались собственные органы управления, правовая система, вооруженные силы и дипломатическая служба. Были приняты государственные символы и Конституция, введена национальная валюта. Узбекистан устанавливал отношения с другими странами и вступал в международные организации. Важной задачей было сохранение управляемости и хозяйственных связей в условиях распада СССР"]},{"n":143,"q":"Узбекская модель развития и ее особенности","a":["Узбекской моделью называют подход к переходу от плановой экономики к рынку, сформулированный в начале независимости. Обычно выделяют пять принципов: приоритет экономики над политикой, ведущую роль государства в реформах, верховенство закона, сильную социальную политику и постепенность преобразований. Предполагалось избегать резкого разрушения хозяйственных связей. При этом постепенность сопровождалась длительным сохранением значительного государственного контроля"]},{"n":144,"q":"Исторический путь обеспечения экономической независимости","a":["Экономическая независимость означала создание собственных финансовых институтов и уменьшение зависимости от прежних союзных поставок. Важными шагами стали введение национальной валюты сум 1 июля 1994 года, развитие банковской системы и расширение собственной промышленности. Большое внимание уделялось продовольствию, энергетике и транспортным связям. При этом экономическая самостоятельность не исключает торговли и сотрудничества с другими странами"]},{"n":145,"q":"Принятие Конституции и ее историческое значение","a":["Первая Конституция независимого Узбекистана была принята 8 декабря 1992 года. Она определила основы государственного строя, права граждан и устройство органов власти. Новая редакция была принята на референдуме 30 апреля 2023 года и вступила в силу 1 мая 2023 года. Конституция является правовой основой государства, но ее нормы должны обеспечиваться реальной работой государственных органов и судов"]},{"n":146,"q":"Принятие государственных символов","a":["Государственный флаг был принят 18 ноября 1991 года, герб 2 июля 1992 года, а гимн 10 декабря 1992 года. Музыку гимна написал Муталь Бурханов, слова Абдулла Арипов. Символы выражают самостоятельность страны, ее исторические традиции и общность граждан. Их используют в официальной жизни, государственных учреждениях и международных отношениях"]},{"n":147,"q":"Принцип разделения властей","a":["Разделение властей означает различие законодательной, исполнительной и судебной функций. Олий Мажлис принимает законы и осуществляет парламентский контроль, исполнительные органы организуют их выполнение, а суды разрешают споры и защищают права. Органы власти должны взаимодействовать и ограничивать возможность злоупотреблений. Само наличие разных учреждений еще не заменяет их реальной самостоятельности и ответственности"]},{"n":148,"q":"Формирование многопартийной системы и ее проблемы","a":["После независимости начала формироваться правовая основа деятельности политических партий и выборов на многопартийной основе. Партии должны представлять интересы разных групп, предлагать программы и выдвигать кандидатов. В учебный период действовали пять зарегистрированных партий, включая УзЛиДеП, НДПУ, «Адолат», «Миллий тикланиш» и Экологическую партию. Основные задачи развития системы связаны с содержательной конкуренцией, открытостью и подотчетностью избирателям"]},{"n":149,"q":"Парламентские реформы","a":["В первые годы независимости создавались основы национального парламентаризма. После реформ парламент стал двухпалатным: с 2005 года работают Законодательная палата и Сенат. Позже расширялись формы парламентского контроля и участия в формировании правительства. На выборах 2024 года для Законодательной палаты впервые применили смешанную систему, сочетающую выборы по округам и партийным спискам"]},{"n":150,"q":"Становление и структура исполнительной власти","a":["Исполнительная власть организует повседневное управление, выполнение законов и государственных программ. На общегосударственном уровне важную роль играет Кабинет Министров во главе с Премьер-министром, в систему также входят министерства и ведомства. На местах действуют хокимы и подчиненные им исполнительные структуры. В ходе реформ менялись состав органов, их полномочия и порядок отчетности"]},{"n":151,"q":"Роль СМИ в демократизации общества","a":["СМИ сообщают гражданам о событиях и решениях власти, объясняют общественные проблемы и дают возможность обсуждать их. Журналистские расследования могут выявлять нарушения и способствовать общественному контролю. Для этой роли необходимы доступ к информации, свобода выражения мнений и безопасность журналистов. Качество работы СМИ также зависит от проверки фактов и ответственности за достоверность сообщений"]},{"n":152,"q":"Либерализация общественной жизни","a":["Либерализация означает расширение свобод, открытости и возможностей самостоятельного участия людей в общественной жизни. В Узбекистане этот процесс связан с развитием общественных обсуждений, электронных обращений и более открытого освещения ряда проблем. Одновременно сохраняются вопросы реальной конкуренции, независимости общественных институтов и защиты свободы слова. Поэтому оценивать нужно конкретные изменения и их практические результаты"]},{"n":153,"q":"Негосударственные некоммерческие организации и их роль","a":["Негосударственные некоммерческие организации создаются для общественно полезных целей, а не для распределения прибыли между участниками. Они могут заниматься образованием, благотворительностью, защитой интересов людей, экологией и помощью уязвимым группам. Их роль состоит в выявлении общественных потребностей и участии граждан в решении проблем. Для эффективной работы важны прозрачность, самостоятельность и понятные правила деятельности"]},{"n":154,"q":"Местное самоуправление и текущие проблемы","a":["Махалля является формой самоорганизации жителей по месту проживания, а ее сход граждан относится к органам самоуправления. Она участвует в поддержке семей, общественной жизни, благоустройстве и выявлении местных проблем. Самоуправление нужно отличать от местных исполнительных органов во главе с хокимом. Основные трудности связаны с достаточностью ресурсов, самостоятельностью решений и недопущением чрезмерной нагрузки на активистов"]},{"n":155,"q":"Государственная молодежная политика","a":["Молодежная политика направлена на создание условий для образования, занятости, здоровья и участия молодых людей в жизни общества. Она включает профессиональное обучение, поддержку инициатив, спорт, культуру и профилактику социальных проблем. Важным документом стал Закон о государственной молодежной политике 2016 года. Эффективность такой политики оценивают по доступности возможностей и реальным результатам для молодежи"]},{"n":156,"q":"Аграрные реформы задачи и направления","a":["Аграрные реформы изменяли организацию сельского хозяйства и условия работы производителей. Развивались фермерские и дехканские хозяйства, менялись механизмы закупок, расширялись выращивание разных культур и переработка продукции. Важные задачи включают повышение урожайности, водосбережение и защиту интересов работников. Для отрасли особенно значимы состояние почв, доступ к воде и предсказуемые правила землепользования"]},{"n":157,"q":"Проблемы развития малого бизнеса и частного предпринимательства","a":["Малый бизнес создает рабочие места, расширяет выбор товаров и услуг и помогает развитию регионов. Для его поддержки упрощались некоторые процедуры регистрации, налогообложения и получения государственных услуг. Основные трудности связаны с доступом к финансированию, инфраструктуре и рынкам, а также с административными барьерами. Устойчивое развитие требует честной конкуренции, защиты собственности и понятных правил"]},{"n":158,"q":"Физическая культура и спорт в годы независимости","a":["После независимости Узбекистан стал самостоятельно участвовать в международных спортивных организациях и соревнованиях. Развивались спортивные школы, массовые занятия, детский и женский спорт. Международные успехи особенно заметны в боксе, дзюдо, борьбе и ряде других дисциплин. Для общества важны не только медали, но и доступность безопасной физической активности для людей разных возрастов"]},{"n":159,"q":"Реформы образования достижения и проблемы","a":["После независимости менялись содержание образования, структура подготовки кадров и сеть учебных заведений. Важными этапами стали Закон об образовании и Национальная программа подготовки кадров 1997 года, а затем новый Закон об образовании 2020 года. Расширялись дошкольное и высшее образование, обновлялись программы и цифровые средства. Среди проблем остаются качество подготовки, различия между регионами, нагрузка на педагогов и связь обучения с практикой"]},{"n":160,"q":"Сильная социальная политика и ее значение","a":["Сильная социальная политика направлена на защиту людей от бедности и тяжелых жизненных обстоятельств. Она включает пенсии, пособия, социальные услуги, поддержку занятости, доступ к образованию и здравоохранению. Помощь должна учитывать реальные потребности семьи и быть доступной без лишних препятствий. Ее цель состоит не только во временной поддержке, но и в создании условий для самостоятельного дохода"]},{"n":161,"q":"Реформы здравоохранения","a":["Реформы здравоохранения связаны с развитием первичной помощи, скорой медицинской помощи, профилактики и специализированного лечения. Создавались новые учреждения, обновлялось оборудование, расширялись цифровые сервисы. Важные задачи включают подготовку кадров, доступность лекарств и уменьшение различий между городом и селом. Оценивать систему следует по качеству и своевременности помощи, а не только по числу построенных объектов"]},{"n":162,"q":"Каракалпакстан в годы независимости","a":["Республика Каракалпакстан входит в состав Узбекистана и имеет собственную Конституцию, Жокаргы Кенес и Совет Министров в рамках конституционного устройства страны. Развивались образование, культура, инфраструктура и производственные проекты. При этом регион особенно сильно затронут последствиями высыхания Аральского моря. Важные задачи включают доступ к чистой воде, здоровье населения, рабочие места и сохранение каракалпакского культурного наследия"]},{"n":163,"q":"Участие в Организации тюркских государств","a":["Узбекистан стал полноправным участником Совета сотрудничества тюркоязычных государств в 2019 году. В 2021 году организация получила название Организация тюркских государств. Сотрудничество охватывает торговлю, транспорт, образование, культуру и общие исторические связи. Для Узбекистана это дополнительная площадка партнерства, которая действует вместе с другими направлениями внешней политики"]},{"n":164,"q":"Культурный Ренессанс с IX по XII век и вклад ученых в мировую цивилизацию","a":["С IX по XII век в городах Центральной Азии и соседних регионов активно развивались математика, астрономия, медицина и философия. Аль-Хорезми внес большой вклад в алгебру, аль-Фергани в астрономию, аль-Бируни в естественные науки, Ибн Сина в медицину и философию. Развитие поддерживали города, торговля, переводческая работа и обмен знаниями. Это наследие является частью истории мировой науки и не ограничивается современными государственными границами"]},{"n":165,"q":"Джалолиддин Мангуберди защитник Родины","a":["Джалолиддин Мангуберди был правителем государства Хорезмшахов и возглавлял сопротивление монгольскому завоеванию в XIII веке. Одним из известных эпизодов стала его победа при Парване в 1221 году. После поражения у Инда он продолжил борьбу в других регионах. В исторической памяти его образ связан с мужеством и защитой страны от завоевателей"]},{"n":166,"q":"Амир Темур государственный деятель","a":["Амир Темур был правителем и полководцем XIV века, создавшим крупную державу с центром в Самарканде. Он укреплял управление, поддерживал строительство и привлекал мастеров и ученых. Самарканд стал важным политическим и культурным центром. Его деятельность включала и разрушительные военные походы, поэтому историческая оценка должна учитывать как государственное строительство, так и последствия войн"]},{"n":167,"q":"Мирзо Улугбек государственный деятель и ученый","a":["Мирзо Улугбек был правителем из династии Тимуридов и выдающимся астрономом XV века. В Самарканде он поддерживал образование и создал крупную обсерваторию. Вместе с учеными своего круга он подготовил астрономические таблицы и звездный каталог, известные как «Зидж». Его наследие показывает значение точных наблюдений, математических расчетов и сотрудничества ученых"]},{"n":168,"q":"Роль джадидов просветителей","a":["Джадиды выступали за обновление образования, распространение современных знаний и развитие общественной мысли. Мунаввар Кары, Махмудходжа Бехбуди, Абдулла Авлони и Абдурауф Фитрат создавали учебные материалы, школы, газеты и литературные произведения. Они связывали развитие общества с грамотностью и образованием. Многие представители движения позднее стали жертвами советских репрессий"]},{"n":169,"q":"Общественная и политическая ситуация в годы перестройки","a":["Узбекистан оставался частью СССР и зависел от союзного центра в политике и экономике. Хозяйство было сильно связано с выращиванием хлопка, что ограничивало разнообразие производства и усиливало экологические проблемы. На фоне перестройки обострились дефицит товаров, социальные трудности и недоверие к власти. Гласность сделала более открытым обсуждение языка, исторического наследия и самостоятельности республики"]},{"n":170,"q":"Общественные и политические процессы накануне независимости","a":["Рост активности был связан с перестройкой, гласностью и ослаблением прежнего контроля над общественными обсуждениями. Люди открыто поднимали вопросы языка, экологии, социальной справедливости и национального наследия. Экономические трудности усиливали запрос на изменения. Появлялись общественные движения и новые формы участия граждан в политической жизни"]},{"n":171,"q":"Реформы государственного управления за годы независимости","a":["После независимости создавались собственные министерства, правительство и местные органы управления. На последующих этапах менялись их полномочия, развивались государственные услуги и электронные обращения. Административные реформы были направлены на сокращение дублирующих задач, повышение ответственности и удобство работы для граждан. Главная задача состоит в переходе от лишних согласований к понятным услугам и проверяемым результатам"]},{"n":172,"q":"Духовные и культурные преобразования в Новом Узбекистане","a":["Социальные и культурные реформы включают образование, здравоохранение, поддержку семей, развитие искусства и сохранение наследия. После независимости создавались новые национальные учреждения, пересматривались программы и расширялись международные культурные контакты. Важна доступность библиотек, музеев, театров и творческих занятий для разных регионов. Качество реформ определяется участием людей и реальным улучшением условий жизни"]},{"n":173,"q":"Деятельность средств массовой информации","a":["СМИ сообщают гражданам о событиях и решениях власти, объясняют общественные проблемы и дают возможность обсуждать их. Журналистские расследования могут выявлять нарушения и способствовать общественному контролю. Для этой роли необходимы доступ к информации, свобода выражения мнений и безопасность журналистов. Качество работы СМИ также зависит от проверки фактов и ответственности за достоверность сообщений"]},{"n":174,"q":"Реформы сельского хозяйства и промышленности","a":["В сельском хозяйстве развивались фермерские хозяйства, разнообразие культур, переработка продукции и водосберегающие технологии. В промышленности расширялись текстильное производство, автомобилестроение, химия и переработка полезных ископаемых. Общее направление состояло в повышении производительности и увеличении выпуска готовых товаров. Результаты зависят от технологий, кадров, доступа к ресурсам и защиты конкуренции"]},{"n":175,"q":"Создание гарантий прав и свобод человека","a":["Гарантии прав включают конституционные нормы, законы, судебную защиту и возможность обжаловать действия власти. Важны презумпция невиновности, доступ к юридической помощи и запрет незаконного ограничения свободы. Новая редакция Конституции 2023 года расширила ряд соответствующих положений. Реальная защищенность человека зависит от применения этих норм, качества расследования жалоб и независимости суда"]},{"n":176,"q":"Изменения страны в международных рейтингах и индексах","a":["Международные индексы сравнивают страны по разным показателям, например развитию человека, прозрачности, управлению или инновациям. Изменение места может отражать как реальные сдвиги, так и пересмотр методики или результаты других стран. Поэтому нужно указывать название индекса, год и используемый показатель. Одного рейтинга недостаточно для полной оценки развития Узбекистана, а неподтвержденные места в таблицах приводить нельзя"]},{"n":177,"q":"Сотрудничество с международными организациями","a":["Узбекистан взаимодействует с ООН, ОБСЕ, ШОС, СНГ, международными финансовыми учреждениями и другими организациями. Направления включают развитие, безопасность, образование, здравоохранение, торговлю и экологию. Такое сотрудничество дает доступ к опыту, финансированию и площадкам для переговоров. При этом каждое соглашение следует оценивать по его условиям, обязательствам и пользе для населения"]},{"n":178,"q":"Роль Узбекистана в обеспечении мира и стабильности в Центральной Азии","a":["Узбекистан участвует в укреплении стабильности через диалог с соседями, развитие торговли и согласование вопросов границ, воды и транспорта. Важны консультации руководителей, культурные связи и совместные экономические проекты. Мир поддерживается не только мерами безопасности, но и решением социальных проблем и расширением взаимного доверия. Устойчивое сотрудничество требует уважения суверенитета и интересов всех государств региона"]}],"sources":["Конституция Республики Узбекистан новая редакция 2023 года","Декларация о суверенитете от 20 июня 1990 года","Закон об основах государственной независимости от 31 августа 1991 года","Государственная символика Узбекистана","Центральный банк о введении национальной валюты","Стратегия развития Нового Узбекистана с 2022 по 2026 год","Первоначальный документ Стратегии Узбекистан 2030 и сведения о его обновлении","Программа Года охраны окружающей среды и зеленой экономики","Выступление на 80 й сессии Генеральной Ассамблеи ООН 23 сентября 2025 года","Центральная избирательная комиссия о смешанной системе выборов","ООН в Узбекистане сведения о сотрудничестве","ЮНЕСКО список государств участников","Участие Узбекистана в Совете тюркоязычных государств с 2019 года"]},{"id":"pk","short":"ПК","name":"ПК вопросы","title":"Ответы по клиническим основам специальной педагогики","subtitle":"52 вопроса о нервной системе и ее нарушениях","tickets":false,"items":[{"n":1,"q":"Нервная система: классификация, свойства","a":["По строению нервная система делится на центральную и периферическую. Центральная включает головной и спинной мозг, периферическая включает нервы, узлы и нервные окончания. По функциям различают соматическую систему и вегетативную систему с симпатическим, парасимпатическим и энтеральным отделами. Основные свойства нервной ткани включают возбудимость, проведение сигналов и способность изменять связи под влиянием опыта"]},{"n":2,"q":"Доли головного мозга (название, функция)","a":["Лобная доля участвует в произвольных движениях, планировании, контроле поведения и образовании речи. Теменная доля обрабатывает телесную чувствительность и помогает ориентироваться в пространстве. Височная доля участвует в слухе, памяти и понимании речи, затылочная связана прежде всего со зрением. Островковая доля участвует в обработке вкуса и сигналов от тела, при этом сложные функции выполняются совместной работой разных областей"]},{"n":3,"q":"Отделы головного мозга (название, функция)","a":["Головной мозг включает продолговатый мозг, мост, мозжечок, средний мозг, промежуточный мозг и большие полушария. Продолговатый мозг участвует в регуляции дыхания и кровообращения, мост проводит сигналы и связан с движениями и сном. Мозжечок согласует движения и равновесие, средний мозг участвует в движениях и ориентировочных реакциях. Таламус передает и обрабатывает сигналы, гипоталамус регулирует внутреннее состояние организма, а большие полушария обеспечивают сложное восприятие, речь и мышление"]},{"n":4,"q":"Поля по Бродману: общая характеристика","a":["Поля Бродмана являются участками коры, которые различаются по строению нервных клеток и их слоев. Нумерация помогает описывать расположение областей мозга. Поле 4 связано с произвольными движениями, поля 1, 2 и 3 с телесной чувствительностью, поле 17 со зрением, поля 41 и 42 со слухом. Поля 44 и 45 участвуют в образовании речи, но ни речь, ни мышление не ограничиваются одним полем"]},{"n":5,"q":"Лимбическая система: определение, функции","a":["Лимбической системой называют группу связанных областей мозга, участвующих в эмоциях, мотивации и памяти. К ней обычно относят гиппокамп, миндалевидное тело, поясную кору и ряд связанных структур. Гиппокамп особенно важен для формирования новых воспоминаний, а миндалевидное тело помогает оценивать эмоциональную значимость событий. Границы этой системы определяются по-разному, потому что перечисленные функции выполняются широкими сетями мозга"]},{"n":6,"q":"Ретикулярная формация: определение, функции","a":["Ретикулярная формация представляет собой сеть нервных клеток и связей в стволе мозга. Она помогает поддерживать бодрствование, регулировать сон, мышечный тонус и реакции на важные сигналы. Ее отдельные участки участвуют в управлении дыханием, кровообращением и восприятием боли. Тяжелое повреждение систем поддержания бодрствования может приводить к нарушению сознания"]},{"n":7,"q":"Таламус: общая характеристика","a":["Таламус является парной структурой промежуточного мозга, состоящей из нескольких групп ядер. Через него к коре проходит большая часть чувствительных сигналов, кроме основного пути обоняния. Он не просто передает информацию, а участвует в ее отборе и обработке. Также таламус связан с движениями, вниманием, сном и поддержанием сознания"]},{"n":8,"q":"Миндалевидное тело: общая характеристика, функции","a":["Миндалевидное тело представляет собой группу ядер в глубине височной доли. Оно помогает определять эмоциональную значимость событий, особенно сигналов угрозы. Через связи с другими структурами оно участвует в обучении на эмоциональном опыте и в телесных реакциях на переживания. Его работа не сводится только к страху, она также связана с интересом, наградой и социальными сигналами"]},{"n":9,"q":"Методы исследования ЦНС: краткая характеристика","a":["Неврологический осмотр оценивает сознание, речь, движения, чувствительность, рефлексы и координацию. МРТ и КТ помогают увидеть строение мозга и выявить повреждения, а электроэнцефалография записывает его электрическую активность. Исследование вызванных потенциалов оценивает прохождение сигналов по отдельным путям. В зависимости от задачи также используют анализ спинномозговой жидкости, лабораторные исследования и нейропсихологическое обследование"]},{"n":10,"q":"Сигнальные системы: характеристика","a":["В учении Ивана Павлова первая сигнальная система связана с непосредственными ощущениями и образами предметов. Например, запах пищи сам вызывает определенную реакцию. Вторая сигнальная система связана со словами и другими речевыми обозначениями, которые могут заменять непосредственный сигнал. Эта историческая схема помогает объяснять роль речи, хотя современная нейронаука описывает обработку информации более подробно"]},{"n":11,"q":"Нейрон: определение, строение","a":["Нейрон является нервной клеткой, которая принимает, обрабатывает и передает информацию. В его теле находится ядро, дендриты обычно принимают сигналы, а аксон проводит их к другим клеткам. У многих аксонов есть миелиновая оболочка, ускоряющая проведение импульса. Контакты, через которые нейроны взаимодействуют друг с другом и с клетками органов, называются синапсами"]},{"n":12,"q":"Нейрон: классификация, функции","a":["По функции нейроны делят на чувствительные, двигательные и вставочные. Чувствительные передают сведения от рецепторов, двигательные направляют команды к мышцам и другим исполнительным органам, а вставочные связывают клетки внутри нервной системы. По строению различают, например, мультиполярные, биполярные и псевдоуниполярные нейроны. Одни нейроны преимущественно усиливают активность других клеток, другие преимущественно тормозят ее"]},{"n":13,"q":"Рефлекторная дуга: виды и их характеристика","a":["Рефлекторная дуга представляет собой путь нервного сигнала при рефлексе. Она включает рецептор, чувствительный путь, центральное звено, двигательный путь и орган, выполняющий ответ. Моносинаптическая дуга имеет один центральный синапс, как в основном звене коленного рефлекса. Полисинаптическая дуга содержит вставочные нейроны и обеспечивает более сложную реакцию, например отдергивание руки"]},{"n":14,"q":"Механизм синаптической передачи","a":["В химическом синапсе нервный импульс достигает окончания аксона и вызывает вход кальция в клетку. Это запускает выделение вещества-передатчика, или нейромедиатора, в синаптическую щель. Медиатор связывается с рецепторами следующей клетки и изменяет ее активность. Затем его действие прекращается за счет обратного захвата, разрушения или удаления из щели; в электрических синапсах сигнал проходит через прямые контакты клеток"]},{"n":15,"q":"Нейротрансмиттерные системы: общая характеристика","a":["Нейротрансмиттерные системы объединяют клетки и связи, которые используют определенные вещества для передачи сигналов. Глутамат является основным возбуждающим медиатором мозга, а ГАМК основным тормозным. Ацетилхолин участвует в работе мышц, внимании и памяти, дофамин связан с движением, мотивацией и обучением. Серотонин и норадреналин участвуют в регуляции бодрствования и эмоций, причем результат зависит от рецепторов и конкретной нервной сети"]},{"n":16,"q":"Гематоэнцефалический барьер: определение, функции","a":["Гематоэнцефалический барьер регулирует переход веществ из крови в ткань мозга. Его основу образуют клетки стенок мозговых капилляров с плотными контактами, а поддерживают барьер перициты и отростки астроцитов. Он помогает сохранять стабильную среду для нейронов и ограничивает проникновение многих вредных веществ. При этом он не является непроницаемой стеной: необходимые вещества проходят через специальные механизмы переноса"]},{"n":17,"q":"Рефлексы: характеристика, виды, примеры","a":["Рефлекс представляет собой закономерную ответную реакцию организма, осуществляемую с участием нервной системы. Безусловные рефлексы имеют врожденную основу, например сужение зрачка на свет или отдергивание руки от горячего. Условные рефлексы формируются при обучении, когда ранее нейтральный сигнал начинает предсказывать значимое событие. Также различают соматические и вегетативные рефлексы, а по уровню замыкания выделяют спинальные и разные виды головных рефлексов"]},{"n":18,"q":"Торможение: определение, виды, примеры","a":["Торможение уменьшает вероятность или силу нервного ответа и помогает согласовывать работу системы. Например, при сокращении одной группы мышц активность мышц с противоположным действием может снижаться. В нейрофизиологии выделяют пресинаптическое и постсинаптическое торможение. В учении об условных рефлексах говорят о внешнем торможении при новом отвлекающем сигнале и внутреннем торможении, которое формируется при обучении, например при угасании неподкрепляемой реакции"]},{"n":19,"q":"Двигательный анализатор, как многоуровневая система","a":["Двигательная система объединяет рецепторы мышц и суставов, чувствительные пути, кору, подкорковые структуры, мозжечок, спинной мозг и мышцы. Кора участвует в замысле и запуске произвольного движения, базальные ядра помогают его выбирать, а мозжечок уточняет точность. Спинной мозг организует выполнение команд и простые рефлексы. Постоянная обратная связь сообщает мозгу о положении тела и результате движения"]},{"n":20,"q":"Экстрапирамидная система: структура, функции","a":["Экстрапирамидной системой традиционно называют структуры и пути, которые участвуют в управлении движениями помимо прямого пирамидного пути. В нее включают базальные ядра и связанные с ними области, а также ряд стволовых двигательных путей. Она помогает выбирать и запускать движения, регулировать позу, мышечный тонус и автоматические действия. Ее повреждение может сопровождаться замедленностью движений, скованностью или непроизвольными движениями"]},{"n":21,"q":"Пирамидный путь","a":["Пирамидный путь проводит команды от коры к двигательным центрам спинного мозга и ствола. Он включает корково-спинномозговые и корково-ядерные волокна. Большая часть корково-спинномозговых волокон переходит на противоположную сторону в нижней части продолговатого мозга. Повреждение центральных двигательных путей может вызывать слабость, повышение мышечного тонуса и рефлексов, а также патологический рефлекс Бабинского"]},{"n":22,"q":"Гиперкинезы: определение, виды","a":["Гиперкинезы представляют собой избыточные непроизвольные движения. Тремор выглядит как дрожание, хорея как нерегулярные быстрые движения, а миоклонии как короткие мышечные рывки. Дистония вызывает устойчивые или повторяющиеся сокращения с необычной позой, тики являются повторяющимися движениями или звуками. Причины бывают различными, поэтому вид движения сам по себе еще не определяет диагноз"]},{"n":23,"q":"Сенсорная система: определение, отделы","a":["Сенсорная система принимает и обрабатывает информацию от внешнего мира или организма. В ней выделяют рецепторный отдел, проводящие нервные пути и центральные области обработки. Рецепторы превращают воздействие в нервный сигнал, а мозг определяет его свойства и значение. Примеры включают зрительную, слуховую, соматосенсорную, вкусовую, обонятельную и вестибулярную системы"]},{"n":24,"q":"I, II, III пары черепно-мозговых нервов: название, тип, функции, патологии","a":["I пара, обонятельный нерв, является чувствительной и обеспечивает обоняние; его поражение может приводить к снижению или потере восприятия запахов. II пара, зрительный нерв, является чувствительной и проводит сигналы от сетчатки; поражение вызывает снижение зрения и изменения поля зрения. III пара, глазодвигательный нерв, имеет двигательные и парасимпатические волокна, управляет большинством движений глаза, подниманием века и сужением зрачка. Его поражение может проявляться опущением века, двоением и расширением зрачка"]},{"n":25,"q":"IV, V, VI пары черепно-мозговых нервов: название, тип, функции, патологии","a":["IV пара, блоковый нерв, является двигательной и управляет верхней косой мышцей глаза; поражение часто вызывает вертикальное двоение. V пара, тройничный нерв, является смешанной, обеспечивает чувствительность лица и работу жевательных мышц; возможны боль, онемение и слабость жевания. VI пара, отводящий нерв, является двигательной и отводит глаз наружу. При ее поражении глаз хуже движется кнаружи и возникает горизонтальное двоение"]},{"n":26,"q":"VII, VIII, IX пары черепно-мозговых нервов: название, тип, функции, патологии","a":["VII пара, лицевой нерв, является смешанной, управляет мимическими мышцами, участвует во вкусе передних двух третей языка и работе ряда желез; поражение может вызывать слабость половины лица. VIII пара, преддверно-улитковый нерв, является чувствительной и обеспечивает слух и равновесие; возможны снижение слуха, головокружение и нарушение устойчивости. IX пара, языкоглоточный нерв, является смешанной, участвует во вкусе задней трети языка, чувствительности глотки, глотании и слюноотделении. При ее поражении могут нарушаться глотание и глоточный рефлекс"]},{"n":27,"q":"X, IX, XI пары черепно-мозговых нервов: название, тип, функции, патологии","a":["В исходном вопросе IX пара повторена, а XII пропущена, поэтому здесь дополнительно разобрана XII пара. X пара, блуждающий нерв, является смешанной, участвует в глотании, голосообразовании и регуляции внутренних органов; поражение может вызывать осиплость и затруднение глотания. XI пара, добавочный нерв, является двигательной и управляет поворотом головы и подниманием плеча; поражение вызывает слабость этих движений. XII пара, подъязычный нерв, является двигательной и управляет языком; при периферическом поражении язык слабеет и отклоняется к пораженной стороне, а функции IX пары приведены в предыдущем ответе"]},{"n":28,"q":"Гнозис: определение, виды нарушений и их характеристика","a":["Гнозис представляет собой узнавание предметов и сигналов с использованием прежнего опыта. Агнозия означает нарушение узнавания, которое нельзя объяснить только потерей чувствительности, зрения или слуха. При зрительной агнозии человек видит объект, но затрудняется его узнать, при слуховой не узнает знакомые звуки. При тактильной агнозии трудно узнать предмет на ощупь, а при прозопагнозии нарушается узнавание знакомых лиц"]},{"n":29,"q":"Праксис: определение, виды нарушений и их характеристика","a":["Праксис представляет собой выполнение освоенных целенаправленных действий. Апраксия означает их нарушение, которое не объясняется только мышечной слабостью или непониманием задания. При идеомоторной апраксии трудно выполнить знакомый жест по просьбе, при идеаторной нарушается последовательность сложного действия. При конструктивных нарушениях человеку трудно собрать фигуру или скопировать рисунок, хотя отдельные движения доступны"]},{"n":30,"q":"Менингит:определение,классификация,симптомы","a":["Менингит является воспалением оболочек головного и спинного мозга. По причине он бывает бактериальным, вирусным, грибковым и другим, а по течению острым или хроническим. Возможны высокая температура, сильная головная боль, рвота, светобоязнь и напряжение мышц шеи. У младенцев бывают вялость, отказ от кормления и выбухание родничка; подозрение на менингит требует срочной медицинской оценки"]},{"n":31,"q":"Энцефалит: определение, классификация, симптомы","a":["Энцефалит представляет собой воспаление ткани головного мозга. Он бывает инфекционным, например вирусным, и аутоиммунным, когда иммунная система ошибочно атакует собственные структуры. Возможны лихорадка, головная боль, спутанность сознания, судороги и изменения поведения. Иногда возникают слабость конечностей и нарушение речи; выраженные нарушения сознания и судороги требуют неотложной помощи"]},{"n":32,"q":"Механизм развития первичного менингита","a":["Первичным называют менингит, который развивается без предшествующего явного очага инфекции в другом органе. Возбудитель может сначала размножаться на слизистых, затем попадать в кровь и преодолевать защитные барьеры центральной нервной системы. В оболочках и спинномозговой жидкости развивается воспаление. Оно может повышать внутричерепное давление, нарушать кровоснабжение и повреждать нервную систему"]},{"n":33,"q":"Механизм развития клещевого энцефалита","a":["Возбудителем является вирус клещевого энцефалита, который чаще передается при укусе зараженного клеща. Реже заражение связано с непастеризованным молоком инфицированных животных. Вирус размножается, попадает в кровь и у части заболевших поражает центральную нервную систему. Болезнь может проходить в две фазы и вызывать менингит, энцефалит, слабость или параличи, но поражение мозга развивается не при каждом заражении"]},{"n":34,"q":"Особенности течения менингоэнцефалита у детей","a":["Менингоэнцефалит означает одновременное воспаление мозговых оболочек и ткани мозга. У детей заболевание может быстро приводить к судорогам, нарушению сознания и обезвоживанию. У младенцев типичные признаки раздражения оболочек иногда выражены слабо, а на первый план выходят вялость, раздражительность и плохое кормление. Возможные последствия включают нарушения слуха, движения и развития, но они возникают не у каждого ребенка"]},{"n":35,"q":"Нейросифилис: неврологические и психические нарушения","a":["Нейросифилис является поражением нервной системы бактерией, вызывающей сифилис. Он может развиться на разных стадиях инфекции. Возможны головная боль, менингит, нарушения чувствительности, координации и зрения, а при поражении сосудов инсульт. Некоторые формы сопровождаются ухудшением памяти, изменением поведения или другими психическими нарушениями; подтверждение требует медицинского обследования"]},{"n":36,"q":"НейроСПИД: неврологические и психические нарушения","a":["ВИЧ может влиять на нервную систему непосредственно и через снижение иммунной защиты. Возможны поражение периферических нервов, замедление мышления, трудности внимания и памяти. При выраженном иммунодефиците риск тяжелых инфекций мозга и некоторых опухолей возрастает. Современная антиретровирусная терапия значительно уменьшает эти риски, поэтому тяжелое поражение нервной системы не является неизбежным"]},{"n":37,"q":"Менингоэнцефалит у детей: симптомы, неврологические и психические проявления при тяжелых формах","a":["При тяжелом течении возможны высокая температура, повторная рвота, судороги, выраженная сонливость, спутанность сознания или кома. Неврологические проявления включают слабость конечностей, нарушение речи, координации и работы черепных нервов. Иногда возникают возбуждение, необычное поведение и снижение контакта с окружающими. После болезни у части детей сохраняются трудности обучения, слуха или движения, поэтому важны наблюдение и реабилитация"]},{"n":38,"q":"Нервно-мышечные заболевания: определение, виды, механизм развития","a":["Нервно-мышечные заболевания нарушают работу двигательных нейронов, периферических нервов, нервно-мышечного соединения или самих мышц. К ним относятся, например, спинальная мышечная атрофия, некоторые полинейропатии, миастения и мышечные дистрофии. Причинами бывают изменения генов, иммунные нарушения и другие повреждающие процессы. Общие проявления включают мышечную слабость, утомляемость и иногда уменьшение объема мышц, но механизм у разных болезней различается"]},{"n":39,"q":"Нейродегенеративные заболевания: определение, виды, механизм развития","a":["Нейродегенеративные заболевания связаны с постепенным нарушением работы и гибелью определенных групп нервных клеток. К ним относятся болезни Альцгеймера, Паркинсона, Гентингтона и боковой амиотрофический склероз. В развитии могут участвовать наследственные изменения, накопление измененных белков и нарушения работы клеток. В зависимости от пораженных сетей страдают память, поведение, движения или мышечная сила"]},{"n":40,"q":"Болезнь паркинсона: общая характеристика","a":["Болезнь Паркинсона является прогрессирующим заболеванием, при котором особенно страдают клетки, вырабатывающие дофамин в черной субстанции. Главные двигательные проявления включают замедленность, скованность и часто дрожание в покое. Возможны нарушения сна, обоняния, настроения и работы кишечника. Лечение помогает уменьшать проявления болезни, а ухудшение памяти возникает не у всех пациентов"]},{"n":41,"q":"Хорея Гентингтона: общая характеристика","a":["Болезнь Гентингтона является наследственным заболеванием, связанным с изменением гена HTT. Оно может вызывать непроизвольные движения, изменения поведения и постепенное ухудшение мышления. Болезнь обычно передается по аутосомно-доминантному типу: у ребенка родителя с одной измененной копией гена риск ее унаследовать составляет 50 процентов. Проявления и возраст начала различаются, а оценка наследственного риска проводится с генетическим консультированием"]},{"n":42,"q":"Боковой амиотрофический склероз: общая характеристика","a":["Боковой амиотрофический склероз, или БАС, поражает двигательные нейроны головного и спинного мозга. Постепенно нарастают слабость и уменьшение объема мышц, могут возникать мышечные подергивания, скованность, нарушения речи и глотания. При поражении дыхательных мышц затрудняется дыхание. Чувствительность часто остается относительно сохранной, но у части людей возможны изменения мышления и поведения"]},{"n":43,"q":"Эпилепсия: этиология, механизм развития","a":["Эпилепсия является заболеванием мозга с устойчивой склонностью к повторным эпилептическим приступам. Приступ возникает из-за чрезмерной согласованной электрической активности определенных групп нейронов. Причины могут быть генетическими, структурными, инфекционными, обменными, иммунными или оставаться неизвестными. Один приступ, например на фоне высокой температуры, не всегда означает эпилепсию"]},{"n":44,"q":"Варианты припадков и их клинические проявления","a":["Приступ может начинаться в ограниченной сети одного полушария, тогда его называют фокальным, или сразу вовлекать двусторонние сети, тогда говорят о генерализованном начале. Фокальные приступы могут проходить с сохранением или нарушением осознания происходящего. Тонико-клонический приступ сопровождается напряжением и ритмическими сокращениями мышц, миоклонический короткими рывками, а атонический внезапной потерей тонуса. Некоторые приступы проявляются только кратким замиранием или необычными ощущениями"]},{"n":45,"q":"Абсанс: общая характеристика. Особенности у детей","a":["Абсанс представляет собой короткий генерализованный приступ с внезапным нарушением сознания. Ребенок на несколько секунд замирает, перестает отвечать, иногда часто моргает, а затем быстро продолжает действие. Такие эпизоды могут повторяться и мешать усвоению учебного материала. Их иногда принимают за невнимательность, поэтому для уточнения причины требуется обследование, часто с электроэнцефалографией"]},{"n":46,"q":"Изменения личности при эпилепсии","a":["Единого обязательного типа личности при эпилепсии не существует. У части людей встречаются тревога, депрессия, трудности внимания, памяти или поведения, но они зависят от многих причин. Влияют сама болезнь, ее причина, частота приступов, лекарства и отношение окружающих. Нельзя считать раздражительность или другие особенности неизбежными признаками любого человека с эпилепсией"]},{"n":47,"q":"Система координации человека. Функция нервно-мышечного аппарата мозжечка, развитие двигательных качеств","a":["Координация помогает выполнять движения точно, плавно и в нужной последовательности. Мозжечок сравнивает план движения с поступающими сигналами от тела и помогает исправлять ошибки. Мышцы, сухожилия и суставы обеспечивают выполнение движения и обратную связь. Сила, скорость, выносливость и координация развиваются при постепенной практике с учетом возраста и состояния здоровья"]},{"n":48,"q":"Система движения человека. Развитие центров движения в коре головного мозга","a":["Движение обеспечивается совместной работой коры, базальных ядер, мозжечка, ствола, спинного мозга, нервов и мышц. Первичная двигательная кора посылает команды, а премоторные области помогают подготовить последовательность действий. У ребенка нервные связи созревают и меняются под влиянием движения и обучения. Повторение, игра и разнообразная двигательная практика помогают формировать навыки, но темп развития у детей различается"]},{"n":49,"q":"Анатомия, физиология и патология органов чувств человека. Общие представления об интуиции, нейрофизиологические основы интуиции","a":["Органы чувств воспринимают свет, звук, запах, вкус и другие воздействия, а нервная система превращает сигналы в ощущения и образы. Нарушения могут возникать на уровне рецепторов, проводящих путей или мозговых центров. Интуицией называют быстрое понимание или решение без полного осознания промежуточных рассуждений. Ее связывают с неосознанным распознаванием знакомых закономерностей и накопленным опытом; отдельного органа интуиции нет, а такие решения могут быть ошибочными"]},{"n":50,"q":"Зрительный анализатор. Анатомия и физиология органа зрения","a":["Зрительная система включает глаз, зрительные нервные пути и области мозга, обрабатывающие изображение. Роговица и хрусталик преломляют свет и направляют его на сетчатку. Палочки помогают видеть при слабом освещении, колбочки обеспечивают цветовое зрение и различение мелких деталей. Сигналы идут по зрительному нерву, частично перекрещиваются и через промежуточные центры поступают в затылочную кору"]},{"n":51,"q":"Зрительный анализатор и его функции. Патологии органов зрения","a":["Зрение позволяет различать форму, цвет, движение, расстояние и положение предметов. При близорукости изображение удаленного предмета фокусируется перед сетчаткой, при дальнозоркости без достаточной аккомодации за ней, а при астигматизме фокусировка искажена. Другие нарушения включают катаракту, глаукому, болезни сетчатки и зрительного нерва. Косоглазие нарушает согласованность положения глаз, а амблиопия означает снижение зрения из-за нарушенного зрительного развития"]},{"n":52,"q":"Физиологические особенности ребенка с нарушением зрения","a":["Особенности зависят от причины, выраженности и времени появления зрительного нарушения. Ребенку может быть труднее ориентироваться, узнавать удаленные предметы, следить за мелкими деталями и согласовывать движения со зрением. Он может сильнее опираться на слух, осязание и движение, но автоматического усиления всех остальных чувств не происходит. Помогают подходящие контраст и освещение, доступные материалы, обучение ориентировке и использование сохранного зрения по рекомендациям специалистов"]}],"sources":["NINDS Основы строения и работы мозга","NCBI Bookshelf Ствол головного мозга","NCBI Bookshelf Ретикулярная формация","Исследование функций черепных нервов","ВОЗ Менингит","CDC Клещевой энцефалит","CDC Сифилис и поражение нервной системы","NIH Болезнь Гентингтона","NIH Боковой амиотрофический склероз","NINDS Эпилепсия и приступы","National Eye Institute Как работает зрение","National Eye Institute Здоровье зрения у детей"]},{"id":"psy","short":"Психология","name":"ПК Психология","title":"Ответы по общей психологии","subtitle":"33 билета с ответами на каждый вопрос","tickets":true,"items":[{"n":1,"q":"Предмет и задачи общей психологии","a":["Общая психология изучает психику и поведение человека. Она объясняет, как человек воспринимает мир, запоминает, думает, переживает и действует. Ее задачи состоят в описании психических явлений, изучении их причин и поиске способов помочь человеку учиться, общаться и справляться с трудностями. Например, изучая обучение, психолог выясняет, почему один способ объяснения помогает ученику, а другой вызывает трудности. Знания используют"],"t":1},{"n":2,"q":"Основная структура психики","a":["В психике выделяют процессы, состояния и свойства. Процессы включают ощущения, восприятие, память, мышление, эмоции и волевые действия. Состояния показывают, что человек переживает сейчас, например усталость или тревогу. Свойства являются относительно устойчивыми особенностями, к ним относятся темперамент, характер и способности. Например, запоминание стихотворения является процессом, усталость во время занятия является состоянием, а привычная настойчивость человека относится к относительно устойчивым свойствам"],"t":1},{"n":3,"q":"История развития науки и этапы становления психологии как науки","a":["Сначала представления о душе и поведении развивались внутри философии. Позже ученые стали связывать психические явления с работой мозга и органов чувств. В 1879 году Вильгельм Вундт открыл в Лейпциге лабораторию экспериментальной психологии, что обычно считают началом психологии как самостоятельной науки. В дальнейшем появились разные школы и практические направления. Переход к эксперименту позволил проверять предположения с помощью наблюдений и измерений. Сегодня исследования соединяют изучение поведения, опыта и работы мозга"],"t":1},{"n":1,"q":"Основные направления психологии в 20 веке","a":["Бихевиоризм изучал поведение и обучение через связь ситуации с реакцией. Психоанализ обращал внимание на бессознательные переживания и внутренние конфликты. Гештальтпсихология рассматривала восприятие как целостный процесс. Гуманистическая психология изучала личностный рост, когнитивная психология исследовала обработку информации, а деятельностный подход связывал развитие психики с деятельностью и общением. Разные направления рассматривают один вопрос с разных сторон. Например, обучение можно объяснять через подкрепление поведения, работу памяти или деятельность ребенка со взрослым"],"t":2},{"n":2,"q":"Понятие о методах психологического исследования","a":["Наблюдение позволяет изучать поведение в обычных или специально созданных условиях. Эксперимент помогает проверить, как изменение одного условия влияет на другое. Также применяют беседу, анкеты, психологические тесты и анализ результатов деятельности. Для надежных выводов важно учитывать условия исследования, особенности участников и возможность других объяснений. Например, чтобы оценить пользу учебного приема, сравнивают результаты при разных условиях. Один случай не позволяет сделать вывод обо всех людях"],"t":2},{"n":3,"q":"Понятие о методах практической психологии","a":["Практическая психология использует диагностику, консультирование, психологическое просвещение, тренинги и коррекционные занятия. Диагностика помогает понять особенности и трудности человека, а консультирование помогает найти способы их решения. Тренинги развивают конкретные навыки, например общение или управление эмоциями. Выбор метода зависит от задачи, возраста и состояния человека. Например, психолог может выяснить причины трудностей общения и предложить упражнения. При этом важно учитывать согласие человека и сохранять личную информацию"],"t":2},{"n":1,"q":"Понятие о мотиве и мотивации","a":["Мотив является внутренней причиной, ради которой человек действует. Например, ученик занимается, чтобы узнать новое, получить хорошую оценку или порадовать родителей. Мотивация представляет собой совокупность мотивов, потребностей и целей, которые направляют поведение. Одна деятельность может поддерживаться сразу несколькими мотивами. Мотив отвечает на вопрос, зачем человек действует, а цель показывает желаемый результат. Например, интерес к профессии побуждает готовиться к экзамену"],"t":3},{"n":2,"q":"Виды мотивов. Осознанные и неосознаваемые мотивы. Локус контроля личности","a":["Мотивы бывают внутренними, когда человеку интересна сама деятельность, и внешними, когда он стремится к награде или избегает наказания. Осознанные мотивы человек может объяснить, а неосознаваемые влияют на него без ясного понимания причин. Локус контроля показывает, с чем человек связывает результаты: с собственными действиями или преимущественно с внешними обстоятельствами. Реальные события обычно зависят и от человека, и от условий. Например, после неудачи человек может изменить способ подготовки или объяснить все случайностью. Полезно замечать обстоятельства, на которые можно повлиять своими действиями"],"t":3},{"n":3,"q":"Общая характеристика общения и его видов","a":["Общение представляет собой установление и развитие контактов между людьми. Через него люди обмениваются информацией, понимают друг друга и согласуют действия. Оно бывает личным и деловым, непосредственным и дистанционным, словесным и невербальным. В общении обычно выделяют обмен сообщениями, восприятие собеседника и взаимодействие. Невербальное общение включает жесты, позу, мимику и интонацию. Их смысл зависит от ситуации, поэтому один жест нельзя считать признаком намерений"],"t":3},{"n":1,"q":"Перцептивная сторона общения. Стереотипы восприятия собеседника","a":["Перцептивная сторона общения связана с тем, как мы воспринимаем и понимаем другого человека. Мы обращаем внимание на слова, выражение лица, голос и поступки. Стереотип представляет собой привычное обобщенное мнение о группе людей, которое может мешать видеть особенности конкретного собеседника. Первое впечатление полезно проверять по дальнейшему поведению человека. Например, молчание собеседника может означать усталость, смущение или желание подумать. Уточнение ситуации помогает избежать поспешного вывода о характере и отношении"],"t":4},{"n":2,"q":"Коммуникативная сторона общения","a":["Коммуникативная сторона общения означает обмен информацией. Для него нужны понятные слова, общий смысл сообщения и обратная связь. Недопонимание возникает из-за шума, разных значений слов, невнимания или сильных эмоций. Помогают уточняющие вопросы, спокойная речь и умение слушать. Обратная связь показывает, как собеседник понял сообщение. Например, пересказ задания своими словами помогает обнаружить и исправить недопонимание до начала работы"],"t":4},{"n":3,"q":"Общение как взаимодействие","a":["Взаимодействие является стороной общения, при которой люди согласуют свои действия и влияют друг на друга. Оно может проходить в форме сотрудничества, соперничества или конфликта. Например, при выполнении общего задания участники распределяют роли и договариваются о правилах. Успешное взаимодействие требует учета целей и интересов каждого. Например, при групповом проекте важно договориться, кто собирает сведения, кто оформляет результат и когда работа должна быть закончена. Это уменьшает недоразумения"],"t":4},{"n":1,"q":"Понятие о внимании","a":["Внимание представляет собой направленность и сосредоточенность психической деятельности на определенном объекте. Оно помогает выделить нужную информацию и временно отвлечься от лишнего. Например, во время чтения человек следит за смыслом текста, хотя вокруг слышны другие звуки. Внимание сопровождает восприятие, память, мышление и другие процессы. Удержание внимания зависит от интереса, сложности задания и самочувствия. Если материал слишком трудный или однообразный, сосредоточиться на нем обычно бывает сложнее"],"t":5},{"n":2,"q":"Основные свойства внимания и ее виды","a":["Основные свойства внимания включают концентрацию, устойчивость, объем, распределение и переключение. Концентрация показывает глубину сосредоточения, устойчивость означает его сохранение во времени, а объем отражает количество одновременно охватываемых объектов. Распределение помогает следить за несколькими действиями, переключение позволяет переходить от одного к другому. По участию воли различают непроизвольное, произвольное и послепроизвольное внимание. Например, устойчивость нужна для чтения, а переключение помогает перейти от чтения к решению задачи. Эти свойства могут развиваться неравномерно"],"t":5},{"n":3,"q":"Развитие внимания","a":["У маленьких детей внимание чаще привлекают яркие, новые и эмоционально значимые события. Постепенно ребенок учится удерживать цель и действовать по правилу. Внимание развивают игры на поиск отличий, выполнение коротких инструкций и задания с постепенным увеличением сложности. Помогают понятная цель, интерес, перерывы и отсутствие лишних отвлекающих предметов. Лучше начинать с коротких заданий и постепенно увеличивать время работы. Полезно заранее объяснять правило и замечать даже небольшие успехи ребенка"],"t":5},{"n":1,"q":"Понятие об ощущении. Виды ощущений","a":["Ощущение является отражением отдельного свойства предмета или состояния организма при воздействии на рецепторы. Оно позволяет почувствовать цвет, звук, запах, вкус, прикосновение или положение тела. Выделяют ощущения от внешнего мира, от внутренних органов и от мышц, суставов и вестибулярного аппарата. Целостный образ предмета формируется уже на уровне восприятия. Например, ощущение холода сообщает о температуре, а мышечное чувство помогает определить положение руки. Сигналы направляют действия и защищают организм"],"t":6},{"n":2,"q":"Свойства ощущений","a":["Ощущения характеризуются качеством, интенсивностью, длительностью и местом возникновения. Качество отличает один вид ощущения от другого, например вкус от звука. Порог чувствительности показывает, какое минимальное воздействие человек может заметить. При длительном действии раздражителя чувствительность может меняться, этот процесс называют адаптацией. Например, после входа в темную комнату предметы видны плохо. Постепенно чувствительность зрения меняется, и человек начинает различать больше деталей"],"t":6},{"n":3,"q":"Сенсорное развитие детей","a":["Сенсорное развитие означает развитие ощущений и восприятия. Ребенок учится различать цвет, форму, размер, звуки, запахи и свойства поверхности. Этому помогают игры с безопасными предметами, сортировка, рисование, музыка и движение. Взрослый называет свойства предметов и дает ребенку возможность сравнивать их в разных действиях. Например, можно предложить подобрать одинаковые по форме фигуры или найти мягкий предмет среди твердых. Такие задания связывают ощущения с действиями"],"t":6},{"n":1,"q":"Психологическая характеристика восприятия","a":["Восприятие позволяет получить целостный образ предмета или события. Например, мы узнаем яблоко по сочетанию формы, цвета, запаха и прежнего опыта. Оно связано с вниманием, памятью, речью и действиями человека. Поэтому один и тот же объект разные люди могут воспринимать немного по-разному. Восприятие зависит и от задачи наблюдения. Художник может замечать сочетания цветов, а покупатель прежде всего обращает внимание на состояние предмета"],"t":7},{"n":2,"q":"Виды и свойства восприятия","a":["По ведущему органу чувств различают зрительное, слуховое, осязательное и другие виды восприятия. Также выделяют восприятие пространства, времени и движения. Его основные свойства включают предметность, целостность, осмысленность, избирательность и относительное постоянство образа. Например, знакомый предмет узнается при разном освещении и с разных сторон. Осмысленность помогает узнать предмет и понять его назначение. Избирательность проявляется, когда человек выделяет нужный объект, а остальные воспринимает как окружающий фон"],"t":7},{"n":3,"q":"Иллюзии в восприятии","a":["Иллюзия представляет собой ошибочное восприятие реально существующего объекта. Например, одинаковые линии могут казаться разными по длине из-за окружающего рисунка. Причинами бывают особенности органов чувств, условия наблюдения, ожидания и эмоциональное состояние. Иллюзии встречаются и у здоровых людей, а при галлюцинации соответствующий внешний объект отсутствует. Например, неподвижные изображения иногда создают впечатление движения. Проверить впечатление помогают изменение точки наблюдения, измерение объекта и сравнение его с другими предметами"],"t":7},{"n":1,"q":"Свойства внимания","a":["Основные свойства внимания включают концентрацию, устойчивость, объем, распределение и переключение. Концентрация показывает глубину сосредоточения, устойчивость означает его сохранение во времени, а объем отражает количество одновременно охватываемых объектов. Распределение помогает следить за несколькими действиями, переключение позволяет переходить от одного к другому. По участию воли различают непроизвольное, произвольное и послепроизвольное внимание. Например, устойчивость нужна для чтения, а переключение помогает перейти от чтения к решению задачи. Эти свойства могут развиваться неравномерно"],"t":8},{"n":2,"q":"Развитие процесса восприятия и наблюдательности у детей","a":["Сначала ребенок чаще замечает самые яркие признаки предмета, а затем учится рассматривать его последовательно. Наблюдательность развивается, когда взрослый предлагает сравнить предметы, найти изменения, описать детали и объяснить различия. Полезны прогулки с наблюдением, рисование с натуры и игры на поиск признаков. Важно учить ребенка проверять свои впечатления. Например, при наблюдении за растением можно рассмотреть листья, стебель и цвет. Такой план помогает замечать не только самые яркие признаки"],"t":8},{"n":3,"q":"Понятие о памяти. Виды памяти","a":["Память позволяет сохранять опыт и использовать его позднее. По содержанию различают двигательную, образную, эмоциональную и словесно-логическую память. По длительности хранения выделяют сенсорную, кратковременную и долговременную память. Рабочая память временно удерживает информацию и помогает выполнять с ней текущие действия, например считать в уме. Разные виды памяти дополняют друг друга. При изучении танца человек запоминает движения, музыку и объяснения преподавателя, а затем соединяет их при исполнении"],"t":8},{"n":1,"q":"Процессы памяти","a":["Основные процессы памяти включают запоминание, сохранение, воспроизведение, узнавание и забывание. Запоминание может происходить специально или без поставленной цели. Смысловые связи и распределенное повторение обычно помогают запомнить материал лучше, чем механическое заучивание без понимания. Забывание связано с ослаблением доступности следов памяти, помехами и недостатком подходящих подсказок. Узнавание происходит при повторной встрече с материалом, а воспроизведение требует вспомнить его самостоятельно. Поэтому знакомый текст еще не всегда удается пересказать"],"t":9},{"n":2,"q":"Психологическая характеристика мышления. Виды мышления","a":["Мышление помогает находить связи, понимать причины и решать задачи, которые нельзя решить только прямым наблюдением. Наглядно-действенное мышление опирается на действия с предметами, наглядно-образное использует образы, а словесно-логическое связано с понятиями и рассуждениями. Эти виды не исключают друг друга и могут работать вместе. Мышление развивается в обучении, практике и общении. Например, собирая конструктор, ребенок пробует детали действием, представляет постройку и объясняет план словами. В одной задаче участвуют разные способы мышления"],"t":9},{"n":3,"q":"Творческое мышление","a":["Творческое мышление помогает находить новые и полезные способы решения задачи. Его признаки включают гибкость, оригинальность, умение предлагать разные варианты и видеть необычные связи. Например, ребенок придумывает несколько способов построить мост из доступных материалов. Для творчества нужны знания, интерес, возможность пробовать и готовность исправлять ошибки. Полезно сначала предложить идеи, а затем оценить их пригодность. Слишком ранняя критика может мешать поиску, но решение требует проверки"],"t":9},{"n":1,"q":"Социальное мышление","a":["Социальное мышление помогает понимать людей, их намерения, отношения и правила совместной жизни. Оно используется, когда мы объясняем чужой поступок, оцениваем ситуацию общения или предполагаем реакцию собеседника. На него влияют опыт, эмоции, стереотипы и культурные нормы. Более точному пониманию помогают учет разных точек зрения и проверка своих предположений. Например, человек предполагает, что друг сердится, потому что тот молчит. Причиной может быть усталость, поэтому догадку уточнить в разговоре"],"t":10},{"n":2,"q":"Механизмы воображения","a":["Воображение преобразует знакомые образы и создает из них новые сочетания. Агглютинация соединяет части разных объектов, например образ русалки. Гиперболизация увеличивает или уменьшает признаки, акцентирование выделяет отдельную черту, схематизация упрощает образ. Типизация объединяет характерные черты многих людей или событий в одном образе. Например, великан создается через преувеличение размеров, а персонаж может соединять черты разных существ. Новизна образа возникает из преобразования знакомого опыта"],"t":10},{"n":3,"q":"Понятие о воображении","a":["Воображение представляет собой создание образов того, что человек сейчас непосредственно не воспринимает. Оно опирается на прежний опыт, но может выходить за его привычные сочетания. Воображение помогает планировать, придумывать, понимать художественные произведения и представлять будущее. Его результаты могут быть реалистичными или фантастическими. Например, перед выступлением ученик представляет аудиторию и последовательность действий. Такой образ помогает подготовиться, хотя ситуация может отличаться от ожидаемой"],"t":10},{"n":1,"q":"Механизмы и виды воображения","a":["Воображение бывает произвольным, когда человек намеренно создает образ, и непроизвольным, когда образы возникают без специальной цели. Воссоздающее воображение помогает представить объект по описанию, а творческое создает новые образы. Активное воображение связано с задачами и действиями, пассивное может ограничиваться мечтами. Основные механизмы включают соединение, изменение, выделение и обобщение знакомых признаков. Например, представление города по описанию является воссоздающим воображением, а создание сказочного города является творческим. При этом оба варианта используют опыт"],"t":11},{"n":2,"q":"Развитие воображения у детей","a":["Воображение развивается вместе с речью, игрой, памятью и расширением опыта. В сюжетной игре ребенок заменяет одни предметы другими и берет на себя разные роли. Полезны сочинение историй, рисование, конструирование и обсуждение того, как можно продолжить сказку. Взрослому важно поддерживать самостоятельные идеи и помогать отличать вымысел от реальных событий. Например, ребенку можно предложить придумать несколько назначений коробки. Чем разнообразнее его впечатления и действия, тем больше материала появляется для образов"],"t":11},{"n":3,"q":"Виды внимания","a":["Непроизвольное внимание возникает само, например при громком звуке или появлении нового предмета. Произвольное внимание требует цели и усилия, например при выполнении трудного задания. Послепроизвольное внимание появляется, когда человек сначала заставляет себя заниматься, а затем увлекается работой. В реальной деятельности эти виды часто переходят один в другой. Например, школьник выполняет упражнение по требованию учителя, а потом увлекается поиском решения. Тогда необходимость заставлять себя заниматься может уменьшаться"],"t":11},{"n":1,"q":"Развитие процесса восприятия и наблюдательности у детей","a":["Сначала ребенок чаще замечает самые яркие признаки предмета, а затем учится рассматривать его последовательно. Наблюдательность развивается, когда взрослый предлагает сравнить предметы, найти изменения, описать детали и объяснить различия. Полезны прогулки с наблюдением, рисование с натуры и игры на поиск признаков. Важно учить ребенка проверять свои впечатления. Например, при наблюдении за растением можно рассмотреть листья, стебель и цвет. Такой план помогает замечать не только самые яркие признаки"],"t":12},{"n":2,"q":"Понятие о памяти. Значение памяти в жизни и деятельности человека","a":["Память сохраняет знания, навыки, впечатления и личный опыт. Благодаря ей человек узнает близких, понимает речь, учится и продолжает начатую работу. Она помогает поддерживать чувство непрерывности собственной жизни и учитывать прошлые ошибки. Без памяти было бы невозможно устойчивое обучение и накопление опыта. Например, опыт помогает выбрать знакомый маршрут и выполнить работу. При этом воспоминания могут меняться, поэтому память не является точной записью прошлого"],"t":12},{"n":3,"q":"Физиологические механизмы памяти","a":["Память связана с изменениями в работе нервных клеток и связей между ними. Когда информация повторяется и используется, некоторые связи укрепляются. Гиппокамп особенно важен для формирования новых воспоминаний о событиях, а долговременные следы распределены по разным участкам мозга. Сон помогает закреплению усвоенного материала. Разные виды обучения задействуют разные системы. Например, освоение двигательного навыка и запоминание рассказа частично опираются на разные сети нервных клеток"],"t":12},{"n":1,"q":"Процессы памяти","a":["Основные процессы памяти включают запоминание, сохранение, воспроизведение, узнавание и забывание. Запоминание может происходить специально или без поставленной цели. Смысловые связи и распределенное повторение обычно помогают запомнить материал лучше, чем механическое заучивание без понимания. Забывание связано с ослаблением доступности следов памяти, помехами и недостатком подходящих подсказок. Узнавание происходит при повторной встрече с материалом, а воспроизведение требует вспомнить его самостоятельно. Поэтому знакомый текст еще не всегда удается пересказать"],"t":13},{"n":2,"q":"Эффект Зейгарник","a":["Эффект Зейгарник описывает склонность лучше помнить прерванные или незавершенные действия, чем законченные. Один из вариантов объяснения состоит в том, что незавершенная задача продолжает удерживать внимание. Эффект связан с исследованиями Блюмы Зейгарник. Он зависит от условий, поэтому не означает, что любое незаконченное дело обязательно запомнится лучше. Например, прерванное задание иногда продолжает возникать в мыслях после занятия. Однако интерес, важность задачи и наличие других дел могут изменять этот результат"],"t":13},{"n":3,"q":"Развитие памяти","a":["Развитие памяти связано с появлением осмысленного запоминания и специальных приемов. Помогают группировка материала, составление плана, связь нового с известным и повторение через промежутки времени. Полезно не только перечитывать, но и пробовать вспомнить ответ без подсказки. У детей запоминание постепенно становится более целенаправленным и связанным с речью. Например, новые слова можно объединить по темам и придумать с ними предложения. Для ребенка полезно связывать запоминание с понятной задачей"],"t":13},{"n":1,"q":"Психологическая характеристика мышления","a":["Мышление помогает находить связи, понимать причины и решать задачи, которые нельзя решить только прямым наблюдением. Наглядно-действенное мышление опирается на действия с предметами, наглядно-образное использует образы, а словесно-логическое связано с понятиями и рассуждениями. Эти виды не исключают друг друга и могут работать вместе. Мышление развивается в обучении, практике и общении. Например, собирая конструктор, ребенок пробует детали действием, представляет постройку и объясняет план словами. В одной задаче участвуют разные способы мышления"],"t":14},{"n":2,"q":"Операции мышления","a":["Анализ разделяет объект на части, а синтез объединяет части в целое. Сравнение позволяет найти сходства и различия, обобщение объединяет предметы по общему признаку. Абстрагирование выделяет важную сторону и временно отвлекается от остальных. Конкретизация помогает объяснить общее правило на отдельном примере. Например, сравнивая два растения, ребенок выделяет форму листьев и размер. Затем он объединяет похожие растения в группу по общему признаку"],"t":14},{"n":3,"q":"Виды мышления","a":["Мышление помогает находить связи, понимать причины и решать задачи, которые нельзя решить только прямым наблюдением. Наглядно-действенное мышление опирается на действия с предметами, наглядно-образное использует образы, а словесно-логическое связано с понятиями и рассуждениями. Эти виды не исключают друг друга и могут работать вместе. Мышление развивается в обучении, практике и общении. Например, собирая конструктор, ребенок пробует детали действием, представляет постройку и объясняет план словами. В одной задаче участвуют разные способы мышления"],"t":14},{"n":1,"q":"Творческое мышление","a":["Творческое мышление помогает находить новые и полезные способы решения задачи. Его признаки включают гибкость, оригинальность, умение предлагать разные варианты и видеть необычные связи. Например, ребенок придумывает несколько способов построить мост из доступных материалов. Для творчества нужны знания, интерес, возможность пробовать и готовность исправлять ошибки. Полезно сначала предложить идеи, а затем оценить их пригодность. Слишком ранняя критика может мешать поиску, но решение требует проверки"],"t":15},{"n":2,"q":"Позитивное мышление","a":["Позитивное мышление означает привычку замечать возможности и искать конструктивный выход из трудностей. Оно не требует отрицать проблемы или запрещать себе неприятные эмоции. Например, неудачу можно рассматривать как повод изменить способ подготовки. Полезное позитивное мышление опирается на факты, реалистичные ожидания и конкретные действия. Например, вместо мысли о неспособности к учебе человек замечает пробел. После этого он выбирает упражнение и проверяет результат подготовки"],"t":15},{"n":3,"q":"Социальное мышление","a":["Социальное мышление помогает понимать людей, их намерения, отношения и правила совместной жизни. Оно используется, когда мы объясняем чужой поступок, оцениваем ситуацию общения или предполагаем реакцию собеседника. На него влияют опыт, эмоции, стереотипы и культурные нормы. Более точному пониманию помогают учет разных точек зрения и проверка своих предположений. Например, человек предполагает, что друг сердится, потому что тот молчит. Причиной может быть усталость, поэтому догадку уточнить в разговоре"],"t":15},{"n":1,"q":"Личностные особенности людей с творческим мышлением","a":["Творчеству часто помогают любознательность, открытость новому опыту, самостоятельность и настойчивость. Важны готовность рассматривать несколько решений и спокойное отношение к неопределенности. Эти особенности не означают, что творческий человек всегда необычно себя ведет или обязательно обладает всеми названными качествами. Творческие навыки можно развивать практикой и обратной связью. Помогает среда, где можно задавать вопросы и предлагать варианты без насмешек. При этом настойчивость позволяет довести идею до работающего результата"],"t":16},{"n":2,"q":"Развитие мышления","a":["Мышление развивается в действиях с предметами, общении и обучении. Ребенок постепенно учится сравнивать, выделять признаки, понимать причины и пользоваться понятиями. Развитию помогают задачи с объяснением решения, вопросы о причинах, обсуждение разных вариантов и практические опыты. Важно давать задания посильной сложности и поддерживать самостоятельное рассуждение. Например, после решения задачи полезно попросить ребенка объяснить свой выбор и найти способ. Так он учится замечать ход собственного рассуждения"],"t":16},{"n":3,"q":"Понятие о воображении","a":["Воображение представляет собой создание образов того, что человек сейчас непосредственно не воспринимает. Оно опирается на прежний опыт, но может выходить за его привычные сочетания. Воображение помогает планировать, придумывать, понимать художественные произведения и представлять будущее. Его результаты могут быть реалистичными или фантастическими. Например, перед выступлением ученик представляет аудиторию и последовательность действий. Такой образ помогает подготовиться, хотя ситуация может отличаться от ожидаемой"],"t":16},{"n":1,"q":"Механизмы воображения","a":["Воображение преобразует знакомые образы и создает из них новые сочетания. Агглютинация соединяет части разных объектов, например образ русалки. Гиперболизация увеличивает или уменьшает признаки, акцентирование выделяет отдельную черту, схематизация упрощает образ. Типизация объединяет характерные черты многих людей или событий в одном образе. Например, великан создается через преувеличение размеров, а персонаж может соединять черты разных существ. Новизна образа возникает из преобразования знакомого опыта"],"t":17},{"n":2,"q":"Виды воображения","a":["Воображение бывает произвольным, когда человек намеренно создает образ, и непроизвольным, когда образы возникают без специальной цели. Воссоздающее воображение помогает представить объект по описанию, а творческое создает новые образы. Активное воображение связано с задачами и действиями, пассивное может ограничиваться мечтами. Основные механизмы включают соединение, изменение, выделение и обобщение знакомых признаков. Например, представление города по описанию является воссоздающим воображением, а создание сказочного города является творческим. При этом оба варианта используют опыт"],"t":17},{"n":3,"q":"Воображение и органические процессы личности","a":["Воображаемые события могут вызывать реальные телесные реакции. Например, представление опасности способно учащать сердцебиение, а мысленный образ еды может усиливать слюноотделение. Это связано с общей работой мозга, эмоций и вегетативной нервной системы. Воображение влияет на самочувствие, но не дает человеку полного контроля над работой организма. Например, мысленная подготовка к знакомому действию может помогать настроиться на его выполнение. Однако она не заменяет реальную тренировку и необходимую помощь"],"t":17},{"n":1,"q":"Развитие воображения у детей","a":["Воображение развивается вместе с речью, игрой, памятью и расширением опыта. В сюжетной игре ребенок заменяет одни предметы другими и берет на себя разные роли. Полезны сочинение историй, рисование, конструирование и обсуждение того, как можно продолжить сказку. Взрослому важно поддерживать самостоятельные идеи и помогать отличать вымысел от реальных событий. Например, ребенку можно предложить придумать несколько назначений коробки. Чем разнообразнее его впечатления и действия, тем больше материала появляется для образов"],"t":18},{"n":2,"q":"Понятие о внимании","a":["Внимание представляет собой направленность и сосредоточенность психической деятельности на определенном объекте. Оно помогает выделить нужную информацию и временно отвлечься от лишнего. Например, во время чтения человек следит за смыслом текста, хотя вокруг слышны другие звуки. Внимание сопровождает восприятие, память, мышление и другие процессы. Удержание внимания зависит от интереса, сложности задания и самочувствия. Если материал слишком трудный или однообразный, сосредоточиться на нем обычно бывает сложнее"],"t":18},{"n":3,"q":"Что такое ощущение","a":["Ощущение является отражением отдельного свойства предмета или состояния организма при воздействии на рецепторы. Оно позволяет почувствовать цвет, звук, запах, вкус, прикосновение или положение тела. Выделяют ощущения от внешнего мира, от внутренних органов и от мышц, суставов и вестибулярного аппарата. Целостный образ предмета формируется уже на уровне восприятия. Например, ощущение холода сообщает о температуре, а мышечное чувство помогает определить положение руки. Сигналы направляют действия и защищают организм"],"t":18},{"n":1,"q":"Оперативная память","a":["Оперативная память удерживает сведения, нужные для выполнения текущей задачи. Например, человек помнит промежуточные результаты, пока решает пример. После завершения действия часть этой информации больше не нужна. В современной психологии близкое понятие рабочей памяти также подчеркивает активную обработку временно удерживаемых сведений. Например, при чтении инструкции нужно удерживать шаги, пока знакомишься со следующими. Записи и разделение задачи на части уменьшают эту нагрузку"],"t":19},{"n":2,"q":"Что такое мышление","a":["Мышление помогает находить связи, понимать причины и решать задачи, которые нельзя решить только прямым наблюдением. Наглядно-действенное мышление опирается на действия с предметами, наглядно-образное использует образы, а словесно-логическое связано с понятиями и рассуждениями. Эти виды не исключают друг друга и могут работать вместе. Мышление развивается в обучении, практике и общении. Например, собирая конструктор, ребенок пробует детали действием, представляет постройку и объясняет план словами. В одной задаче участвуют разные способы мышления"],"t":19},{"n":3,"q":"Основная задача психологии","a":["Общая психология изучает психику и поведение человека. Она объясняет, как человек воспринимает мир, запоминает, думает, переживает и действует. Ее задачи состоят в описании психических явлений, изучении их причин и поиске способов помочь человеку учиться, общаться и справляться с трудностями. Например, изучая обучение, психолог выясняет, почему один способ объяснения помогает ученику, а другой вызывает трудности. Знания используют"],"t":19},{"n":1,"q":"Основные методы в психологии","a":["Наблюдение позволяет изучать поведение в обычных или специально созданных условиях. Эксперимент помогает проверить, как изменение одного условия влияет на другое. Также применяют беседу, анкеты, психологические тесты и анализ результатов деятельности. Для надежных выводов важно учитывать условия исследования, особенности участников и возможность других объяснений. Например, чтобы оценить пользу учебного приема, сравнивают результаты при разных условиях. Один случай не позволяет сделать вывод обо всех людях"],"t":20},{"n":2,"q":"Произвольное и непроизвольное внимание","a":["Непроизвольное внимание возникает без специального решения человека под влиянием яркого, нового или значимого события. Произвольное внимание человек направляет сознательно, исходя из поставленной цели. Например, неожиданный звонок привлекает непроизвольное внимание, а возвращение к учебнику требует произвольного. Умение управлять вниманием развивается постепенно. Чтобы удерживать произвольное внимание, полезно убрать помехи и обозначить ближайшую цель. Со временем знакомая работа может требовать меньше сознательного усилия"],"t":20},{"n":3,"q":"Понятие о воображении","a":["Воображение представляет собой создание образов того, что человек сейчас непосредственно не воспринимает. Оно опирается на прежний опыт, но может выходить за его привычные сочетания. Воображение помогает планировать, придумывать, понимать художественные произведения и представлять будущее. Его результаты могут быть реалистичными или фантастическими. Например, перед выступлением ученик представляет аудиторию и последовательность действий. Такой образ помогает подготовиться, хотя ситуация может отличаться от ожидаемой"],"t":20},{"n":1,"q":"Развитие процесса восприятия и наблюдательности у детей","a":["Сначала ребенок чаще замечает самые яркие признаки предмета, а затем учится рассматривать его последовательно. Наблюдательность развивается, когда взрослый предлагает сравнить предметы, найти изменения, описать детали и объяснить различия. Полезны прогулки с наблюдением, рисование с натуры и игры на поиск признаков. Важно учить ребенка проверять свои впечатления. Например, при наблюдении за растением можно рассмотреть листья, стебель и цвет. Такой план помогает замечать не только самые яркие признаки"],"t":21},{"n":2,"q":"Развитие памяти","a":["Развитие памяти связано с появлением осмысленного запоминания и специальных приемов. Помогают группировка материала, составление плана, связь нового с известным и повторение через промежутки времени. Полезно не только перечитывать, но и пробовать вспомнить ответ без подсказки. У детей запоминание постепенно становится более целенаправленным и связанным с речью. Например, новые слова можно объединить по темам и придумать с ними предложения. Для ребенка полезно связывать запоминание с понятной задачей"],"t":21},{"n":3,"q":"Позитивное мышление","a":["Позитивное мышление означает привычку замечать возможности и искать конструктивный выход из трудностей. Оно не требует отрицать проблемы или запрещать себе неприятные эмоции. Например, неудачу можно рассматривать как повод изменить способ подготовки. Полезное позитивное мышление опирается на факты, реалистичные ожидания и конкретные действия. Например, вместо мысли о неспособности к учебе человек замечает пробел. После этого он выбирает упражнение и проверяет результат подготовки"],"t":21},{"n":1,"q":"Развитие мышления","a":["Мышление развивается в действиях с предметами, общении и обучении. Ребенок постепенно учится сравнивать, выделять признаки, понимать причины и пользоваться понятиями. Развитию помогают задачи с объяснением решения, вопросы о причинах, обсуждение разных вариантов и практические опыты. Важно давать задания посильной сложности и поддерживать самостоятельное рассуждение. Например, после решения задачи полезно попросить ребенка объяснить свой выбор и найти способ. Так он учится замечать ход собственного рассуждения"],"t":22},{"n":2,"q":"Психологическая характеристика мышления. Виды мышления","a":["Мышление помогает находить связи, понимать причины и решать задачи, которые нельзя решить только прямым наблюдением. Наглядно-действенное мышление опирается на действия с предметами, наглядно-образное использует образы, а словесно-логическое связано с понятиями и рассуждениями. Эти виды не исключают друг друга и могут работать вместе. Мышление развивается в обучении, практике и общении. Например, собирая конструктор, ребенок пробует детали действием, представляет постройку и объясняет план словами. В одной задаче участвуют разные способы мышления"],"t":22},{"n":3,"q":"Коммуникативная сторона общения","a":["Коммуникативная сторона общения означает обмен информацией. Для него нужны понятные слова, общий смысл сообщения и обратная связь. Недопонимание возникает из-за шума, разных значений слов, невнимания или сильных эмоций. Помогают уточняющие вопросы, спокойная речь и умение слушать. Обратная связь показывает, как собеседник понял сообщение. Например, пересказ задания своими словами помогает обнаружить и исправить недопонимание до начала работы"],"t":22},{"n":1,"q":"Основные направления психологии в 20 веке","a":["Бихевиоризм изучал поведение и обучение через связь ситуации с реакцией. Психоанализ обращал внимание на бессознательные переживания и внутренние конфликты. Гештальтпсихология рассматривала восприятие как целостный процесс. Гуманистическая психология изучала личностный рост, когнитивная психология исследовала обработку информации, а деятельностный подход связывал развитие психики с деятельностью и общением. Разные направления рассматривают один вопрос с разных сторон. Например, обучение можно объяснять через подкрепление поведения, работу памяти или деятельность ребенка со взрослым"],"t":23},{"n":2,"q":"Виды мотивов. Осознанные и неосознаваемые мотивы. Локус контроля личности","a":["Мотивы бывают внутренними, когда человеку интересна сама деятельность, и внешними, когда он стремится к награде или избегает наказания. Осознанные мотивы человек может объяснить, а неосознаваемые влияют на него без ясного понимания причин. Локус контроля показывает, с чем человек связывает результаты: с собственными действиями или преимущественно с внешними обстоятельствами. Реальные события обычно зависят и от человека, и от условий. Например, после неудачи человек может изменить способ подготовки или объяснить все случайностью. Полезно замечать обстоятельства, на которые можно повлиять своими действиями"],"t":23},{"n":3,"q":"Основные свойства внимания и ее виды","a":["Основные свойства внимания включают концентрацию, устойчивость, объем, распределение и переключение. Концентрация показывает глубину сосредоточения, устойчивость означает его сохранение во времени, а объем отражает количество одновременно охватываемых объектов. Распределение помогает следить за несколькими действиями, переключение позволяет переходить от одного к другому. По участию воли различают непроизвольное, произвольное и послепроизвольное внимание. Например, устойчивость нужна для чтения, а переключение помогает перейти от чтения к решению задачи. Эти свойства могут развиваться неравномерно"],"t":23},{"n":1,"q":"Сенсорное развитие детей","a":["Сенсорное развитие означает развитие ощущений и восприятия. Ребенок учится различать цвет, форму, размер, звуки, запахи и свойства поверхности. Этому помогают игры с безопасными предметами, сортировка, рисование, музыка и движение. Взрослый называет свойства предметов и дает ребенку возможность сравнивать их в разных действиях. Например, можно предложить подобрать одинаковые по форме фигуры или найти мягкий предмет среди твердых. Такие задания связывают ощущения с действиями"],"t":24},{"n":2,"q":"Понятие о воображении","a":["Воображение представляет собой создание образов того, что человек сейчас непосредственно не воспринимает. Оно опирается на прежний опыт, но может выходить за его привычные сочетания. Воображение помогает планировать, придумывать, понимать художественные произведения и представлять будущее. Его результаты могут быть реалистичными или фантастическими. Например, перед выступлением ученик представляет аудиторию и последовательность действий. Такой образ помогает подготовиться, хотя ситуация может отличаться от ожидаемой"],"t":24},{"n":3,"q":"Основная структура психики","a":["В психике выделяют процессы, состояния и свойства. Процессы включают ощущения, восприятие, память, мышление, эмоции и волевые действия. Состояния показывают, что человек переживает сейчас, например усталость или тревогу. Свойства являются относительно устойчивыми особенностями, к ним относятся темперамент, характер и способности. Например, запоминание стихотворения является процессом, усталость во время занятия является состоянием, а привычная настойчивость человека относится к относительно устойчивым свойствам"],"t":24},{"n":1,"q":"Операции мышления","a":["Анализ разделяет объект на части, а синтез объединяет части в целое. Сравнение позволяет найти сходства и различия, обобщение объединяет предметы по общему признаку. Абстрагирование выделяет важную сторону и временно отвлекается от остальных. Конкретизация помогает объяснить общее правило на отдельном примере. Например, сравнивая два растения, ребенок выделяет форму листьев и размер. Затем он объединяет похожие растения в группу по общему признаку"],"t":25},{"n":2,"q":"Развитие процесса восприятия и наблюдательности у детей","a":["Сначала ребенок чаще замечает самые яркие признаки предмета, а затем учится рассматривать его последовательно. Наблюдательность развивается, когда взрослый предлагает сравнить предметы, найти изменения, описать детали и объяснить различия. Полезны прогулки с наблюдением, рисование с натуры и игры на поиск признаков. Важно учить ребенка проверять свои впечатления. Например, при наблюдении за растением можно рассмотреть листья, стебель и цвет. Такой план помогает замечать не только самые яркие признаки"],"t":25},{"n":3,"q":"Понятие о памяти. Значение памяти в жизни и деятельности человека","a":["Память сохраняет знания, навыки, впечатления и личный опыт. Благодаря ей человек узнает близких, понимает речь, учится и продолжает начатую работу. Она помогает поддерживать чувство непрерывности собственной жизни и учитывать прошлые ошибки. Без памяти было бы невозможно устойчивое обучение и накопление опыта. Например, опыт помогает выбрать знакомый маршрут и выполнить работу. При этом воспоминания могут меняться, поэтому память не является точной записью прошлого"],"t":25},{"n":1,"q":"Методы исследования в психологии","a":["Наблюдение позволяет изучать поведение в обычных или специально созданных условиях. Эксперимент помогает проверить, как изменение одного условия влияет на другое. Также применяют беседу, анкеты, психологические тесты и анализ результатов деятельности. Для надежных выводов важно учитывать условия исследования, особенности участников и возможность других объяснений. Например, чтобы оценить пользу учебного приема, сравнивают результаты при разных условиях. Один случай не позволяет сделать вывод обо всех людях"],"t":26},{"n":2,"q":"История развития психологии","a":["Сначала представления о душе и поведении развивались внутри философии. Позже ученые стали связывать психические явления с работой мозга и органов чувств. В 1879 году Вильгельм Вундт открыл в Лейпциге лабораторию экспериментальной психологии, что обычно считают началом психологии как самостоятельной науки. В дальнейшем появились разные школы и практические направления. Переход к эксперименту позволил проверять предположения с помощью наблюдений и измерений. Сегодня исследования соединяют изучение поведения, опыта и работы мозга"],"t":26},{"n":3,"q":"Предмет психологии","a":["Общая психология изучает психику и поведение человека. Она объясняет, как человек воспринимает мир, запоминает, думает, переживает и действует. Ее задачи состоят в описании психических явлений, изучении их причин и поиске способов помочь человеку учиться, общаться и справляться с трудностями. Например, изучая обучение, психолог выясняет, почему один способ объяснения помогает ученику, а другой вызывает трудности. Знания используют"],"t":26},{"n":1,"q":"Что такое воображение","a":["Воображение представляет собой создание образов того, что человек сейчас непосредственно не воспринимает. Оно опирается на прежний опыт, но может выходить за его привычные сочетания. Воображение помогает планировать, придумывать, понимать художественные произведения и представлять будущее. Его результаты могут быть реалистичными или фантастическими. Например, перед выступлением ученик представляет аудиторию и последовательность действий. Такой образ помогает подготовиться, хотя ситуация может отличаться от ожидаемой"],"t":27},{"n":2,"q":"Что такое личность","a":["Личность представляет собой человека как участника общественной жизни со своими ценностями, мотивами, отношениями и способами поведения. Она формируется в общении, деятельности, воспитании и собственном выборе. Понятие личности отличается от понятия индивида, которое обозначает отдельного представителя человеческого вида. Индивидуальность отражает неповторимое сочетание особенностей конкретного человека. Например, отношение к обязанностям проявляется в поступках и выборе человека. При этом отдельная ошибка или случайная реакция не описывает всю личность"],"t":27},{"n":3,"q":"Уровни личности","a":["Единой общепринятой схемы уровней личности нет. В модели Константина Платонова выделяют направленность личности, опыт, особенности психических процессов и биологически обусловленные свойства. Направленность включает ценности и мотивы, опыт включает знания и навыки. Эта схема помогает рассматривать человека с разных сторон, но не делит его на независимые части. Например, интерес к профессии относится к направленности, освоенное умение к опыту, а особенности темперамента к биологической основе. В жизни эти стороны взаимодействуют"],"t":27},{"n":1,"q":"Виды мышления","a":["Мышление помогает находить связи, понимать причины и решать задачи, которые нельзя решить только прямым наблюдением. Наглядно-действенное мышление опирается на действия с предметами, наглядно-образное использует образы, а словесно-логическое связано с понятиями и рассуждениями. Эти виды не исключают друг друга и могут работать вместе. Мышление развивается в обучении, практике и общении. Например, собирая конструктор, ребенок пробует детали действием, представляет постройку и объясняет план словами. В одной задаче участвуют разные способы мышления"],"t":28},{"n":2,"q":"Развитие памяти у детей","a":["Развитие памяти связано с появлением осмысленного запоминания и специальных приемов. Помогают группировка материала, составление плана, связь нового с известным и повторение через промежутки времени. Полезно не только перечитывать, но и пробовать вспомнить ответ без подсказки. У детей запоминание постепенно становится более целенаправленным и связанным с речью. Например, новые слова можно объединить по темам и придумать с ними предложения. Для ребенка полезно связывать запоминание с понятной задачей"],"t":28},{"n":3,"q":"Восприятие это","a":["Восприятие позволяет получить целостный образ предмета или события. Например, мы узнаем яблоко по сочетанию формы, цвета, запаха и прежнего опыта. Оно связано с вниманием, памятью, речью и действиями человека. Поэтому один и тот же объект разные люди могут воспринимать немного по-разному. Восприятие зависит и от задачи наблюдения. Художник может замечать сочетания цветов, а покупатель прежде всего обращает внимание на состояние предмета"],"t":28},{"n":1,"q":"Психический процесс в психологии","a":["Психический процесс представляет собой изменяющуюся во времени работу психики, которая помогает человеку познавать мир и регулировать поведение. Примеры включают ощущение, восприятие, запоминание, мышление и переживание эмоций. Процессы связаны друг с другом, поэтому при решении одной задачи обычно участвуют сразу несколько. Их различают для удобства изучения. Например, при ответе на уроке ученик воспринимает вопрос, вспоминает материал, обдумывает формулировку и следит за волнением. Все эти процессы образуют работу"],"t":29},{"n":2,"q":"Этапы развития психологии","a":["Сначала представления о душе и поведении развивались внутри философии. Позже ученые стали связывать психические явления с работой мозга и органов чувств. В 1879 году Вильгельм Вундт открыл в Лейпциге лабораторию экспериментальной психологии, что обычно считают началом психологии как самостоятельной науки. В дальнейшем появились разные школы и практические направления. Переход к эксперименту позволил проверять предположения с помощью наблюдений и измерений. Сегодня исследования соединяют изучение поведения, опыта и работы мозга"],"t":29},{"n":3,"q":"Взаимосвязь психологии с другими науками","a":["Психология связана с биологией и нейронауками, которые изучают мозг и организм. Педагогика использует психологические знания в обучении, медицина применяет их для понимания здоровья и болезни. Социология помогает изучать влияние общества и групп, а философия рассматривает общие вопросы сознания и познания. Математика и статистика нужны для проверки результатов исследований. Например, исследование трудностей обучения требует учитывать развитие ребенка, условия преподавания и особенности внимания. Поэтому специалисты разных областей часто работают над общей задачей вместе"],"t":29},{"n":1,"q":"Психологи которые внесли свой вклад","a":["Вильгельм Вундт развивал экспериментальное изучение психики, а Уильям Джеймс исследовал сознание и его функции. Иван Павлов изучал условные рефлексы, Зигмунд Фрейд создал психоанализ. Жан Пиаже исследовал развитие мышления, Лев Выготский показал роль общения и культуры в развитии ребенка. Алексей Леонтьев развивал деятельностный подход, а Александр Лурия изучал связь психических функций с мозгом. Эти ученые предлагали разные объяснения и методы исследования. Их идеи важно рассматривать в историческом контексте, потому что психология продолжает проверять и уточнять представления"],"t":30},{"n":2,"q":"Позитивное мышление","a":["Позитивное мышление означает привычку замечать возможности и искать конструктивный выход из трудностей. Оно не требует отрицать проблемы или запрещать себе неприятные эмоции. Например, неудачу можно рассматривать как повод изменить способ подготовки. Полезное позитивное мышление опирается на факты, реалистичные ожидания и конкретные действия. Например, вместо мысли о неспособности к учебе человек замечает пробел. После этого он выбирает упражнение и проверяет результат подготовки"],"t":30},{"n":3,"q":"Сенсорное развитие детей","a":["Сенсорное развитие означает развитие ощущений и восприятия. Ребенок учится различать цвет, форму, размер, звуки, запахи и свойства поверхности. Этому помогают игры с безопасными предметами, сортировка, рисование, музыка и движение. Взрослый называет свойства предметов и дает ребенку возможность сравнивать их в разных действиях. Например, можно предложить подобрать одинаковые по форме фигуры или найти мягкий предмет среди твердых. Такие задания связывают ощущения с действиями"],"t":30},{"n":1,"q":"Иерархия потребностей личности «Пирамида Маслоу»","a":["Абрахам Маслоу описывал физиологические потребности, безопасность, принадлежность и любовь, уважение и самоактуализацию. Физиологические потребности связаны с едой, водой и сном, а самоактуализация означает развитие своих возможностей. Нижние потребности часто требуют первоочередного внимания, но порядок не является строгим законом для каждого человека. Несколько потребностей могут действовать одновременно. Например, человек может заниматься творчеством даже в трудных условиях. Поэтому схему используют для общего понимания мотивации, учитывая культуру, опыт и конкретную ситуацию"],"t":31},{"n":2,"q":"Этапы восприятия","a":["Для объяснения восприятия можно выделить обнаружение сигнала, различение его признаков, объединение признаков в образ и узнавание объекта. Затем человек соотносит образ со своим опытом и придает ему смысл. Например, сначала замечает силуэт, затем различает детали и узнает знакомого человека. В реальной работе мозга эти процессы частично происходят одновременно. На узнавание влияют освещение, расстояние, внимание и ожидания. Если информации мало, человек может сначала ошибиться, а затем уточнить образ по признакам"],"t":31},{"n":3,"q":"Онтогенез процесса восприятия","a":["Онтогенез восприятия означает его развитие в течение жизни человека. У младенца восприятие совершенствуется через движение, контакт со взрослыми и действия с предметами. Позже ребенок учится выделять существенные признаки, называть их и наблюдать по определенному плану. Развитие зависит от созревания нервной системы, опыта, обучения и доступности сенсорной информации. Например, дошкольник учится различать похожие формы, а школьник целенаправленно рассматривает схему. Новые способы наблюдения формируются и совершенствуются при поддержке взрослого"],"t":31},{"n":1,"q":"Основные функции ощущений","a":["Ощущения дают первичную информацию о внешнем мире и состоянии тела. Они помогают ориентироваться, замечать опасность, поддерживать равновесие и регулировать движения. Сигналы от внутренних органов участвуют в переживании голода, жажды и других потребностей. На основе ощущений формируются более сложные образы восприятия. Например, боль побуждает прекратить опасное действие, а чувство равновесия помогает сохранять позу. Без этих сигналов управление поведением было бы сложнее"],"t":32},{"n":2,"q":"Физиологический механизм ощущений","a":["Раздражитель действует на рецептор, который преобразует воздействие в нервный сигнал. По чувствительным нервным путям сигнал поступает в центральную нервную систему. Разные участки мозга обрабатывают его свойства и связывают их с опытом. Например, свет воспринимают клетки сетчатки, а зрительный образ формируется с участием зрительных путей и коры. При повреждении любого звена этого пути ощущение может нарушаться. Поэтому одинаковые жалобы иногда связаны с разными причинами и требуют изучения"],"t":32},{"n":3,"q":"Виды внимания","a":["Непроизвольное внимание возникает само, например при громком звуке или появлении нового предмета. Произвольное внимание требует цели и усилия, например при выполнении трудного задания. Послепроизвольное внимание появляется, когда человек сначала заставляет себя заниматься, а затем увлекается работой. В реальной деятельности эти виды часто переходят один в другой. Например, школьник выполняет упражнение по требованию учителя, а потом увлекается поиском решения. Тогда необходимость заставлять себя заниматься может уменьшаться"],"t":32},{"n":1,"q":"Виды воображения","a":["Воображение бывает произвольным, когда человек намеренно создает образ, и непроизвольным, когда образы возникают без специальной цели. Воссоздающее воображение помогает представить объект по описанию, а творческое создает новые образы. Активное воображение связано с задачами и действиями, пассивное может ограничиваться мечтами. Основные механизмы включают соединение, изменение, выделение и обобщение знакомых признаков. Например, представление города по описанию является воссоздающим воображением, а создание сказочного города является творческим. При этом оба варианта используют опыт"],"t":33},{"n":2,"q":"Что такое типизация в воображении","a":["Типизация представляет собой создание образа, в котором объединены характерные черты многих людей, предметов или событий. Писатель может собрать знакомые особенности разных учителей в одном литературном герое. Такой образ передает общие черты определенного типа, сохраняя индивидуальные детали. Типизация широко применяется в литературе, искусстве и игре. Например, герой может воплощать привычки заботливого наставника, оставаясь отдельным персонажем. Это позволяет через частный образ показать человеческие качества и отношения"],"t":33},{"n":3,"q":"Преднамеренное пассивное воображение","a":["Преднамеренное пассивное воображение возникает, когда человек сознательно создает приятные или желаемые образы, но не связывает их с действиями по достижению цели. Примером могут быть грезы об успехе без реального плана подготовки. Само по себе такое фантазирование может давать отдых. Если оно постоянно заменяет деятельность, выполнение важных задач затрудняется. Различие видно по продолжению фантазии: человек либо только переживает образ, либо составляет план и начинает действовать. Во втором случае воображение становится активным"],"t":33}],"sources":["OpenStax Psychology 2e разделы по общей психологии","OpenStax История психологии","OpenStax Современные направления психологии"]},{"id":"nerv","short":"НС","name":"Нервная система","title":"Ответы по нервной системе и слуховому анализатору","subtitle":"198 вопросов в порядке исходного списка","tickets":false,"items":[{"n":1,"q":"Основной структурной и функциональной единицей нервной системы является","a":["Верно: нейрон. Он принимает сигнал через дендриты, проводит его по аксону и передаёт следующей клетке. Аксон и синапс это части нейрона, а не самостоятельные единицы. Глия питает и защищает нервные клетки, но сигнал не проводит"]},{"n":2,"q":"Белое вещество головного мозга состоит в основном из","a":["Верно: нервных волокон. Это отростки нейронов, покрытые миелиновой оболочкой, и именно миелин даёт белый цвет. Тела нейронов лежат в сером веществе. Волокна связывают участки мозга между собой и с нижележащими отделами"]},{"n":3,"q":"Серое вещество головного мозга образует","a":["Верно: кору мозга. Серое вещество это скопления тел нейронов. В головном мозге они образуют кору больших полушарий и мозжечка, а также подкорковые ядра. Нервные узлы тоже состоят из тел нейронов, но лежат вне ЦНС"]},{"n":4,"q":"К отделам головного мозга не относится","a":["Верно: спинной. Головной мозг делят на продолговатый, задний с мостом и мозжечком, средний, промежуточный и конечный. Спинной мозг это отдельный орган ЦНС в позвоночном канале. Гипофиз тоже не отдел мозга, а железа, поэтому вопрос спорный, см. последний раздел"]},{"n":5,"q":"Продолговатый мозг регулирует","a":["Верно: дыхание и сердцебиение. Здесь лежат жизненно важные центры: дыхательный, сосудодвигательный, а также центры глотания, кашля, чихания и рвоты. Повреждение этого отдела несовместимо с жизнью. Память связана с корой, а координация с мозжечком"]},{"n":6,"q":"Центр равновесия и координации движений расположен в","a":["Верно: мозжечке. Мозжечок сверяет замысел движения с тем, как оно выполняется, и вносит поправки. Он же поддерживает мышечный тонус и равновесие. При его поражении появляются шаткая походка, промахивание мимо цели и дрожание"]},{"n":7,"q":"Конечный мозг состоит из","a":["Верно: двух полушарий. Это самый крупный отдел: два полушария, покрытые корой, с подкорковыми ядрами и белым веществом внутри. Полушария соединяет мозолистое тело. Гипоталамус и средний мозг лежат ниже и к конечному мозгу не относятся"]},{"n":8,"q":"За сознание и мышление отвечает","a":["Верно: кора больших полушарий. В коре находятся высшие центры: мышление, речь, память, осознанное восприятие и произвольные движения. Таламус только переключает сигналы к коре, а спинной мозг и мозжечок в сознании не участвуют"]},{"n":9,"q":"Гипофиз вырабатывает гормоны, регулирующие","a":["Верно: работу желез внутренней секреции. Гипофиз называют главной эндокринной железой: его тропные гормоны управляют щитовидной железой, надпочечниками и половыми железами. Сам он подчиняется гипоталамусу. Кроме тропных, он выделяет гормон роста и пролактин"]},{"n":10,"q":"Гипоталамус контролирует","a":["Верно: обмен веществ и температуру тела. Это высший центр вегетативной регуляции: температура, аппетит, жажда, обмен веществ, сон и бодрствование. Через гипофиз он управляет и эндокринной системой. Кровяное давление он меняет тоже, но через сосудодвигательный центр"]},{"n":11,"q":"Гиппокамп играет основную роль в","a":["Верно: памяти и обучении. Гиппокамп переводит новые сведения из кратковременной памяти в долговременную. Он входит в лимбическую систему, поэтому эмоционально окрашенные события запоминаются лучше. При двустороннем повреждении человек перестаёт запоминать новое, хотя прошлое помнит"]},{"n":12,"q":"Экстрапирамидальная система регулирует","a":["Верно: автоматические и непроизвольные движения. Она управляет позой, мышечным тонусом и заученными движениями, которые не требуют внимания: ходьбой, жестами, удержанием равновесия. Основа её это базальные ядра, красное ядро, чёрная субстанция и ретикулярная формация"]},{"n":13,"q":"Количество пар черепно-мозговых нервов","a":["Верно: 12. Нумерация идёт римскими цифрами сверху вниз, от обонятельного первого до подъязычного двенадцатого. Одни пары чисто чувствительные, другие чисто двигательные, третьи смешанные. Все, кроме первых двух, выходят из ствола мозга"]},{"n":14,"q":"Обонятельный нерв отвечает за","a":["Верно: обоняние. Это первая пара, чисто чувствительная. Волокна идут от рецепторов слизистой носа через решётчатую кость к обонятельной луковице. Корковый центр лежит в крючке и парагиппокампальной извилине височной доли"]},{"n":15,"q":"Зрительный нерв передает информацию от","a":["Верно: сетчатки глаза. Нерв образован аксонами ганглиозных клеток сетчатки. В области перекреста волокна от внутренних половин сетчатки переходят на другую сторону, поэтому каждое полушарие видит противоположную половину поля зрения. Мышцами глаза управляют III, IV и VI пары"]},{"n":16,"q":"Слуховой нерв также участвует в восприятии","a":["Верно: равновесия. Восьмая пара называется преддверно-улитковым нервом и состоит из двух частей. Улитковая часть несёт звук от кортиева органа, преддверная идёт от полукружных каналов и мешочков преддверия. Поэтому при болезнях внутреннего уха страдают и слух, и равновесие"]},{"n":17,"q":"Тройничный нерв обеспечивает","a":["Верно: чувствительность лица и жевание. Это смешанный нерв с тремя ветвями: глазной, верхнечелюстной и нижнечелюстной. Чувствительные волокна собирают информацию от кожи лица, слизистых, зубов и роговицы, двигательные идут к жевательным мышцам. При его поражении возникает сильнейшая лицевая боль"]},{"n":18,"q":"Лицевой нерв иннервирует","a":["Верно: мимику. Седьмая пара управляет всеми мимическими мышцами, а через промежуточный нерв отвечает ещё за вкус передних двух третей языка и работу слёзной и слюнных желёз. При повреждении половина лица становится неподвижной, глаз не закрывается, угол рта опускается"]},{"n":19,"q":"Блуждающий нерв регулирует","a":["Верно: работу сердца и внутренних органов. Десятая пара это основной парасимпатический нерв: он замедляет сердцебиение, сужает бронхи, усиливает работу желудка и кишечника. Назван блуждающим, потому что спускается из черепа в грудную и брюшную полость. Участвует он и в глотании, и в работе голосовых связок"]},{"n":20,"q":"Спинной мозг состоит из","a":["Верно: серого и белого вещества. Серое вещество лежит внутри и на разрезе похоже на бабочку, белое окружает его снаружи. В сером находятся тела нейронов и замыкаются рефлекторные дуги. Белое это проводящие пути к головному мозгу и обратно"]},{"n":21,"q":"Центры рефлексов находятся в","a":["Верно: спинном мозге. В нём замыкаются дуги простых безусловных рефлексов: коленного, сгибательного, мочеиспускания, дефекации. Головной мозг их контролирует, но для самого действия не обязателен. Поэтому при травме спинного мозга рефлексы ниже повреждения могут сохраняться"]},{"n":22,"q":"Проводящие пути спинного мозга делятся на","a":["Верно: нисходящие и восходящие. Восходящие несут чувствительность вверх, к головному мозгу, нисходящие передают команды вниз, к мышцам и железам. Они лежат в белом веществе отдельными пучками, каждый со своей задачей. По расположению их делят на передние, боковые и задние канатики"]},{"n":23,"q":"Восходящие пути передают импульсы","a":["Верно: от рецепторов к мозгу. Это чувствительные, или афферентные, пути. По ним идут боль, температура, прикосновение и сведения о положении тела. Обычно они трёхнейронные: первый нейрон в спинномозговом узле, второй в спинном или продолговатом мозге, третий в таламусе"]},{"n":24,"q":"Нисходящие пути передают импульсы","a":["Верно: от мозга к исполнительным органам. Это двигательные, или эфферентные, пути. Главный из них пирамидный, он несёт команды произвольных движений от коры к мотонейронам передних рогов. Экстрапирамидные пути регулируют тонус и автоматические движения"]},{"n":25,"q":"Центральная нервная система включает","a":["Верно: спинной и головной мозг. Оба лежат в костных вместилищах, головной в черепе и спинной в позвоночном канале, и покрыты тремя оболочками. Всё остальное, то есть нервы, корешки и узлы, относится к периферической нервной системе"]},{"n":26,"q":"Периферическая нервная система включает","a":["Верно: нервы и нервные узлы. Сюда входят 12 пар черепных и 31 пара спинномозговых нервов, их корешки, сплетения и ганглии. Задача этой части связывать ЦНС с органами и тканями. Её делят на соматическую и вегетативную"]},{"n":27,"q":"Белое вещество больших полушарий формирует","a":["Верно: проводящие пути. Волокна делят на три группы: ассоциативные соединяют участки одного полушария, комиссуральные связывают два полушария через мозолистое тело, проекционные идут к нижележащим отделам. Скопления тел нейронов внутри белого вещества образуют базальные ядра"]},{"n":28,"q":"Двигательная зона расположена в","a":["Верно: лобной доле. Это предцентральная извилина, в её пятом слое лежат гигантские пирамидные клетки Беца. Тело спроецировано на извилину перевёрнуто: ноги вверху, лицо внизу. Чем тоньше движения, тем больше участок коры, поэтому кисть и язык занимают много места"]},{"n":29,"q":"Центр речи находится в","a":["Верно: лобной доле. Речь обеспечивают два центра. Двигательный центр Брока лежит в нижней лобной извилине и отвечает за произнесение слов, а центр понимания речи Вернике находится в височной доле. У большинства людей оба лежат в левом полушарии"]},{"n":30,"q":"Центр зрения находится в","a":["Верно: затылочной доле. Зрительная кора лежит по краям шпорной борозды, в области клина и язычной извилины. Сюда приходят волокна от латерального коленчатого тела. При повреждении этой зоны глаз остаётся целым, но человек перестаёт видеть"]},{"n":31,"q":"Центр слуха","a":["Верно: височной доле. Слуховая кора занимает средний отдел верхней височной извилины, это извилины Гешля. Каждое ухо связано с обоими полушариями, поэтому одностороннее повреждение коры к глухоте не приводит. Рядом лежит центр Вернике, который превращает звуки в понятную речь"]},{"n":32,"q":"Рефлекс это","a":["Верно: ответ организма на раздражение. Реакция идёт по рефлекторной дуге: рецептор, чувствительный нейрон, центр в ЦНС, двигательный нейрон, рабочий орган. Рефлекс возникает без участия воли и является основной формой работы нервной системы"]},{"n":33,"q":"Безусловные рефлексы","a":["Верно: врождённые. Они передаются по наследству, одинаковы у всех представителей вида и не требуют обучения: сосательный, мигательный, глотательный, оборонительный. Их центры лежат в спинном мозге и стволе. Условные рефлексы приобретаются в течение жизни и могут угасать"]},{"n":34,"q":"Условные рефлексы формируются в","a":["Верно: коре больших полушарий. Они вырабатываются при совпадении безразличного раздражителя с безусловным, как в опытах Павлова со звонком и кормлением. Без коры такой рефлекс не образуется, поэтому он индивидуален. Если подкрепление исчезает, рефлекс угасает"]},{"n":35,"q":"Симпатическая система","a":["Верно: учащает сердцебиение. Симпатический отдел готовит организм к нагрузке и стрессу: учащает пульс и дыхание, повышает давление, расширяет зрачки и бронхи. При этом пищеварение тормозится, потому что в момент опасности оно не нужно"]},{"n":36,"q":"Парасимпатическая система","a":["Верно: замедляет обмен веществ. Этот отдел работает в покое, на восстановление: замедляет пульс, сужает зрачки и бронхи, усиливает пищеварение. Главный его проводник это блуждающий нерв. Два отдела вегетативной системы действуют на одни и те же органы противоположно"]},{"n":37,"q":"При повреждении пирамидного пути нарушаются","a":["Верно: произвольные движения. Пирамидный путь несёт команды от коры к мотонейронам спинного мозга и ядрам черепных нервов. При его поражении развивается центральный паралич: движения пропадают, а тонус мышц и рефлексы повышаются. Непроизвольные движения при этом сохраняются"]},{"n":38,"q":"Ретикулярная формация отвечает за","a":["Верно: бодрствование и сон. Это сеть нейронов в стволе мозга, которая поддерживает тонус коры и уровень бодрствования. Она же участвует в регуляции дыхания, кровообращения и мышечного тонуса. При её угнетении человек засыпает или теряет сознание"]},{"n":39,"q":"Нарушение кровообращения в мозге может вызвать","a":["Верно: инсульт. Он бывает ишемическим, когда сосуд закупорен тромбом, и геморрагическим, когда сосуд разрывается. Участок мозга без кровотока погибает за минуты, поэтому помощь нужна немедленно. Менингит и неврит это воспаления, а не сосудистые катастрофы"]},{"n":40,"q":"Воспаление оболочек мозга называется","a":["Верно: менингитом. Воспаляются мягкая и паутинная оболочки, нарастает внутричерепное давление. Отсюда главные признаки: резкая головная боль, рвота без облегчения, светобоязнь и ригидность затылочных мышц. Подтверждает диагноз люмбальная пункция"]},{"n":41,"q":"Воспаление вещества мозга это","a":["Верно: энцефалит. Страдает сама мозговая ткань, поэтому к общим симптомам добавляются очаговые: судороги, парезы, нарушения речи и сознания. Часто воспаление захватывает и оболочки, тогда говорят о менингоэнцефалите. Частая причина это вирусы, в том числе клещевого энцефалита"]},{"n":42,"q":"Повреждение спинного мозга приводит к","a":["Верно: параличу. Проводящие пути прерываются, и связь головного мозга с телом ниже места травмы теряется. Нарушаются и движения, и чувствительность, часто страдает работа тазовых органов. Чем выше уровень повреждения, тем больше объём нарушений"]},{"n":43,"q":"Эпилепсия связана с","a":["Верно: нарушением электрической активности мозга. Группа нейронов начинает разряжаться избыточно и синхронно, и разряд распространяется по коре. Если он охватывает весь мозг, приступ генерализованный с потерей сознания, если только часть, приступ очаговый. Такую активность видно на ЭЭГ"]},{"n":44,"q":"Основная функция нервной системы","a":["Верно: регуляция работы органов. Она согласует работу органов между собой и связывает организм с внешней средой, обеспечивая быстрый ответ на изменения. Гормональная регуляция решает ту же задачу, но медленнее. Транспорт веществ это дело крови, а защита иммунитета"]},{"n":45,"q":"Передача импульса осуществляется через","a":["Верно: синапс. Это контакт между двумя клетками, где сигнал передаётся химически. Импульс доходит до окончания аксона, из пузырьков выделяется медиатор, он действует на рецепторы следующей клетки. Миелин ускоряет проведение по волокну, но сам сигнал не передаёт"]},{"n":46,"q":"Средний мозг отвечает за","a":["Верно: ориентировочные рефлексы. В его крыше лежит четверохолмие: верхние холмики это подкорковый центр зрения, нижние слуха. Благодаря им человек поворачивает голову и глаза на внезапный свет или звук. Здесь же лежат красное ядро и чёрная субстанция, регулирующие мышечный тонус"]},{"n":47,"q":"Варолиев мост расположен между","a":["Верно: продолговатым мозгом и средним. Мост входит в задний мозг вместе с мозжечком и лежит на его передней поверхности. Через него проходят все пути между головным и спинным мозгом, а также волокна к мозжечку. Здесь находятся ядра с пятой по восьмую пары черепных нервов"]},{"n":48,"q":"Промежуточный мозг включает","a":["Верно: таламус и гипоталамус. Полный состав шире: таламус, гипоталамус, эпиталамус с эпифизом и метаталамус с коленчатыми телами. Таламус это коллектор, через который к коре идут почти все виды чувствительности, кроме обоняния. Гипоталамус управляет вегетативными функциями и гипофизом"]},{"n":49,"q":"Гипоталамус регулирует","a":["Верно: температуру тела, аппетит, обмен веществ. Сюда же относятся жажда, сон и бодрствование, половое поведение и эмоции. Гипоталамус сам вырабатывает гормоны, управляющие гипофизом, поэтому он связывает нервную и эндокринную системы. Координация и дыхание к нему отношения не имеют"]},{"n":50,"q":"Гипофиз выполняет функцию","a":["Верно: железы внутренней секреции. Он лежит в турецком седле и связан с гипоталамусом ножкой. Передняя доля вырабатывает собственные гормоны, задняя хранит и выделяет гормоны гипоталамуса. Размером гипофиз меньше горошины, но управляет всей эндокринной системой"]},{"n":51,"q":"Гиппокамп играет роль в","a":["Верно: формировании памяти и эмоций. Гиппокамп вместе с миндалиной и поясной извилиной входит в лимбическую систему. Он закрепляет новые воспоминания и придаёт им эмоциональную окраску. Поэтому сильные переживания запоминаются надолго"]},{"n":52,"q":"Мозжечок отвечает за","a":["Верно: равновесие и координацию. Мозжечок делает движения точными и плавными, распределяет тонус между мышцами. Он получает сведения от мышц, вестибулярного аппарата и коры и сравнивает замысел с результатом. Речь и эмоции к его основным задачам не относятся"]},{"n":53,"q":"Экстрапирамидальная система обеспечивает","a":["Верно: автоматические движения. Это заученные действия, которые идут без участия внимания: ходьба, жесты, поза, содружественные движения рук при ходьбе. При поражении системы появляются либо лишние движения, либо скованность и дрожание, как при паркинсонизме"]},{"n":54,"q":"Речевой центр Брока расположен","a":["Верно: в лобной доле. Это задняя часть нижней лобной извилины, у большинства людей слева. Центр Брока управляет мышцами, которые складывают звуки в слова. При его поражении человек понимает речь, но говорит с трудом или не говорит вовсе"]},{"n":55,"q":"Центр понимания речи Вернике расположен","a":["Верно: в височной доле. Он занимает заднюю часть верхней височной извилины рядом со слуховой корой. При его поражении человек слышит речь и говорит бегло, но смысла не понимает и путает слова"]},{"n":56,"q":"Вторая пара, зрительный нерв","a":["Верно: передача зрительной информации. Нерв несёт сигнал от сетчатки к латеральному коленчатому телу и верхним холмикам. По строению это не настоящий нерв, а вырост мозга, поэтому он покрыт оболочками мозга"]},{"n":57,"q":"Третья пара, глазодвигательный нерв","a":["Верно: движение глаз. Он иннервирует большинство мышц глазного яблока, мышцу века и несёт парасимпатические волокна к зрачку. При его поражении появляются косоглазие, опущенное веко и расширенный зрачок"]},{"n":58,"q":"Пятая пара, тройничный нерв","a":["Верно: чувствительность лица. Три ветви собирают чувствительность от лба и глаза, от верхней челюсти и от нижней. Третья ветвь ещё и двигательная, она управляет жеванием. Обоняние, слух и зрение обеспечивают другие пары"]},{"n":59,"q":"Седьмая пара, лицевой нерв","a":["Верно: мимика. Нерв проходит через канал в височной кости рядом со средним ухом, поэтому при отитах он часто страдает. Кроме мимики он отвечает за вкус передних двух третей языка и работу слёзной железы"]},{"n":60,"q":"Восьмая пара, преддверно-улитковый нерв","a":["Верно: слух и равновесие. Улитковая часть начинается в спиральном узле улитки, преддверная в вестибулярном узле. Обе идут в ствол мозга одним стволом. Поэтому опухоль этого нерва даёт сразу и снижение слуха, и головокружение"]},{"n":61,"q":"Девятая пара, языкоглоточный нерв","a":["Верно: вкус и глотание. Он несёт вкусовую чувствительность задней трети языка, управляет мышцами глотки и даёт волокна к околоушной слюнной железе. Вместе с блуждающим нервом участвует в глотательном и рвотном рефлексах"]},{"n":62,"q":"Десятая пара, блуждающий нерв","a":["Верно: регуляция работы внутренних органов. Это самый длинный черепной нерв: он доходит до кишечника. Он замедляет сердце, усиливает пищеварение, участвует в речи и глотании через возвратный гортанный нерв"]},{"n":63,"q":"Гипофиз расположен","a":["Верно: в турецком седле. Это углубление клиновидной кости на основании черепа. Рядом проходит зрительный перекрест, поэтому опухоль гипофиза часто сужает поля зрения. С гипоталамусом он соединён тонкой ножкой"]},{"n":64,"q":"Гипофиз состоит из","a":["Верно: передней, средней и задней долей. Передняя доля, аденогипофиз, сама вырабатывает гормоны. Задняя, нейрогипофиз, только накапливает и выделяет окситоцин и вазопрессин, которые образуются в гипоталамусе"]},{"n":65,"q":"Передняя доля гипофиза выделяет гормоны","a":["Верно: роста, тиреотропный, гонадотропные. Сюда же входят адренокортикотропный гормон и пролактин. Адреналин вырабатывают надпочечники, инсулин поджелудочная железа, мелатонин эпифиз"]},{"n":66,"q":"Нарушение функции гипофиза вызывает","a":["Верно: гигантизм или карликовость. Избыток гормона роста в детстве даёт гигантизм, недостаток карликовость. Если избыток появляется уже у взрослого, развивается акромегалия: растут кисти, стопы и черты лица"]},{"n":67,"q":"Гиппокамп отвечает за","a":["Верно: формирование кратковременной памяти. Гиппокамп удерживает свежие сведения и постепенно переводит их в долговременное хранилище коры. Сами воспоминания хранятся не в нём, а в коре, поэтому старые события при его повреждении сохраняются"]},{"n":68,"q":"При повреждении гиппокампа у человека наблюдается","a":["Верно: амнезия. При двустороннем повреждении новые воспоминания перестают закрепляться, хотя старые остаются. Человек помнит детство, но не помнит, что было несколько минут назад. Речь, зрение и движения при этом сохранны"]},{"n":69,"q":"Повреждение базальных ядер вызывает","a":["Верно: гиперкинезы, то есть непроизвольные движения. Базальные ядра сдерживают лишние движения и распределяют тонус. При одних поражениях появляются лишние движения, при других, например при паркинсонизме, наоборот, скованность и тремор"]},{"n":70,"q":"Спинно-таламический путь проводит импульсы","a":["Верно: боли и температуры. Это касается латерального пучка, передний несёт прикосновение и давление. Второй нейрон пути переходит на противоположную сторону в спинном мозге, поэтому боль слева осознаётся правым полушарием"]},{"n":71,"q":"Спинно-мозжечковый путь передаёт информацию","a":["Верно: о положении тела в пространстве. Это проприоцепция: сигналы от мышц, сухожилий и суставов о степени их напряжения. Информация идёт в мозжечок и не доходит до сознания, поэтому мы удерживаем равновесие, не думая об этом"]},{"n":72,"q":"Двигательная зона коры расположена","a":["Верно: в лобной доле. Предцентральная извилина отделена от чувствительной зоны центральной бороздой. Каждое полушарие управляет противоположной половиной тела, потому что пирамидный путь перекрещивается"]},{"n":73,"q":"Соматосенсорная зона","a":["Верно: теменная доля. Чувствительность кожи, мышц и суставов проецируется в постцентральную извилину. Как и в двигательной зоне, тело представлено перевёрнуто и неравномерно: губы и кисти занимают больше всего места"]},{"n":74,"q":"Повреждение афферентного пути вызывает","a":["Верно: потерю чувствительности. Афферентный значит приносящий, такой путь идёт от рецептора к мозгу. Если он прерван, участок тела перестаёт чувствовать, хотя мышцы могут работать. Исчезают и рефлексы, у которых этот путь был началом дуги"]},{"n":75,"q":"Повреждение эфферентного пути вызывает","a":["Верно: паралич. Эфферентный значит выносящий, по нему команда идёт от мозга к мышце. При повреждении на уровне коры или пути паралич центральный, с повышенным тонусом, при повреждении мотонейрона периферический, с вялостью и атрофией"]},{"n":76,"q":"При поражении спинного мозга выше поясничного отдела развивается","a":["Верно: паралич нижних конечностей. Пути к ногам прерываются, возникает нижняя параплегия. Часто страдают и тазовые органы. Если поражение выше, в шейном отделе, отказывают и руки, а при высоком повреждении нарушается дыхание"]},{"n":77,"q":"При поражении проводящих путей мозжечка наблюдается","a":["Верно: шаткая походка. Это атаксия: человек ходит широко расставляя ноги, качается и промахивается мимо цели. Добавляются дрожание при движении, невнятная речь и низкий мышечный тонус"]},{"n":78,"q":"К слуховому анализатору относятся","a":["Верно: слуховой рецептор, слуховой нерв и зона коры. Любой анализатор по Павлову состоит из трёх частей: периферической, проводниковой и центральной. Евстахиева труба и хрусталик в эту схему не входят"]},{"n":79,"q":"Наружное ухо состоит","a":["Верно: из ушной раковины, слухового прохода и барабанной перепонки. Раковина собирает звук, проход проводит его к перепонке. В части учебников перепонку считают границей со средним ухом и в наружное не включают, поэтому вопрос спорный"]},{"n":80,"q":"Барабанная перепонка выполняет функцию","a":["Верно: преобразует воздушные звуковые волны в механические колебания. Перепонка колеблется в такт звуку и передаёт колебания на молоточек. Усиливают звук уже косточки, а не она сама"]},{"n":81,"q":"Накопление ушной серы в наружном слуховом проходе может привести","a":["Верно: к ухудшению слуха. Серная пробка перекрывает проход, и звук не доходит до перепонки. Слух возвращается сразу после промывания уха у врача. Вариант «тугоухость» по смыслу тот же, поэтому вопрос стоит уточнить"]},{"n":82,"q":"С чем сообщается полость среднего уха","a":["Верно: с полостью глотки, через слуховую трубу. Благодаря этому давление с двух сторон перепонки выравнивается, но по этому же пути в ухо попадает инфекция при насморке. В исходном файле этот вариант слился со строкой вопроса и в списке ответов его нет"]},{"n":83,"q":"Со слуховым анализатором у человека связано","a":["Верно: речь. Ребёнок учится говорить, подражая услышанному и постоянно сверяя свою речь со слухом. Поэтому при ранней глухоте речь не развивается, хотя речевой аппарат цел"]},{"n":84,"q":"Слуховые рецепторы находятся в","a":["Верно: улитке. Точнее, в кортиевом органе на основной мембране улитки. Волосковые клетки превращают колебания жидкости в нервный импульс. В полукружных каналах лежат рецепторы равновесия, а не слуха"]},{"n":85,"q":"Слуховые косточки","a":["Верно: усиливают колебания барабанной перепонки и передают их во внутреннее ухо. Молоточек, наковальня и стремечко работают как система рычагов. Площадь перепонки гораздо больше площади окна преддверия, за счёт этого давление звука растёт"]},{"n":86,"q":"Вестибулярный аппарат образован","a":["Верно: двумя мешочками и тремя полукружными каналами. Мешочки преддверия чувствуют положение головы и прямолинейное ускорение. Каналы лежат в трёх взаимно перпендикулярных плоскостях и ловят повороты"]},{"n":87,"q":"Внутреннее ухо отделено от среднего","a":["Верно: пластинкой с двумя отверстиями. Это окно преддверия, куда упирается стремечко, и окно улитки, затянутое мембраной. Через первое колебания входят в жидкость улитки, второе гасит их"]},{"n":88,"q":"Лишившись в раннем детстве слуха, люди утрачивают способность","a":["Верно: произносить слова. Без слухового образца речь не формируется, развивается глухонемота. Именно поэтому важно выявить тугоухость как можно раньше и поставить слуховой аппарат или имплант"]},{"n":89,"q":"Ушная сера необходима для","a":["Верно: задержки пыли и направления звуков в слуховой проход. Сера задерживает пыль и микробы, увлажняет кожу и создаёт кислую среду, неудобную для бактерий. Выводится она наружу сама, поэтому чистить проход палочками не нужно"]},{"n":90,"q":"Система слуховых косточек состоит из","a":["Верно: молоточка, наковальни и стремечка. Цепочка соединяет барабанную перепонку с окном преддверия. Это самые маленькие кости человеческого тела, стремечко весит около трёх миллиграммов"]},{"n":91,"q":"Слуховые косточки, во сколько раз меняют колебания","a":["Верного варианта в списке нет. Система косточек усиливает давление звука примерно в 20 раз, амплитуда при этом даже уменьшается. В списке есть вариант «уменьшают в 20 раз», похоже на опечатку в слове «усиливают», это надо уточнить"]},{"n":92,"q":"Если постоянно слушать громкую музыку через наушники, это может привести","a":["Верно: к тугоухости. Громкий звук губит волосковые клетки улитки, а они не восстанавливаются. Тугоухость при этом нейросенсорная и нарастает незаметно, начиная с высоких частот"]},{"n":93,"q":"Внутреннее ухо состоит","a":["Верно: из преддверия, полукружных каналов и улитки. Всё это лежит в пирамиде височной кости и называется лабиринтом. Улитка отвечает за слух, преддверие и каналы за равновесие"]},{"n":94,"q":"Внутренняя слуховая труба","a":["Верно: выравнивает давление. Слуховая, она же евстахиева, труба соединяет барабанную полость с носоглоткой. Она открывается при глотании и зевоте, поэтому уши «закладывает» в самолёте и отпускает после глотка"]},{"n":95,"q":"Симптомы экссудативного среднего отита","a":["Верно: «заложенность» уха. В барабанной полости скапливается жидкость без гноя и без прободения перепонки. Отсюда заложенность, снижение слуха и ощущение переливания жидкости, так что верны два варианта из списка. Боли обычно нет, этим он отличается от гнойного"]},{"n":96,"q":"Симптомы острого ограниченного наружного отита","a":["Верно: боль в ухе. Ограниченный наружный отит это фурункул слухового прохода. Боль резкая, усиливается при надавливании на козелок и жевании. Гиперемия перепонки и заушная припухлость бывают при среднем отите и мастоидите"]},{"n":97,"q":"Звуковоспринимающий отдел включает","a":["Верно: рецепторный аппарат улитки. Звукопроводящий отдел это наружное и среднее ухо с лестницами улитки, звуковоспринимающий начинается с волосковых клеток. Это деление важно для диагноза: при поражении первого тугоухость кондуктивная, второго нейросенсорная"]},{"n":98,"q":"Для адгезивного среднего отита характерно","a":["Верно: кондуктивная тугоухость. После перенесённых воспалений в барабанной полости остаются рубцы и спайки, которые мешают перепонке и косточкам двигаться. Вариант про воспалительные процессы в анамнезе тоже верен, а опыт Вебера при кондуктивной тугоухости даёт звук в хуже слышащее ухо"]},{"n":99,"q":"Не является причиной усиления боли в ухе при фурункуле наружного уха","a":["Верно: повороты головы. Боль усиливается от всего, что двигает стенки слухового прохода или давит на них: жевания, зевания, надавливания на козелок, введения воронки. Поворот головы проход не затрагивает"]},{"n":100,"q":"Слух ухудшается при больших дефектах барабанной перепонки вследствие","a":["Верно: нарушаются и трансформационный механизм, и экранирующая роль перепонки. Без целой перепонки звук хуже передаётся на косточки. Кроме того, звук одновременно попадает на оба окна улитки и их колебания гасят друг друга"]},{"n":101,"q":"Для отосклероза характерно","a":["Верно: прогрессирующее двустороннее снижение слуха. При отосклерозе разрастается костная ткань вокруг стремечка и оно перестаёт двигаться. Болеет чаще всего молодые женщины, болезнь часто встречается у родственников и усиливается при беременности"]},{"n":102,"q":"При эпитимпаните показано лечение","a":["Верно: санирующая операция. Эпитимпанит разрушает кость и часто сопровождается холестеатомой. Это грозит парезом лицевого нерва, менингитом и абсцессом мозга, поэтому каплями здесь не обойтись"]},{"n":103,"q":"Кохлеарная имплантация показана детям при","a":["Верно: глухонемоте. Имплантат ставят при двусторонней глухоте, когда слуховые аппараты не помогают. Чем раньше операция, тем лучше разовьётся речь, потому что речевые зоны коры созревают в первые годы жизни"]},{"n":104,"q":"Для экссудативного среднего отита характерно","a":["Верно: снижение слуха. Жидкость в барабанной полости мешает перепонке двигаться. Гноетечения нет, потому что перепонка цела. Меняется также цвет перепонки, она становится желтоватой или синюшной, так что этот вариант тоже верен"]},{"n":105,"q":"Густое, желтовато-зелёное гнойное отделяемое с гнилостным запахом","a":["Верно: для эпитимпанита. Запах даёт распад костной ткани, то есть кариес. При мезотимпаните кость не разрушается и выделения без запаха, слизисто-гнойные. Поэтому запах это тревожный признак"]},{"n":106,"q":"Общие признаки хронических гнойных отитов","a":["Верно: наличие стойкой перфорации барабанной перепонки. Это часть классической триады: стойкая перфорация, периодическое гноетечение и снижение слуха. В списке верны три варианта из четырёх, лишний только про нарушение равновесия"]},{"n":107,"q":"Симптомы отосклероза","a":["Верно: симптом паракузис Виллизия. Это кажущееся улучшение слуха в шумном месте: в шуме собеседники говорят громче, и больной слышит лучше. Снижение слуха с низкочастотным шумом тоже характерно, так что верны два варианта"]},{"n":108,"q":"С каким заболеванием дифференцируют фурункул слухового прохода","a":["Верно: с мастоидитом. И там, и там есть припухлость и боль за ухом. Различают по слуху и отоскопии: при фурункуле слух почти не страдает и больно при надавливании на козелок, при мастоидите слух снижен и есть гноетечение"]},{"n":109,"q":"Наиболее частым возбудителем острого среднего отита является","a":["Верно: пневмококк. За ним идут гемофильная палочка и моракселла. Микроб попадает в ухо из носоглотки по слуховой трубе, обычно на фоне насморка. У детей труба короче и шире, поэтому отиты у них чаще"]},{"n":110,"q":"Что является признаком хронического среднего отита","a":["Верно: наличие стойкой перфорации барабанной перепонки. При остром отите перфорация зарастает за несколько недель, при хроническом остаётся навсегда. Гноетечение и кондуктивная тугоухость входят в ту же триаду и тоже верны"]},{"n":111,"q":"Осложнением какого заболевания чаще всего является острый средний отит","a":["Верно: ОРВИ. При насморке отекает устье слуховой трубы, вентиляция уха нарушается и инфекция поднимается в барабанную полость. Поэтому при простуде важно следить за носом и не сморкаться слишком резко"]},{"n":112,"q":"Односторонняя тугоухость, остро возникшая во время приема душа","a":["Верно: следствие серной пробки. Вода попала в ухо, пробка разбухла и полностью перекрыла проход. Характерно, что слух пропал мгновенно, на одно ухо и без боли. После промывания слух восстанавливается сразу"]},{"n":113,"q":"Симптом острой нейросенсорной тугоухости","a":["Верно: субъективный ушной шум. Шум слышит только сам больной, он появляется одним из первых. Нарушение разборчивости речи тоже верно. Это неотложное состояние: лечение нужно начать в первые дни, иначе слух не вернётся"]},{"n":114,"q":"Для экссудативного отита характерно","a":["Верно: ощущение переливания жидкости в ухе. Больной замечает его при наклонах и поворотах головы, иногда слух при этом ненадолго улучшается. При отоскопии виден уровень жидкости или пузырьки за перепонкой"]},{"n":115,"q":"Кохлеарная имплантация показана при","a":["Верно: полном выпадении слуховой функции. Имплантат заменяет погибшие волосковые клетки и раздражает слуховой нерв напрямую. При лёгкой и средней тугоухости хватает слухового аппарата, а при кондуктивной помогает операция на косточках"]},{"n":116,"q":"Для отогенного пареза лицевого нерва характерно","a":["Верно: парез всех мимических мышц. Нерв страдает в канале височной кости, то есть по периферическому типу. Поэтому страдает и лоб: человек не может нахмуриться и закрыть глаз. При центральном парезе, например после инсульта, лоб остаётся подвижным"]},{"n":117,"q":"Слухулучшающие операции проводятся при","a":["Верно: кондуктивной тугоухости. Хирург восстанавливает перепонку или подвижность косточек, то есть путь звука. При нейросенсорной тугоухости повреждён рецептор, и восстанавливать проведение бессмысленно"]},{"n":118,"q":"Нерв, иннервирующий мышцу, поднимающую верхнее веко","a":["Верно: глазодвигательный нерв и волокна симпатического ствола. Основную мышцу поднимает третья пара, а маленькая верхняя тарзальная мышца работает от симпатических волокон. Поэтому веко опускается и при параличе третьей пары, и при синдроме Горнера"]},{"n":119,"q":"Чувствительная иннервация роговицы осуществляется","a":["Верно: глазным нервом, первой ветвью тройничного. Именно поэтому касание роговицы вызывает мигательный рефлекс: чувствительная часть дуги идёт по тройничному, двигательная по лицевому нерву"]},{"n":120,"q":"Какой нерв регулирует работу сердца, легких и органов пищеварения","a":["Верно: десятая пара, блуждающий нерв. Это главный проводник парасимпатической системы. При его раздражении пульс замедляется, именно поэтому сильный кашель или давление на глазные яблоки может уредить сердцебиение"]},{"n":121,"q":"Какой нерв иннервирует грудино-ключично-сосцевидную и трапециевидную мышцы","a":["Верно: одиннадцатая пара, добавочный нерв. Он чисто двигательный. При его повреждении человеку трудно повернуть голову в сторону и поднять плечо, лопатка отходит от спины"]},{"n":122,"q":"Какой нерв обеспечивает вкусовую чувствительность передних двух третей языка","a":["Верно: седьмая пара, лицевой нерв через промежуточный. Вкусовые волокна идут в составе барабанной струны. Заднюю треть языка обслуживает девятая пара, а обычную чувствительность языка тройничный нерв"]},{"n":123,"q":"Какой из нервов является чисто чувствительным","a":["Верно: первая пара, обонятельный нерв. Чисто чувствительных нервов три: первая, вторая и восьмая пары. Чисто двигательные это третья, четвёртая, шестая, одиннадцатая и двенадцатая, остальные смешанные"]},{"n":124,"q":"Какой нерв является чисто двигательным и иннервирует мышцы языка","a":["Верно: двенадцатая пара, подъязычный нерв. При его одностороннем поражении язык при высовывании отклоняется в больную сторону. Со временем половина языка атрофируется и нарушается речь"]},{"n":125,"q":"Какая пара иннервирует мышцы движения глазного яблока, кроме верхней косой и латеральной прямой","a":["Верно: третья пара, глазодвигательный нерв. Верхнюю косую мышцу иннервирует четвёртая пара, латеральную прямую шестая. Есть удобное правило для запоминания: верхняя косая четвёртая, наружная прямая шестая, всё остальное третья"]},{"n":126,"q":"Что изучает нейрогенетика","a":["Верно: влияние наследственности на развитие и работу нервной системы. Она ищет гены, связанные с эпилепсией, аутизмом, болезнями Паркинсона и Альцгеймера. Анатомия мозга и химия медиаторов это другие дисциплины"]},{"n":127,"q":"Что такое нейрогенез","a":["Верно: образование новых нейронов из стволовых клеток. Основной нейрогенез идёт внутриутробно. У взрослого новые нейроны образуются лишь в немногих зонах, прежде всего в гиппокампе, и это связано с обучением и памятью"]},{"n":128,"q":"В каком возрасте наблюдается наиболее активный нейрогенез","a":["Верно: в детстве, а самый активный внутриутробно. К моменту рождения у ребёнка уже есть почти все нейроны, дальше растут связи между ними. В исходном файле этот вариант слился со строкой вопроса и среди ответов его нет"]},{"n":129,"q":"Как называется процесс формирования синапсов между нейронами","a":["Верно: синаптогенез. Он идёт особенно бурно в первые годы жизни, потом лишние синапсы отсеиваются. Миелинизация это другой процесс, покрытие отростков оболочкой для скорости проведения"]},{"n":130,"q":"Что такое нейропластичность","a":["Верно: изменение структуры и функций нейронных сетей под влиянием опыта. Благодаря ей работает обучение и восстанавливаются функции после инсульта: соседние участки берут на себя задачи погибших. У детей пластичность выше, чем у взрослых"]},{"n":131,"q":"Как называется естественная гибель нейронов в процессе развития","a":["Верно: апоптоз. Это запрограммированная гибель: лишние клетки удаляются аккуратно и без воспаления. Некроз, наоборот, это гибель от повреждения, с разрушением оболочки и воспалением вокруг"]},{"n":132,"q":"Какой тип клеток обеспечивает питание и защиту нейронов","a":["Верно: глиальные клетки. Астроциты питают нейроны и участвуют в гематоэнцефалическом барьере, олигодендроциты образуют миелин, микроглия работает как иммунная защита. Глиальных клеток в мозге не меньше, чем нейронов"]},{"n":133,"q":"Какой нейромедиатор играет ключевую роль в передаче возбуждения в двигательных нейронах","a":["Верно: ацетилхолин. Именно он действует в нервно-мышечном синапсе и запускает сокращение мышцы. На этом основано действие кураре и ботулотоксина, которые блокируют эту передачу"]},{"n":134,"q":"Какой метод используют для исследования активности мозга в реальном времени","a":["Верно: ЭЭГ. Электроды на коже головы ловят суммарную активность коры с точностью до миллисекунд. МРТ показывает строение, а не работу в момент времени, поэтому для приступов и сна применяют именно ЭЭГ"]},{"n":135,"q":"Что понимается под нейроинфекцией","a":["Верно: инфекция нервной системы. Сюда относят менингит, энцефалит, миелит, полиомиелит, бешенство и столбняк. Возбудителями бывают бактерии, вирусы, грибы и паразиты, но путь один: проникновение через барьеры мозга"]},{"n":136,"q":"Какой тип микроорганизмов чаще всего вызывает менингит","a":["Верно: бактерии, прежде всего менингококк и пневмококк. В жизни вирусные менингиты встречаются чаще бактериальных, но их вызывают энтеровирусы, а не вирусы гриппа из списка. Бактериальный протекает тяжелее и требует антибиотиков"]},{"n":137,"q":"При какой форме менингита в спинномозговой жидкости обнаруживается гной","a":["Верно: при бактериальном. Ликвор становится мутным, в нём много нейтрофилов, высокий белок и низкая глюкоза. При вирусном менингите ликвор прозрачный с лимфоцитами, это и позволяет быстро различить формы"]},{"n":138,"q":"Какое исследование обязательно для подтверждения менингита","a":["Верно: люмбальная пункция. Иглу вводят между поясничными позвонками, где спинного мозга уже нет. По составу жидкости сразу видно, бактериальный менингит или вирусный, и какой нужен препарат"]},{"n":139,"q":"Каким образом чаще всего распространяются вирусные нейроинфекции","a":["Верно: воздушно-капельным, контактным путём и через укусы. Энтеровирусы передаются и через грязные руки, клещевой энцефалит через укус клеща, бешенство через укус животного. Поэтому варианты со словом только неверны"]},{"n":140,"q":"Какой симптом типичен для менингита","a":["Верно: напряжение шейных мышц. Это ригидность затылочных мышц: больной не может прижать подбородок к груди. Рядом проверяют симптомы Кернига и Брудзинского. У младенцев важный признак это выбухание родничка"]},{"n":141,"q":"Энцефалит это","a":["Верно: воспаление головного мозга. При менингите воспаляются оболочки, при энцефалите само вещество. Отсюда и разница в симптомах: при энцефалите на первый план выходят нарушения сознания и очаговые симптомы"]},{"n":142,"q":"Какой признак характерен для энцефалита","a":["Верно: судороги и потеря сознания. Добавляются парезы, нарушения речи, поведения и памяти, то есть признаки поражения конкретных участков мозга. Состояние тяжёлое и требует лечения в стационаре"]},{"n":143,"q":"Что может быть осложнением после нейроинфекции","a":["Верно: потеря слуха или зрения. После гнойного менингита стойкая тугоухость встречается особенно часто. К осложнениям относятся также эпилепсия, гидроцефалия и задержка развития у детей"]},{"n":144,"q":"Что происходит при воспалении оболочек мозга","a":["Верно: повышается давление в черепе. Воспалённые оболочки вырабатывают больше жидкости и хуже её всасывают. Отсюда распирающая головная боль и рвота без облегчения. В исходном файле этот вариант слился со строкой вопроса"]},{"n":145,"q":"Что делать нельзя при подозрении на менингит","a":["Верно: лечиться самостоятельно дома. Бактериальный менингит развивается за часы и без антибиотиков смертелен. Жаропонижающее дать можно, но это не лечение и не повод откладывать вызов скорой"]},{"n":146,"q":"Какие нейроны чаще всего вовлекаются в развитие судорожных приступов","a":["Верно: тормозные, ГАМКергические. Приступ возникает, когда торможение перестаёт сдерживать возбуждение. Именно поэтому противосудорожные препараты усиливают действие ГАМК. Ответ «возбуждающие» тоже можно обосновать, поэтому вопрос стоит уточнить"]},{"n":147,"q":"Что является клиническим проявлением эпилепсии","a":["Верно: судорожные приступы. Они бывают генерализованными с потерей сознания и очаговыми, когда дёргается только рука или половина лица. Есть и бессудорожные приступы, когда человек на несколько секунд замирает"]},{"n":148,"q":"Какой метод используется для диагностики эпилепсии","a":["Верно: ЭЭГ. Она показывает характерные разряды и помогает понять, из какого участка исходит приступ. МРТ делают отдельно, чтобы найти причину: опухоль, рубец или порок развития"]},{"n":149,"q":"Что показывает электроэнцефалограмма","a":["Верно: электрическую активность мозга. Запись состоит из волн разной частоты: альфа в покое с закрытыми глазами, бета при активности, дельта во сне. Активность мышц пишет ЭМГ, а сердца ЭКГ"]},{"n":150,"q":"Какая форма эпилепсии обычно начинается в детстве","a":["Верно: идиопатическая. У неё нет видимой причины в виде опухоли или травмы, в основе наследственная предрасположенность. Многие детские формы проходят с возрастом. Симптоматическая форма, наоборот, связана с повреждением мозга"]},{"n":151,"q":"Какие отделы центральной нервной системы соединяют между собой ассоциативные проводящие пути","a":["Верно: соседние извилины в пределах одной доли мозга. Ассоциативные волокна связывают участки коры внутри одного полушария: короткие соединяют соседние извилины, длинные разные доли. Межполушарных связей они не дают, это работа комиссуральных волокон"]},{"n":152,"q":"Какие отделы центральной нервной системы соединяют между собой комиссуральные проводящие пути","a":["Верно: симметричные участки правой и левой половин мозга. Основная их масса идёт через мозолистое тело, часть через переднюю и заднюю спайки. Благодаря им полушария работают согласованно, а при рассечении мозолистого тела эта согласованность теряется"]},{"n":153,"q":"Какие отделы центральной нервной системы соединяют между собой проекционные проводящие пути","a":["Верно: обеспечивают двусторонние связи между нижележащими и вышележащими отделами. Восходящие проекционные пути несут чувствительность к коре, нисходящие команды от коры к стволу и мышцам. Во внутренней капсуле они собраны плотным пучком, поэтому небольшой очаг там даёт обширные выпадения"]},{"n":154,"q":"К экстероцептивным проводящим путям относятся","a":["Верно: латеральный спинно-таламический тракт. Экстероцептивные пути несут сигналы от кожи: боль, температуру и прикосновение. Корково-мосто-мозжечковый и покрышечно-спинномозговой это нисходящие пути, к чувствительности они не относятся"]},{"n":155,"q":"К проприоцептивным путям мозжечкового направления относятся","a":["Верно: пучок Флексига. Это задний спинно-мозжечковый путь, он несёт в мозжечок данные о положении тела и напряжении мышц. Пучок Говерса относится к той же группе, а пучки Голля и Бурдаха идут к коре"]},{"n":156,"q":"К проприоцептивным путям коркового направления относятся","a":["Верно: бульбо-таламический тракт. Он продолжает пучки Голля и Бурдаха от ядер продолговатого мозга через таламус к постцентральной извилине. Благодаря ему человек с закрытыми глазами знает положение своих рук и ног"]},{"n":157,"q":"Какие импульсы проводит латеральный спинно-таламический тракт","a":["Верно: температурной и болевой чувствительности. Путь перекрещивается почти на уровне своего сегмента, поэтому при половинном поражении спинного мозга боль и температура выпадают на противоположной стороне. Тактильную чувствительность несёт передний спинно-таламический тракт"]},{"n":158,"q":"Какие импульсы проводит передний спинно-таламический тракт","a":["Верно: тактильной чувствительности. Он проводит прикосновение и давление, то есть грубое осязание. Тонкое различение прикосновения идёт по пучкам Голля и Бурдаха, поэтому при повреждении одного пути осязание выпадает не полностью"]},{"n":159,"q":"Где расположен первый нейрон латерального спинно-таламического тракта","a":["Верно: в спинномозговых узлах. Первый нейрон любого чувствительного пути лежит в узле, то есть вне центральной нервной системы. Один его отросток идёт от рецептора кожи, другой входит в задний рог"]},{"n":160,"q":"Где расположен второй нейрон латерального спинно-таламического тракта","a":["Верно: в задних рогах спинного мозга. Это собственное ядро заднего рога, его аксон переходит на противоположную сторону. Переход идёт косо, на два-три сегмента выше, поэтому уровень выпадения чувствительности не совпадает точно с уровнем травмы"]},{"n":161,"q":"Где расположен третий нейрон латерального спинно-таламического тракта","a":["Верно: в таламусе. Это вентролатеральные ядра, общий пересадочный пункт почти для всей чувствительности. Отсюда отростки идут через внутреннюю капсулу к постцентральной извилине"]},{"n":162,"q":"Где расположен первый нейрон переднего спинно-таламического тракта","a":["Верно: в спинномозговых узлах. Схема та же, что у латерального пути: узел, задний рог, таламус. Это общее правило для чувствительных путей, поэтому такие вопросы решаются по шаблону"]},{"n":163,"q":"Где расположен второй нейрон переднего спинно-таламического тракта","a":["Верно: в задних рогах спинного мозга. Его аксон тоже переходит на противоположную сторону, но часть волокон остаётся на своей. Из-за этого тактильная чувствительность страдает меньше болевой"]},{"n":164,"q":"В каком отделе головного мозга заканчиваются экстероцептивные проводящие пути","a":["Верно: в постцентральной извилине противоположной стороны. Там лежит корковый центр общей чувствительности с проекцией тела вниз головой. Площадь проекции зависит не от размера части тела, а от её чувствительности, поэтому кисть и язык занимают больше всего места"]},{"n":165,"q":"Сколько нейронов включает проводящий путь зрительного анализатора","a":["Верно: 4. Это фоторецептор, биполярная клетка, ганглиозная клетка и нейрон подкоркового центра зрения. Первые три лежат прямо в сетчатке, то есть сетчатка это вынесенная наружу часть мозга"]},{"n":166,"q":"Где расположен 4-й нейрон проводящего пути зрительного анализатора","a":["Верно: в верхнем холмике среднего мозга. Это лучший из предложенных вариантов, хотя точнее тела четвёртых нейронов лежат в латеральном коленчатом теле, которого в списке нет. Медиальное коленчатое тело относится к слуху, поэтому его выбирать нельзя"]},{"n":167,"q":"В каком отделе головного мозга заканчивается проводящий путь зрительного анализатора","a":["Верно: в клину и язычной извилине. Это края шпорной борозды затылочной доли. При поражении этой зоны человек не слепнет на один глаз, а теряет часть поля зрения в обоих"]},{"n":168,"q":"Где находится первый нейрон проводящего пути слухового анализатора","a":["Верно: в спиральном узле улитки. Это биполярные клетки, их отростки подходят к волосковым клеткам кортиева органа. Сам кортиев орган содержит рецепторы, а не тела нейронов, поэтому этот вариант неверен"]},{"n":169,"q":"Укажите локализацию второго нейрона слухового проводящего пути","a":["Верно: переднее и заднее улитковые ядра моста. Оттуда часть волокон переходит на противоположную сторону и образует латеральную петлю. Из-за двустороннего проведения поражение выше ядер не даёт полной глухоты на одно ухо"]},{"n":170,"q":"Где расположен третий нейрон слухового проводящего пути","a":["Верно: в медиальном коленчатом теле. Вместе с нижними холмиками среднего мозга это подкорковый центр слуха. Нижние холмики отвечают за рефлекторный поворот головы и глаз на звук"]},{"n":171,"q":"В какой извилине расположен корковый центр слуха","a":["Верно: в среднем отделе верхней височной извилины. Это извилины Гешля, скрытые в глубине боковой борозды. Рядом, в задней части той же извилины, лежит центр Вернике, отвечающий за понимание речи"]},{"n":172,"q":"Укажите локализацию первого нейрона вестибулярного пути","a":["Верно: вестибулярный узел. Его называют узлом Скарпы, он лежит во внутреннем слуховом проходе. Отростки идут к рецепторам полукружных каналов, мешочка и маточки"]},{"n":173,"q":"Где находится второй нейрон проводящего пути вестибулярного анализатора","a":["Верно: ядро Дейтерса. Это самое крупное, латеральное, из четырёх вестибулярных ядер моста. От него начинается преддверно-спинномозговой путь, который держит тонус мышц при наклонах"]},{"n":174,"q":"Чем объясняются симптомы морской болезни при раздражении вестибулярного аппарата","a":["Верно: связями вестибулярных ядер с ядрами языкоглоточного и блуждающего нервов. Через них идут тошнота, рвота, слюнотечение и замедление пульса. Связи с ядрами глазодвигательных нервов тоже есть, но они дают нистагм, а не тошноту"]},{"n":175,"q":"Укажите локализацию первого нейрона проводящего пути вкусового анализатора","a":["Верно: узел коленца лицевого нерва. Он обслуживает передние две трети языка через барабанную струну. Для задней трети первые нейроны лежат в узлах языкоглоточного и блуждающего нервов"]},{"n":176,"q":"Где расположен второй нейрон проводящего пути вкусового анализатора","a":["Верно: ядро одиночного пути. Оно лежит в продолговатом мозге и общее для вкусовых волокон седьмой, девятой и десятой пар. Слюноотделительные ядра к вкусу не относятся, они дают секреторные волокна"]},{"n":177,"q":"Укажите локализацию коркового центра обоняния","a":["Верно: парагиппокампальная извилина и крючок гиппокампа. Обоняние единственное чувство, которое попадает в кору без переключения в таламусе. Это объясняет, почему запахи так быстро поднимают эмоции и воспоминания"]},{"n":178,"q":"Перечислите проприоцептивные тракты коркового направления","a":["Верно: бульбо-таламический тракт. Он продолжение пучков Голля и Бурдаха, идущее к постцентральной извилине. Пучки Говерса, Флексига и Монакова к коре не идут"]},{"n":179,"q":"Перечислите проприоцептивные пути мозжечкового направления","a":["Верно: пучок Говерса. Вместе с пучком Флексига он несёт данные о положении тела в мозжечок. Эти сигналы не доходят до сознания, они нужны для автоматической координации"]},{"n":180,"q":"Укажите локализацию первого нейрона всех проприоцептивных трактов","a":["Верно: спинномозговой узел. Правило общее для всей чувствительности: первый нейрон всегда вне центральной нервной системы. Различаются такие пути только местом второго и третьего нейронов"]},{"n":181,"q":"Где заканчиваются пучки Голля и Бурдаха","a":["Верно: в тонком и клиновидном ядрах продолговатого мозга. Там лежат вторые нейроны, их аксоны перекрещиваются и образуют медиальную петлю. Пучок Голля несёт сигналы от ног, пучок Бурдаха от рук"]},{"n":182,"q":"Что такое медиальная петля","a":["Верно: продолжение пучков Голля и Бурдаха. Это аксоны вторых нейронов после перекреста в продолговатом мозге, идущие к таламусу. По ходу к ней присоединяются волокна от головы, поэтому в таламус приходит чувствительность всего тела"]},{"n":183,"q":"Где заканчивается бульбо-таламический тракт","a":["Верно: в постцентральной извилине. Это общий корковый конец всей осознаваемой чувствительности. При его поражении человек не узнаёт предметы на ощупь и теряет чувство положения конечности"]},{"n":184,"q":"Какой из спинно-мозжечковых трактов является дважды перекрещенным","a":["Верно: передний спинно-мозжечковый тракт. Пучок Говерса перекрещивается в спинном мозге и второй раз в верхнем мозжечковом парусе. В итоге он приходит в мозжечок на свою же сторону, как и неперекрещенный пучок Флексига"]},{"n":185,"q":"Укажите локализацию второго нейрона заднего спинно-мозжечкового пути","a":["Верно: ядро Кларка. Грудное ядро Кларка лежит у основания заднего рога, с восьмого шейного по второй или третий поясничный сегмент. Его аксоны не перекрещиваются и входят в мозжечок через нижнюю ножку"]},{"n":186,"q":"Какую функцию выполняет пирамидная система","a":["Верно: осуществление произвольных движений. Это осознанные движения по команде коры, прежде всего тонкие движения кисти и речевых мышц. Непроизвольные движения и тонус обеспечивает экстрапирамидная система"]},{"n":187,"q":"Укажите локализацию первого нейрона пирамидных путей","a":["Верно: клетки Беца предцентральной извилины. Это гигантские пирамидные клетки пятого слоя коры. Проекция тела в этой извилине тоже перевёрнута: нога сверху, лицо снизу"]},{"n":188,"q":"Где расположен второй нейрон корково-ядерного тракта","a":["Верно: двигательные ядра глазодвигательного и блокового нервов. Вообще это двигательные ядра всех черепных нервов, а не только третьей и четвёртой пар. Большинство таких ядер получает волокна с двух сторон, поэтому односторонний очаг в коре редко даёт полный паралич"]},{"n":189,"q":"Укажите локализацию второго нейрона корково-спинномозговых проводящих путей","a":["Верно: мотонейроны передних рогов спинного мозга. Их называют конечным общим путём: к ним приходят команды и от пирамидной, и от экстрапирамидной системы. Гибель самих мотонейронов даёт вялый паралич с атрофией мышц"]},{"n":190,"q":"На каком уровне волокна переднего корково-спинномозгового тракта переходят на противоположную сторону","a":["Верно: на уровне сегментов спинного мозга. Этот путь перекрещивается постепенно, посегментно, в передней белой спайке. Латеральный путь, наоборот, перекрещивается сразу, в продолговатом мозге"]},{"n":191,"q":"Волокна какого проводящего пути входят в состав перекреста пирамид","a":["Верно: латерального корково-спинномозгового тракта. На перекрест уходит около восьмидесяти процентов волокон пирамидного пути. Поэтому очаг в одном полушарии вызывает паралич противоположной половины тела"]},{"n":192,"q":"Какую функцию выполняет экстрапирамидная система","a":["Верно: осуществление непроизвольных движений. Она отвечает за тонус, позу, автоматизмы и готовность мышц к движению. При её поражении возникают дрожание, скованность и лишние движения, как при болезни Паркинсона"]},{"n":193,"q":"Каковы функции пучка Монакова","a":["Верно: регуляция мышечного тонуса, необходимого для удерживания тела в состоянии равновесия. Пучок Монакова это красноядерно-спинномозговой путь. Он работает без участия воли, согласуя тонус сгибателей и разгибателей"]},{"n":194,"q":"Где берет начало покрышечно-спинномозговой путь","a":["Верно: в верхних и нижних холмиках среднего мозга. Это крыша, то есть покрышка среднего мозга. Путь обеспечивает защитные движения на внезапный свет и звук, например резкий поворот головы и вздрагивание"]},{"n":195,"q":"Какова функция ретикулярно-спинномозгового тракта","a":["Верно: регуляция тонуса скелетных мышц в зависимости от изменяющихся условий внешней среды. Он начинается от ретикулярной формации ствола, которая задаёт уровень бодрствования. Поэтому во сне тонус мышц падает, а при испуге мгновенно растёт"]},{"n":196,"q":"Укажите место расположения первого нейрона корково-мостомозжечкового тракта","a":["Верно: нейроны всех долей коры полушарий. Волокна собираются со всей коры и идут через внутреннюю капсулу к мосту. Это самый массивный нисходящий путь, он намного крупнее пирамидного"]},{"n":197,"q":"Где находится второй нейрон корково-мостомозжечкового пути","a":["Верно: в собственных ядрах моста. Их аксоны перекрещиваются и через среднюю ножку входят в кору противоположного полушария мозжечка. Поэтому полушарие мозга работает в паре с противоположным полушарием мозжечка"]},{"n":198,"q":"Какова функция корково-мостомозжечкового тракта","a":["Верно: контроль функций мозжечка. Кора сообщает мозжечку о задуманном движении, а мозжечок сверяет замысел с выполнением. Остальные варианты описывают работу самого мозжечка, а не задачу тракта"]}],"sources":["Файл с вопросами, присланный преподавателем","Привес М. Г., Лысенков Н. К., Бушкович В. И. Анатомия человека","Пальчун В. Т., Магомедов М. М., Лучихин Л. А. Оториноларингология"]}];
